def _cos_pi_tn(t_n: float = 0.0) -> float:
    return math.cos(math.pi * t_n)

def _ua_layer_density(layer: int, t_n: float = 0.0) -> float:
    rho = RHO_SCM
    if layer == 1:
        return rho
    if layer == 2:
        return rho * (1.0 + BETA_I * _cos_pi_tn(t_n))
    if layer == 3:
        return rho * (1.0 + BETA_I * _cos_pi_tn(t_n)) * (1.0 + 0.1 * (layer - 2))
    return rho * (1.0 + BETA_I * _cos_pi_tn(t_n)) * (1.0 + 0.1 * (layer - 2)) + 0.1 * rho

def _triadic_g(M: float = DEFAULT_M, r: float = DEFAULT_R, t_n: float = 0.0) -> float:
    g_comp = (RHO_SCM * M / (r * r)) * (1.0 + SSQ)
    g_res = g_comp * PHI_RESONANCE
    g_buoy = (RHO_SCM * M / r) * (1.0 + K_Ub * _cos_pi_tn(t_n))
    return W_C * g_comp + W_R * g_res + W_B * g_buoy

def _triadic_g_decomposed(M: float = DEFAULT_M, r: float = DEFAULT_R, t_n: float = 0.0) -> Dict[str, Any]:
    g_comp = (RHO_SCM * M / (r * r)) * (1.0 + SSQ)
    g_res  = g_comp * PHI_RESONANCE
    g_buoy = (RHO_SCM * M / r) * (1.0 + K_Ub * _cos_pi_tn(t_n))
    triadic = W_C * g_comp + W_R * g_res + W_B * g_buoy
    parts = [g_comp, g_res, g_buoy]
    abs_max = max(abs(v) for v in parts)
    abs_min = min(abs(v) for v in parts)
    agreement_pct = ((abs_max - abs_min) / abs_max * 100.0) if abs_max != 0 else 0.0
    g_canonical_8term  = _g_compressed(M, r, t_n)
    g_master_resonance = _g_resonance(M, r, t_n)
    cross_vals = [abs(triadic), abs(g_canonical_8term), abs(g_master_resonance)]
    cmax = max(cross_vals); cmin = min(cross_vals)
    cross_agreement_pct = ((cmax - cmin) / cmax * 100.0) if cmax != 0 else 0.0
    return {
        "triadic": triadic,
        "g_comp": g_comp,
        "g_res": g_res,
        "g_buoy": g_buoy,
        "agreement_pct": agreement_pct,
        "weights": {"w_C": W_C, "w_R": W_R, "w_B": W_B},
        "cross_master_g_compressed_8term": g_canonical_8term,
        "cross_master_g_resonance": g_master_resonance,
        "cross_method_agreement_pct": cross_agreement_pct,
    }

def _f_u_bi(M: float = DEFAULT_M, r: float = DEFAULT_R, t_n: float = 0.0) -> float:
    return (RHO_SCM * M / r) * (1.0 + BETA_I * _cos_pi_tn(t_n) + SSQ)

def _f_u_bi_i(M: float = DEFAULT_M, r: float = DEFAULT_R, layers: int = 4, t_n: float = 0.0) -> float:
    total = 0.0
    for L in range(1, layers + 1):
        ua = _ua_layer_density(L, t_n)
        total += ua * M / (r * r) * (1.0 + 0.05 * L)
    return total * (1.0 + K_Ub * _cos_pi_tn(t_n))

def _scm(level: int = 1, t_n: float = 0.0) -> float:
    base = RHO_SCM * (1.0 + 0.01 * (level - 1))
    return base * (1.0 + 0.2 * _cos_pi_tn(t_n))

def _resonant_adpm(omega: float = OMEGA_SCM, t_n: float = 0.0) -> float:
    base = omega * _cos_pi_tn(t_n) * PHI_RESONANCE
    return base

def _vacuum_ledger_4term() -> float:
    amp = G8_26_BARRIER
    v0   = RHO_SCM * amp * G1_K
    r26  = RHO_SCM * amp * G3_RICCI_COEF
    kk   = RHO_SCM * amp * G2_BETA_BASE
    bsfg = RHO_SCM * amp * G4_BSFG_COEF
    return v0 + r26 + kk + bsfg

PLANCK_LAMBDA_TARGET_J_M3 = 5.95e-10

V_UA_PAPER_1170 = math.sqrt(1.0e23)
RHO_KK_PAPER_1171_ZETA = 5.951e-10

def _V0_explicit_paper_1170():
    return K_MEX * RHO_SCM

def _rho_R26_explicit_paper_1170():
    return (13.0 / 2.0) * (V_UA_PAPER_1170 ** 2) * RHO_SCM

def _rho_KK_explicit_paper_1171():
    return RHO_KK_PAPER_1171_ZETA

def _rho_BSFG_residual_paper_1170():
    total = K_MEX * RHO_SCM * float(G8_26_BARRIER)
    return total - (_V0_explicit_paper_1170()
                    + _rho_R26_explicit_paper_1170()
                    + _rho_KK_explicit_paper_1171())

def _vacuum_ledger_paper_1170_explicit():
    v0   = _V0_explicit_paper_1170()
    r26  = _rho_R26_explicit_paper_1170()
    kk   = _rho_KK_explicit_paper_1171()
    bsfg = _rho_BSFG_residual_paper_1170()
    total = v0 + r26 + kk + bsfg
    return {
        "V0_mexican_hat":        v0,
        "rho_R26_curvature":     r26,
        "rho_KK_zeta_reg":       kk,
        "rho_BSFG_residual":     bsfg,
        "total":                 total,
        "planck_target":         PLANCK_LAMBDA_TARGET_J_M3,
        "residual_pct":          (total - PLANCK_LAMBDA_TARGET_J_M3) / PLANCK_LAMBDA_TARGET_J_M3 * 100.0,
    }

def _vacuum_ledger_4term_decomposed() -> Dict[str, float]:
    amp = G8_26_BARRIER
    v0 = RHO_SCM * amp * G1_K
    r26 = RHO_SCM * amp * G3_RICCI_COEF
    kk = RHO_SCM * amp * G2_BETA_BASE
    bsfg = RHO_SCM * amp * G4_BSFG_COEF
    total = v0 + r26 + kk + bsfg
    planck = PLANCK_LAMBDA_TARGET_J_M3
    residual_pct = (total - planck) / planck * 100.0
    return {
        "V0": v0,
        "R26_term": r26,
        "rho_KK": kk,
        "rho_BSFG": bsfg,
        "total": total,
        "planck_target": planck,
        "residual_pct": residual_pct,
    }


def _w_sector_from_variational_principle():
    return -1.0

def _w_R26():           return _w_sector_from_variational_principle()
def _w_KK():            return _w_sector_from_variational_principle()
def _w_BSFG():          return _w_sector_from_variational_principle()
def _w_mexican_hat():   return _w_sector_from_variational_principle()

def _rho_sector_at_z(rho_0, w_sector, z):
    one_plus_z = 1.0 + z
    exponent = 3.0 * (1.0 + w_sector)
    return rho_0 * (one_plus_z ** exponent)

def _rho_R26_term_uqff(z=0.0):
    rho_0 = RHO_SCM * G8_26_BARRIER * G3_RICCI_COEF
    return _rho_sector_at_z(rho_0, _w_R26(), z)

def _rho_KK_uqff(z=0.0):
    rho_0 = RHO_SCM * G8_26_BARRIER * G2_BETA_BASE
    return _rho_sector_at_z(rho_0, _w_KK(), z)

def _rho_BSFG_uqff(z=0.0):
    rho_0 = RHO_SCM * G8_26_BARRIER * G4_BSFG_COEF
    return _rho_sector_at_z(rho_0, _w_BSFG(), z)

def _rho_mexican_hat_uqff(z=0.0):
    rho_0 = RHO_SCM * G8_26_BARRIER * G1_K
    return _rho_sector_at_z(rho_0, _w_mexican_hat(), z)

def _rho_DE_uqff(z=0.0):
    return (_rho_R26_term_uqff(z) + _rho_KK_uqff(z)
            + _rho_BSFG_uqff(z) + _rho_mexican_hat_uqff(z))

def _p_DE_uqff(z=0.0):
    p = (_w_R26()        * _rho_R26_term_uqff(z)
         + _w_KK()         * _rho_KK_uqff(z)
         + _w_BSFG()       * _rho_BSFG_uqff(z)
         + _w_mexican_hat()* _rho_mexican_hat_uqff(z))
    return p

def _drho_DE_dz_uqff(z=0.0, h=1.0e-4):
    return (_rho_DE_uqff(z + h) - _rho_DE_uqff(z - h)) / (2.0 * h)

def _w_z_uqff(z=0.0):
    rho = _rho_DE_uqff(z)
    if rho == 0.0:
        return float("nan")
    drho_dz = _drho_DE_dz_uqff(z)
    return ((1.0 + z) / (3.0 * rho)) * drho_dz - 1.0

def _w_0_uqff():
    return _w_z_uqff(0.0)

def _w_a_uqff():
    return _w_z_uqff(1.0) - _w_z_uqff(0.0)

def _dw_dz_uqff(z=0.0, h=1.0e-3):
    return (_w_z_uqff(z + h) - _w_z_uqff(z - h)) / (2.0 * h)

def _d2w_dz2_uqff(z=0.0, h=1.0e-3):
    return (_w_z_uqff(z + h) - 2.0 * _w_z_uqff(z) + _w_z_uqff(z - h)) / (h * h)

E0_QUANTUM_CHAIN_J = 1.0e-20
N_QUANTUM_LEVELS   = 26
HUBBLE_RADIUS_M    = 1.373e26
BOHR_RADIUS_M      = 5.29177210903e-11

def _derive_rho_scm_from_quantum_chain() -> Dict[str, float]:
    sum_E_n = E0_QUANTUM_CHAIN_J * 10.0 * (10.0**N_QUANTUM_LEVELS - 1.0) / 9.0
    peak_E_n = E0_QUANTUM_CHAIN_J * 10.0**N_QUANTUM_LEVELS
    V_universe = (4.0 / 3.0) * math.pi * HUBBLE_RADIUS_M**3
    V_hydrogen = (4.0 / 3.0) * math.pi * BOHR_RADIUS_M**3
    rho_chain_cosm = sum_E_n / V_universe
    rho_chain_atom = sum_E_n / V_hydrogen
    legacy = RHO_SCM
    ratio = legacy / rho_chain_cosm if rho_chain_cosm > 0 else float("inf")
    return {
        "E_0_J": E0_QUANTUM_CHAIN_J,
        "n_levels": float(N_QUANTUM_LEVELS),
        "sum_E_n_J": sum_E_n,
        "peak_E_n_J": peak_E_n,
        "V_universe_m3": V_universe,
        "V_hydrogen_m3": V_hydrogen,
        "rho_chain_cosmological_J_m3": rho_chain_cosm,
        "rho_chain_atomic_J_m3": rho_chain_atom,
        "rho_scm_legacy_J_m3": legacy,
        "legacy_over_chain_cosmological_ratio": ratio,
    }

def _vacuum_ledger_literal_forms() -> Dict[str, float]:
    rs = RHO_SCM
    v0_lit   = (25.0 / 12.0) * rs
    r26_lit  = G3_RICCI_COEF * rs
    bsfg_lit = G4_BSFG_COEF * rs
    zeta_26 = 0.0
    for k in range(1, 201):
        zeta_26 += 1.0 / (k**N_QUANTUM_LEVELS)
    rho_kk_lit = zeta_26 / (float(N_QUANTUM_LEVELS) ** N_QUANTUM_LEVELS)
    total_lit = v0_lit + r26_lit + rho_kk_lit + bsfg_lit
    planck = PLANCK_LAMBDA_TARGET_J_M3
    residual_lit_pct = (total_lit - planck) / planck * 100.0
    total_amp = _vacuum_ledger_4term()
    ratio = total_amp / total_lit if total_lit > 0 else float("inf")
    return {
        "V0_literal": v0_lit,
        "R26_term_literal": r26_lit,
        "rho_KK_literal": rho_kk_lit,
        "rho_BSFG_literal": bsfg_lit,
        "total_literal": total_lit,
        "planck_target": planck,
        "residual_literal_pct": residual_lit_pct,
        "total_amplified_step7": total_amp,
        "amplified_over_literal_ratio": ratio,
    }

UA_BRACKET_DIMLESS = 1.0e-4
PLASMOID_LOCAL_SCM_KG_M3 = 1.0e15
NUCLEON_MASS_KG_ANCHOR   = 1.67262192e-27

def _mass_from_vacuum_5path() -> Dict[str, float]:
    c2 = C_LIGHT * C_LIGHT
    path1_per_c2_kg_m3 = RHO_SCM / c2

    rho_vacuum         = RHO_SCM * S26_DPM
    buoyancy_denom     = BETA0_DPM * UA_BRACKET_DIMLESS
    ratio              = rho_vacuum / buoyancy_denom
    dim_gain           = ratio * (float(D_CRIT) / float(D_BSFG)) ** 2
    ledger_saturation  = 1.0 / (8.0 * math.pi * dim_gain)
    kg_unit_per_m3     = rho_vacuum * ledger_saturation

    mamu_raw            = RHO_SCM * A_26
    mamu_per_c2_kg_m3   = mamu_raw / c2
    mamu_anchor_kg      = 1.627e-27
    mamu_ratio_vs_anchor = mamu_per_c2_kg_m3 / mamu_anchor_kg

    m_n_ladder_peak_kg  = (E0_QUANTUM_CHAIN_J * 10.0 ** N_QUANTUM_LEVELS) / c2
    m_n_at_n9_kg        = (E0_QUANTUM_CHAIN_J * 10.0 ** 9) / c2
    m_n_at_n11_kg       = (E0_QUANTUM_CHAIN_J * 10.0 ** 11) / c2
    m_n_at_n18_kg       = (E0_QUANTUM_CHAIN_J * 10.0 ** 18) / c2

    rho_local_anchor    = PLASMOID_LOCAL_SCM_KG_M3
    plasmoid_amp        = rho_local_anchor / path1_per_c2_kg_m3

    alpha_inv           = 137.035999084
    alpha               = 1.0 / alpha_inv
    f_u_closure_ratio   = ledger_saturation / alpha
    f_u_residual_pct    = (f_u_closure_ratio - 1.0) * 100.0

    return {
        "path1_per_c2_kg_m3":              path1_per_c2_kg_m3,
        "path2_rho_vacuum_J_m3":           rho_vacuum,
        "path2_ledger_saturation":         ledger_saturation,
        "path2_kg_unit_per_m3":            kg_unit_per_m3,
        "path3_mamu_raw_product":          mamu_raw,
        "path3_mamu_per_c2_kg_m3":         mamu_per_c2_kg_m3,
        "path3_mamu_anchor_kg":            mamu_anchor_kg,
        "path3_mamu_ratio_vs_anchor":      mamu_ratio_vs_anchor,
        "path4_m26_peak_kg":               m_n_ladder_peak_kg,
        "path4_m_n9_kg":                   m_n_at_n9_kg,
        "path4_m_n11_kg":                  m_n_at_n11_kg,
        "path4_m_n18_higgs_slot_kg":       m_n_at_n18_kg,
        "path5_rho_local_anchor_kg_m3":    rho_local_anchor,
        "path5_plasmoid_amplification":    plasmoid_amp,
        "f_u_alpha":                       alpha,
        "f_u_closure_ratio":               f_u_closure_ratio,
        "f_u_residual_pct":                f_u_residual_pct,
    }

def _g1_mexican_hat() -> float:
    return G1_K

def _g2_kk_beta(i: int = 0) -> float:
    return 3.0 * (5.0 - i) / 20.0

def _g3_einstein_ricci() -> float:
    return G3_RICCI_COEF

def _g3_kk_spinor_closure() -> Dict[str, float]:
    ricci_coef = G3_RICCI_COEF
    kk_internal_dims = D_CRIT - D_BSFG
    kk_leading_suppress = 1.0 / G8_26_BARRIER
    kk_correction = kk_internal_dims * kk_leading_suppress
    spinor_so26_dim = 2 ** (D_CRIT // 2)
    spinor_per_dim = spinor_so26_dim / D_CRIT
    spinor_correction = 1.0 / spinor_per_dim
    g3_total = ricci_coef * (1.0 + kk_correction + spinor_correction)
    closure_diff_pct = (g3_total - ricci_coef) / ricci_coef * 100.0
    return {
        "ricci_coef": ricci_coef,
        "kk_internal_dims": float(kk_internal_dims),
        "kk_leading_suppression": kk_leading_suppress,
        "kk_correction": kk_correction,
        "spinor_so26_dim": float(spinor_so26_dim),
        "spinor_per_dim": spinor_per_dim,
        "spinor_correction": spinor_correction,
        "g3_kk_spinor_total": g3_total,
        "closure_diff_pct": closure_diff_pct,
    }

def _g4_bsfg() -> float:
    return G4_BSFG_COEF

def _g5_kk_suppress() -> float:
    return 1.0 / G8_26_BARRIER

def _g6_phi_res() -> float:
    return G1_K

def _g8_26_barrier() -> float:
    return G8_26_BARRIER

def _master_lagrangian(R_26: float = 1.0,
                       kappa_E: float = None,
                       F_DPM_sq: float = 1.0,
                       U_g: list = None,
                       U_b: list = None,
                       U_m_abs: float = 1.0,
                       UA_kinetic_g_dd_UA: float = 0.0,
                       U_A: float = 1.0,
                       v_UA: float = 1.0,
                       rho_SCm_val: float = None) -> Dict[str, float]:
    if kappa_E is None:
        kappa_E = 8.0 * math.pi * G_NEWTON / (C_LIGHT ** 4)
    if U_g is None:
        U_g = [1.0, 1.0, 1.0, 1.0]
    if U_b is None:
        U_b = [1.0, 1.0, 1.0, 1.0]
    if len(U_g) != 4 or len(U_b) != 4:
        raise ValueError("PAPER_1167 requires 4-element U_g and U_b vectors")
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val

    beta = [3.0 * (5 - i) / 20.0 for i in (1, 2, 3, 4)]
    T1 = R_26 / (2.0 * kappa_E)
    T2 = -0.25 * F_DPM_sq
    T3 = sum(beta[i] * U_g[i] * U_b[i] for i in range(4))
    T4 = -0.5 * U_m_abs * U_m_abs
    T5 = -0.5 * UA_kinetic_g_dd_UA
    T6 = -(25.0 / 12.0) * rsc * (((U_A / max(v_UA, 1e-300)) ** 2) - 1.0) ** 2
    L_total = T1 + T2 + T3 + T4 + T5 + T6
    return {
        "T1_R26_over_2kappaE":      T1,
        "T2_DPM_gauge_neg_quarter": T2,
        "T3_interaction_sum":       T3,
        "T4_Um_self_energy":        T4,
        "T5_UA_kinetic":            T5,
        "T6_UA_mexican_hat":        T6,
        "L_FU_total":               L_total,
        "kappa_E_used":             kappa_E,
        "beta_i_ladder":            beta,
        "beta_sum":                 sum(beta),
        "F_TRZ":                    1.0 / 10.0,
        "L_GR":                     T1,
        "L_DPM":                    T2,
        "L_interaction":            T3,
        "L_SCm":                    T6,
        "L_UQFF_total":             L_total,
    }

def _g_compressed(M: float = DEFAULT_M, r: float = DEFAULT_R, t_n: float = 0.0) -> float:
    Ug1 = G_NEWTON * M / (r * r)
    Ug2 = Ug1 * SSQ
    Ug3 = Ug1 * BETA_I * _cos_pi_tn(t_n)
    Ug4 = RHO_SCM * M / r
    psi = PHI_RESONANCE * Ug1
    phi = G1_K * Ug2
    quantum_integral = PLANCK_H * OMEGA_SCM / (r * r * r)
    buoyancy_fluid   = RHO_SCM * (4.0 / 3.0) * math.pi * r * r * r
    return Ug1 + Ug2 + Ug3 + Ug4 + psi + phi + quantum_integral + buoyancy_fluid

def _g_resonance(M: float = DEFAULT_M, r: float = DEFAULT_R, t_n: float = 0.0) -> float:
    a_dpm     = RHO_SCM * M / (r * r)
    a_thz     = OMEGA_SCM * a_dpm
    a_aether  = (RHO_UA / RHO_SCM) * a_dpm * PHI_RESONANCE
    f_trz     = 0.1
    lambda_i  = G1_K
    mod       = _cos_pi_tn(t_n)
    return (a_dpm + a_thz + a_aether) * lambda_i * (1.0 + f_trz) * mod

def _ua_4layer_explicit(t_n: float = 0.0, p_t: float = 1.0,
                        beta_t: float = BETA_I) -> Dict[str, float]:
    ua1 = RHO_SCM
    ua2 = p_t * beta_t * _cos_pi_tn(t_n)
    ua3 = RHO_UA * 0.1
    ua4 = ua1 + ua2 + ua3
    return {"UA_prime": ua1, "UA_double": ua2, "UA_triple": ua3, "UA_quad": ua4}

def _u_mi(t: float = 1.0, r: float = DEFAULT_R, n: int = 1,
          gamma: float = GAMMA, t_n: float = 0.0,
          M: float = DEFAULT_M) -> float:
    base = RHO_SCM * M / (r * r) * n
    return base * (1.0 - math.exp(-gamma * t * _cos_pi_tn(t_n)))

def _f_u_bi_i_steps(M: float = DEFAULT_M, r: float = DEFAULT_R,
                    V: float = None, t_n: float = 0.0) -> Dict[str, float]:
    if V is None:
        V = (4.0 / 3.0) * math.pi * r * r * r
    g_local           = G_NEWTON * M / (r * r)
    step1_archimedes  = RHO_SCM * V * g_local
    step2_lep         = step1_archimedes * (1.0 + SSQ)
    step3_qwave       = step2_lep * PLANCK_H * OMEGA_SCM / EV_J
    step4_compressed  = step3_qwave * (1.0 + K_Ub * _cos_pi_tn(t_n))
    return {"step1_archimedes":   step1_archimedes,
            "step2_lep_scaling":  step2_lep,
            "step3_qwave_thz":    step3_qwave,
            "step4_g_compressed": step4_compressed,
            "total":              step4_compressed}

def _rho_scm_energy_density() -> float:
    return RHO_SCM

def _rho_ua_energy_density() -> float:
    return RHO_UA

def _rho_scm_mass_equiv() -> float:
    return RHO_SCM / (C_LIGHT * C_LIGHT)

def _rho_ua_mass_equiv() -> float:
    return RHO_UA / (C_LIGHT * C_LIGHT)

def _compute_rho_vac_energy(f_i: float, E_n: float, V: float) -> float:
    return (f_i * E_n) / V

def _l94_higgs_off_shell_width_ratio(R_scm: float = None) -> float:
    if R_scm is None:
        R_scm = BETA_I * SSQ * PHI_RESONANCE
    return 1.0 + R_scm

def _l94_higgs_mass_ncg_uqff() -> float:
    lambda_H = 1.79e18 * SSQ
    v_scm_proxy = (RHO_SCM * S_26 * PHI_RESONANCE) ** 0.5
    return (2.0 * lambda_H * v_scm_proxy * v_scm_proxy) ** 0.5

def _l94_polyakov_string_tension() -> float:
    return RHO_SCM * (S_26 ** 3) * PHI_RESONANCE

def _l94_calabi_yau_kahler_potential(t1: float = 1.0, t2: float = 1.0, t3: float = 1.0) -> float:
    s = SSQ
    li26 = 0.0
    s_pow = 1.0
    for n in range(1, 41):
        s_pow *= s
        li26 += s_pow / (n ** 26)
    prod_t = (2.0 * t1) * (2.0 * t2) * (2.0 * t3)
    return -math.log(li26 * prod_t)

def _l94_inflation_lagrangian(Ug: float = 1.0, Omega: float = 1.0,
                               M: float = M_SUN, d: float = DEFAULT_R,
                               UA: float = 1.0e-4, Fn: float = 1.0,
                               Phi: float = PHI_RESONANCE) -> float:
    return -BETA_I * Ug * Omega * (M / d) * UA + Fn * Phi

def _l94_cmb_lagrangian(Ug_list: List[float] = None, Omega_g: float = 1.0,
                         M: float = M_SUN, dg: float = DEFAULT_R,
                         UA: float = 1.0e-4, Fn: float = 1.0) -> float:
    if Ug_list is None:
        Ug_list = [1.0, 1.0, 1.0, 1.0]
    sum_ug = sum(Ug_list)
    return -BETA_I * sum_ug * Omega_g * (M / dg) * UA + Fn * (F_THZ / OMEGA_SCM) * PHI_RESONANCE

def _l94_rho_de_time(t: float = 0.0, Gamma: float = 1.0, R: float = 1.0) -> float:
    kappa = 5.787e-9
    rho_scm_t = RHO_SCM * S_26 * math.exp((kappa + SSQ / 26.0) * t)
    return rho_scm_t * S_26 * Gamma * (2.0 * R - 1.0)

def _l94_w_de_time(t: float = 0.0, Gamma: float = 1.0) -> float:
    if abs(Gamma - 1.0) < 1e-12 or t == 0.0:
        return -1.0
    kappa = 5.787e-9
    num = 2.0 * kappa * t + SSQ * t / 26.0
    den = math.log(Gamma)
    return -1.0 + num / den

def _l94_hubble_modulated(t: float = 0.0, Gamma: float = 1.0,
                           H_0: float = 67.4, E_net: float = 1.0,
                           F_U: float = 1.0) -> float:
    if F_U == 0.0:
        return H_0
    return H_0 * (1.0 + (Gamma * PHI_RESONANCE) / F_U * E_net)

def _l94_swampland_wgc_bound(g: float = 1.0, M_Pl: float = 2.176434e-8) -> float:
    return g * M_Pl * (1.0 + BETA_I * (S_26 ** 3))

def _l94_cmera_entropy(L: float = 1.0, eps: float = 1.0e-35,
                        c_central: float = 1.0, l_scm: float = 1.0) -> float:
    if eps <= 0.0 or L <= 0.0:
        return 0.0
    base = (c_central / 3.0) * math.log(L / eps)
    corr = 1.0 + BETA_I * (S_26 ** 3) * PHI_RESONANCE * eps / max(l_scm, 1e-300)
    return base * corr

def _l94_qec_phonon_error_floor(omega_qubit: float = 5.0e9) -> float:
    if omega_qubit <= 0.0:
        return 0.0
    return BETA_I * (S_26 ** 3) * SSQ * (OMEGA_SCM / omega_qubit) ** 2

def _l94_ncg_spectral_triple_dirac_shift() -> float:
    return BETA_I * (S_26 ** 3) * PHI_RESONANCE

def _l94_cgc_bk_saturation_correction(alpha_s: float = 0.3) -> float:
    return 1.0 + BETA_I * (S_26 ** 3) * PHI_RESONANCE * alpha_s

def _l94_gw_strain_modifier(f_hz: float = 100.0, alpha: float = 1.0,
                             f_scm: float = F_THZ) -> float:
    if f_scm <= 0.0:
        return 1.0
    return 1.0 - BETA_I * (S_26 ** 3) * PHI_RESONANCE * (f_hz / f_scm) ** alpha

def _l94_bh_shadow_phonon_correction(M_kg: float = M_SUN) -> float:
    r_ph_gr = 3.0 * math.sqrt(3.0) * G_NEWTON * M_kg / (C_LIGHT * C_LIGHT)
    return r_ph_gr * (1.0 + BETA_I * (S_26 ** 3) * SSQ * PHI_RESONANCE)

def _l94_gup_minimum_length() -> float:
    ell_Pl = math.sqrt(PLANCK_H / (2.0 * math.pi) * G_NEWTON / (C_LIGHT ** 3))
    correction = 1.0 + BETA_I * (S_26 ** 3) * 1.0e-78
    return ell_Pl * math.sqrt(correction)

def _l94_qgp_alice_dnch_deta(Npart: float = 383.0, alpha_s: float = 0.3,
                              SCm_ratio: float = SSQ) -> float:
    buoy = 1.0 + BETA_I * (S_26 ** 3)
    return Npart * alpha_s * (1.0 + SCm_ratio) * buoy

def _l94_scm_ua_duality(F_scm: float = 1.0, F_ua: float = 0.0) -> Dict[str, Any]:
    F = F_scm - F_ua
    if F > 1e-30:
        regime = "EXPANSION"
    elif F < -1e-30:
        regime = "COLLAPSE"
    else:
        regime = "EQUILIBRIUM"
    ratio = F_scm / F_ua if F_ua != 0.0 else float("inf")
    return {"value": F, "regime": regime, "ratio": ratio,
            "F_SCm": F_scm, "F_UA": F_ua}

def _l94_cosmic_quantum_egg_partition(n_max: int = 26) -> Dict[str, Any]:
    levels = []
    vds_sum = 0.0
    bh_sum = 0.0
    for n in range(1, n_max + 1):
        vds_n = (SSQ ** n) / (n ** 26)
        bh_n = 1.0 / (n ** 26) - vds_n
        levels.append({"n": n, "vds": vds_n, "bh": bh_n,
                        "partition_sum": vds_n + bh_n,
                        "partition_id_holds": abs((vds_n + bh_n) - 1.0 / (n ** 26)) < 1e-300})
        vds_sum += vds_n
        bh_sum += bh_n
    return {"levels": levels, "vds_total": vds_sum, "bh_total": bh_sum,
            "total": vds_sum + bh_sum, "n_max": n_max}

def _l94_cos_pitn_net_zero_integral(N: int = 1000) -> Dict[str, float]:
    if N <= 0:
        N = 1000
    h = 1.0 / N
    total = 0.0
    for k in range(N):
        x = (k + 0.5) * h
        total += math.cos(math.pi * x)
    numerical = total * h
    analytic = (math.sin(math.pi) - math.sin(0.0)) / math.pi
    return {"numerical": numerical, "analytic": analytic,
            "residual": numerical - analytic, "N": N}

def _l95_A26_sextic_sum() -> int:
    return sum(i ** 6 for i in range(1, 27))

def _l95_M_AMU_dpm() -> float:
    return RHO_SCM * _l95_A26_sextic_sum()

def _l95_Lambda_uqff_closed(H_0: float = 67.4 * 1000.0 / 3.0857e22) -> float:
    return (18.0 / 5.0) * SSQ * (H_0 ** 2) / (C_LIGHT ** 2)

def _l95_H0_asymmetry_ratio() -> float:
    return 2.268e-18 / 2.184e-18

def _l95_g6_phi_res_closed() -> float:
    return (D_BSFG - 1.0) / D_BSFG

def _l95_g7_ftrz_closed() -> float:
    return 1.0 / 120.0

def _l95_g8_26factorial() -> float:
    p = 1.0
    for k in range(1, 27):
        p *= k
    return p

def _l95_g5_kk_tower_sum(n_max: int = 100) -> float:
    total = 0.0
    for n in range(1, n_max + 1):
        total += 1.0 / (n * (n + 25)) ** 26
    return total

def _l95_g4_moduli_mass_sq(i: int = 1) -> float:
    return 1.0 / (i ** 26)

def _l95_g4_moduli_tau_star(i: int = 1) -> float:
    return SSQ ** i

def _l95_g2_beta_i_ladder(i: int = 1) -> float:
    return 3.0 * (5 - i) / 20.0

def _l95_g1_mexhat_K() -> float:
    return PHI_RESONANCE

def _l95_l_uqff_master_synthesis(R26: float = 1.0, F_sq: float = 1.0,
                                  Ug_Ub_sum: float = 1.0, Um_sq: float = 1.0,
                                  dUA_sq: float = 1.0, UA_ratio: float = 1.0) -> float:
    kappa = 1.0
    return (R26 / (2.0 * kappa) - F_sq / 4.0 + Ug_Ub_sum
            - 0.5 * Um_sq - 0.5 * dUA_sq
            - (25.0 / 12.0) * RHO_SCM * (UA_ratio ** 2 - 1.0) ** 2)

def _l95_rho_lambda_closed_4term(V0: float = 0.0, R26_term: float = 0.0,
                                  rho_kk: float = 0.0, rho_bsfg: float = 0.0) -> float:
    return V0 + R26_term + rho_kk + rho_bsfg

def _l95_rho_kk_hbar_tracked(m1c2_J: float = 0.16e-3 * 1.602176634e-19) -> float:
    hbar = PLANCK_H / (2.0 * math.pi)
    zeta5 = 1.0369277551433699
    return (3.0 * zeta5) / (128.0 * math.pi ** 6) * (D_CRIT / D_BSFG) ** 4 * \
           (m1c2_J ** 4) / (hbar * C_LIGHT) ** 3

def _l95_kk_lightest_meV() -> float:
    return 0.16

def _l95_l_kk_star_mm() -> float:
    return 1.23

def _l95_E_phonon_meV() -> float:
    eV = PLANCK_H * F_THZ / 1.602176634e-19
    return eV * 1000.0

def _l95_E_scm_phonon_eV(xi: float = 1.0) -> float:
    E_J = PLANCK_H * F_THZ * S26_DPM * PHI_RESONANCE * xi
    return E_J / 1.602176634e-19

def _l95_fubi_i_99sum_lenr(M: float = M_SUN, r: float = DEFAULT_R,
                            t_n: float = 0.0, Ug_uniform: float = 1.0) -> float:
    return sum(-BETA_I * Ug_uniform * math.cos(math.pi * t_n) * M / (r ** 2)
               for _ in range(99))

def _l95_parkhomov_P_excess(N: float = 2.0e18, eps_eV: float = 630.0,
                             kappa_day: float = 5.0e-4, t_hr: float = 1.0) -> float:
    eps_J = eps_eV * 1.602176634e-19
    t_day = t_hr / 24.0
    return N * eps_J * math.exp(-kappa_day * t_day)

def _l95_pons_fleischmann_P(N_ps: float = 1.0e20, eps_eV: float = 630.0,
                             f_b: float = PHI_RESONANCE) -> float:
    return N_ps * eps_eV * 1.602176634e-19 * f_b

def _l95_nambu_goto_vds26() -> float:
    return (SSQ ** 26) / (26 ** 26)

def _l95_type_iib_radius(i: int = 1, ell_s: float = 1.616e-35) -> float:
    return ell_s * (SSQ ** i)

def _l95_brane_tension(p: int = 3, T0: float = 8.66e-11, g_s: float = 1.0,
                        ell_s: float = 1.616e-35, t_n: float = 0.0) -> float:
    base = T0 / (g_s * (2.0 * math.pi * ell_s) ** p)
    return base * (1.0 + BETA_I * PHI_RESONANCE * abs(math.cos(math.pi * t_n)))

def _l95_heterotic_PL(t_n: float = 0.0) -> float:
    return 0.5 * (1.0 + math.cos(math.pi * t_n))

def _l95_heterotic_PR(t_n: float = 0.0) -> float:
    return 0.5 * (1.0 - math.cos(math.pi * t_n))

def _l95_m_theory_kappa11_sq(ell_s: float = 1.616e-35) -> float:
    return (ell_s ** 9) / (2.0 * RHO_SCM * S26_DPM * PHI_RESONANCE)

def _l95_joint_coeff_vds_dvp() -> float:
    def Lin(s, nmax=20):
        return sum((SSQ ** k) / (k ** s) for k in range(1, nmax + 1))
    w_vds = Lin(26) / max(Lin(25), 1e-300)
    w_dvp = SSQ ** 29
    return math.sqrt(max(w_vds * w_dvp, 0.0))

def _l95_higgs_potential_UH(t: float = 0.0, n: int = 18, omega_H: float = 1.0,
                             f_quasi: float = 0.01) -> float:
    lambda_H = 1.79e18
    return lambda_H * RHO_UA * omega_H * math.exp(-SSQ * n / 26.0) * (1.0 + f_quasi)

def _l95_scs_mu_string_tension(eta_GeV: float = 246.0, L_over_delta: float = 100.0) -> float:
    return (eta_GeV ** 2) * math.log(L_over_delta) * math.exp(-SSQ * 13.0 / 26.0)

def _l95_scs_radio_psd(Gmu: float = 1.0e-10, I: float = 1.0, f: float = 1.0e9,
                        d_m: float = 3.086e22) -> float:
    emiss = math.exp(-SSQ * 13.0 / 26.0)
    return Gmu * (C_LIGHT ** 2) * (I ** 2) * f / (4.0 * math.pi * d_m * d_m) * emiss

def _l95_scs_emission_factor() -> float:
    return math.exp(-SSQ * 13.0 / 26.0)

def _l95_scs_delta21cm(Gmu: float = 1.0e-10, T_S: float = 10.0) -> float:
    return Gmu * (C_LIGHT ** 2) / (K_B * T_S) * PHI_RESONANCE * RHO_SCM

def _l95_graphene_chiral_gap(Delta0: float = 1.0e-3, k_mag: float = 1.0, d: int = 2) -> float:
    return Delta0 * (k_mag ** d) * math.exp(-SSQ * 10.0 / 26.0)

def _l95_shock_S_t(M_mach: float = 3.0) -> float:
    return 4.0 * (M_mach ** 2)

def _l95_g_shock_total(M_solar: float = 1.0, r_m: float = DEFAULT_R,
                        M_mach: float = 3.0, C_release: float = 1.0) -> float:
    M_kg = M_solar * M_SUN
    return G_NEWTON * M_kg / (r_m ** 2) * _l95_shock_S_t(M_mach) + C_release

def _l95_dwarf_alpha_msigma() -> float:
    return 0.2

def _l95_Ug4_expulsion(dM_BH_kg: float = 1.0e6 * M_SUN, f_fb: float = 0.05) -> float:
    return RHO_SCM * abs(dM_BH_kg) * f_fb

def _l95_metallicity_grad_flat(grad_intrinsic: float = -0.1, lam_Edd: float = 0.1) -> float:
    return grad_intrinsic / (1.0 + 10.0 * lam_Edd)

def _l95_ns_sigma_n_density(sigma0: float = 1.0e-28, rho: float = 1.0e17,
                              rho0: float = 1.0e3) -> float:
    return sigma0 * (rho / rho0)

def _l95_lqg_area_phonon(j: float = 0.5, gamma_immirzi: float = 0.2375) -> float:
    hbar = PLANCK_H / (2.0 * math.pi)
    ell_P_sq = hbar * G_NEWTON / (C_LIGHT ** 3)
    return 8.0 * math.pi * gamma_immirzi * ell_P_sq * math.sqrt(j * (j + 1)) * S26_DPM * PHI_RESONANCE

def _l95_scm_string_action_26D(R_26: float = 1.0, F_sq: float = 1.0,
                                A_mu_sq: float = 1.0, t_n: float = 0.0,
                                L_phonon: float = 1.0, eta_rho_nu: float = 1.0) -> float:
    return (R_26 - 0.25 * F_sq
            + 0.5 * eta_rho_nu * A_mu_sq * math.cos(math.pi * t_n)
            + L_phonon)

def _l95_geo_folding_F26(x: float = 1.0) -> float:
    fact26 = _l95_g8_26factorial()
    return x * (fact26 ** (-1.0 / 13.0)) * S26_DPM * PHI_RESONANCE

def _l95_riemann_epsilon_bound(t_n: float = 0.5) -> float:
    return abs(1.0 - math.cos(math.pi * t_n)) * PHI_RESONANCE * (SSQ ** 26)

def _l95_fubi_i_7component_sum(F_phonon: float = 0.0, F_inflation: float = 0.0,
                                F_BCS: float = 0.0, F_VDS: float = 0.0,
                                F_DVP: float = 0.0, F_BSH: float = 0.0,
                                F_QCalcGeom: float = 0.0) -> float:
    return F_phonon + F_inflation + F_BCS + F_VDS + F_DVP + F_BSH + F_QCalcGeom

def _l95_l_de_buoyancy(R: float = 1.0, V_m3: float = 1.0e48) -> float:
    return RHO_SCM * (C_LIGHT ** 2) * S_26 * PHI_RESONANCE * (2.0 * R - 1.0) * V_m3

def _l95_l_horizon_bh_entropy(A_m2: float = 1.0, T_H: float = 1.0,
                                Delta_SCm: float = 8.283e-22) -> float:
    hbar = PLANCK_H / (2.0 * math.pi)
    ell_P_sq = hbar * G_NEWTON / (C_LIGHT ** 3)
    return A_m2 / (4.0 * ell_P_sq) * Delta_SCm / (K_B * max(T_H, 1e-300)) * S_26

def _l95_buoyancy_sector_template(Ug_list: List[float] = None,
                                   Omega_g: float = 1.0,
                                   M: float = M_SUN,
                                   d_g: float = DEFAULT_R,
                                   UA: float = 1.0e-4,
                                   F_n: float = 1.0e-10,
                                   Phi: float = PHI_RESONANCE,
                                   beta_i: float = BETA_I,
                                   s26_modulation: bool = False) -> dict:
    if Ug_list is None:
        Ug_list = [1.0, 1.0, 1.0, 1.0]
    s26_factor = S_26 if s26_modulation else 1.0
    L_buoy   = -beta_i * sum(Ug_list) * Omega_g * (M / max(d_g, 1e-300)) * UA * s26_factor
    L_phonon = F_n * Phi * s26_factor
    L_total  = L_buoy + L_phonon
    F_U_at_stationarity = 1.0 if abs(L_total) < 1e-30 * max(abs(L_buoy), abs(L_phonon), 1.0) else (
        1.0 + L_total / max(abs(L_phonon), 1e-300))
    return {"L_buoy": L_buoy, "L_phonon": L_phonon, "L_total": L_total,
            "dL_dphi": L_total, "F_U_at_stationarity": F_U_at_stationarity,
            "beta_i": beta_i, "s26_applied": s26_modulation}

def _l95_l_expansion(E_plus_t: float = 1.0, V_m3: float = 1.0e48) -> float:
    return E_plus_t * V_m3 * S_26

def _l95_l_erosion(E_minus_t: float = 1.0, V_m3: float = 1.0e48) -> float:
    return -abs(E_minus_t) * V_m3 * S_26

def _l95_l_e_of_t_unified(E_plus_t: float = 1.0, E_minus_t: float = 0.0,
                           V_m3: float = 1.0e48) -> dict:
    L_exp = _l95_l_expansion(E_plus_t, V_m3)
    L_ero = _l95_l_erosion(E_minus_t, V_m3)
    L_total = L_exp + L_ero
    if L_total > 1e-300:
        regime = "expansion"
    elif L_total < -1e-300:
        regime = "erosion"
    else:
        regime = "balanced"
    return {"L_expansion": L_exp, "L_erosion": L_ero, "L_total": L_total,
            "regime": regime}

def _l95_l_scm_e_t(t: float = 0.0, Gamma: float = 1.0, R: float = 1.0,
                    V_m3: float = 1.0e48, V_fil_m3: float = 1.0) -> float:
    return RHO_SCM * V_m3 * (C_LIGHT ** 2) * (2.0 * R - 1.0) * V_fil_m3 * S_26

def _l95_l_phonon(E_net: float = 1.0, V_m3: float = 1.0e-30) -> float:
    return E_net * V_m3 * PHI_RESONANCE * S_26

def _l95_l_stellar_wind(rho_w: float = 1.0e-13, v_w: float = 1.0e6,
                         M_star: float = M_SUN, d_neb: float = 1.0e16,
                         Ug_list: List[float] = None,
                         Omega_g: float = 1.0e-7, UA: float = 1.0e-4,
                         F_n: float = 1.0e-10) -> dict:
    base = _l95_buoyancy_sector_template(Ug_list, Omega_g, M_star, d_neb,
                                          UA, F_n, PHI_RESONANCE, BETA_I, False)
    ram = rho_w * v_w * v_w
    return {"L_template": base["L_total"], "ram_pressure_Pa": ram,
            "L_total_wind": base["L_total"] + ram,
            "F_U_at_stationarity": base["F_U_at_stationarity"]}

def _l95_l_merger_critical_radius(Ug_list: List[float] = None,
                                    M: float = M_SUN,
                                    F_n: float = 1.0e-10,
                                    Phi: float = PHI_RESONANCE,
                                    beta_i: float = BETA_I) -> dict:
    if Ug_list is None:
        Ug_list = [1.0, 1.0, 1.0, 1.0]
    sum_ug = sum(Ug_list)
    denom = abs(F_n * Phi)
    if denom < 1e-300:
        r_crit = float("inf")
    else:
        r_crit = 2.0 * beta_i * sum_ug * M / denom
    r_probe = max(r_crit * 0.5, 1.0e-30)
    L_buoy_probe = -beta_i * sum_ug * (M / r_probe) * 1.0e-4
    L_phon = F_n * Phi
    L_tot = L_buoy_probe + L_phon
    if abs(L_tot) < 1e-30 * max(abs(L_buoy_probe), abs(L_phon), 1.0):
        transition = "at_crit"
    elif L_tot < 0.0:
        transition = "pre_merger"
    else:
        transition = "post_merger"
    return {"r_crit_m": r_crit, "L_buoy_at_probe": L_buoy_probe,
            "L_phonon": L_phon, "L_total_probe": L_tot,
            "transition": transition}

def _l95_l_cooper_pair_bcs_gap(Delta_eV: float = 5.17e-3,
                                T_K: float = 300.0,
                                V_SCm: float = 1.0,
                                F_UBi: float = 1.0,
                                F_U: float = 1.0) -> dict:
    Delta_J = Delta_eV * EV_J
    if T_K <= 0.0 or F_U == 0.0:
        return {"lhs": 1.0, "rhs": float("inf"), "gap_residual": float("inf"),
                "T_c_K": None, "holds": False}
    x = Delta_J / (2.0 * K_B * T_K)
    x_capped = min(x, 700.0)
    tanh_val = math.tanh(x_capped)
    rhs = (V_SCm / 2.0) * tanh_val * Delta_J * S_26 * (F_UBi / F_U)
    gap_residual = rhs - 1.0
    target = 2.0 / max(V_SCm * Delta_J * S_26 * (F_UBi / F_U), 1e-300)
    if 0.0 < target < 1.0:
        T_c = Delta_J / (2.0 * K_B * math.atanh(target))
    else:
        T_c = None
    return {"lhs": 1.0, "rhs": rhs, "gap_residual": gap_residual,
            "T_c_K": T_c, "holds": abs(gap_residual) < 1e-30}

def _l95_l_lqg_spin_foam(j: float = 0.5, gamma_immirzi: float = 0.2375,
                          A_v_amplitude: float = 1.0,
                          F_n: float = 1.0e-10,
                          Phi: float = PHI_RESONANCE) -> dict:
    A_v = math.sqrt(2.0 * j + 1.0) * A_v_amplitude
    base = _l95_buoyancy_sector_template(F_n=F_n, Phi=Phi)
    L_self = (Phi * Phi) * gamma_immirzi
    return {"A_v_factor": A_v,
            "L_template": A_v * base["L_total"],
            "L_phonon_selfint": L_self,
            "L_total": A_v * base["L_total"] + L_self,
            "gamma_immirzi": gamma_immirzi}

def _l95_paper503_wolfram_lagrangian_symbolic() -> str:
    return ("LUQFF[t_, r_, phi_] := "
            "R26[r]/(2 kappaE) "
            "- (1/4) FDPM[t, r]^2 "
            "+ Sum[(3 (5 - i)/20) Ug[i] Ub[i], {i, 1, 4}] "
            "- (1/2) Um[t, r]^2 "
            "- (1/2) gMuNu[r] D[UA[t, r], t] D[UA[t, r], t] "
            "- (25/12) rhoSCm ((UA[t, r]/vUA)^2 - 1)^2 "
            "+ Sum[Lsector[s, t, r, phi], {s, sectorList}]")

def _l95_l_uqff_master_sum(L_GR: float = 0.0, L_SCm: float = 0.0,
                            L_phonon: float = 0.0, L_interaction: float = 0.0,
                            sector_contribs: List[float] = None) -> dict:
    if sector_contribs is None:
        sector_contribs = []
    L_sectors = sum(float(x) for x in sector_contribs)
    L_total = L_GR + L_SCm + L_phonon + L_interaction + L_sectors
    return {"L_GR": L_GR, "L_SCm": L_SCm, "L_phonon": L_phonon,
            "L_interaction": L_interaction, "L_sectors_sum": L_sectors,
            "L_UQFF_total": L_total, "n_sectors": len(sector_contribs)}

