_MPC_M = 3.086e22
M_LENS_RINGS_KG     = 1.0e14 * M_SUN
R_EINSTEIN_RINGS_M  = 3.086e20
B_RINGS_T           = 1.0e-5
Z_LENS_RINGS        = 0.5
Z_SOURCE_RINGS      = 2.0
H0_RINGS_KMSMPC     = 70.0
V_GAS_RINGS_MS      = 1.0e6
T_RINGS_DEFAULT_S   = 5.0e9 * _YEAR_S_MAGNETAR

def _D_LS_over_D_S_uqff(z_lens: float = Z_LENS_RINGS,
                         z_source: float = Z_SOURCE_RINGS) -> float:
    return (1.0 + z_lens) / max(1.0 + z_source, 1e-300)

def _einstein_lensing_factor_uqff(M_lens_kg: float = M_LENS_RINGS_KG,
                                    r_lens_m: float = R_EINSTEIN_RINGS_M,
                                    z_lens: float = Z_LENS_RINGS,
                                    z_source: float = Z_SOURCE_RINGS) -> float:
    base = G_NEWTON * M_lens_kg / ((C_LIGHT ** 2) * max(r_lens_m, 1e-300))
    return base * _D_LS_over_D_S_uqff(z_lens, z_source)

def _rings_g_master_uqff(r_m: float = R_EINSTEIN_RINGS_M,
                          t_s: float = T_RINGS_DEFAULT_S,
                          M_kg: float = M_LENS_RINGS_KG,
                          B_T: float = B_RINGS_T,
                          B_crit_T: float = B_CRIT_MAGNETAR_T,
                          z_lens: float = Z_LENS_RINGS,
                          z_source: float = Z_SOURCE_RINGS,
                          H0_kmsMpc: float = H0_RINGS_KMSMPC,
                          Lambda_m2: float = LAMBDA_MAGNETAR_M2,
                          Ug2: float = 0.0,
                          Ug3: float = 0.0,
                          f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                          v_gas_ms: float = V_GAS_RINGS_MS,
                          q_C: float = EV_J,
                          m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                          macro_scale: float = MACROSCOPIC_SCALE_LORENTZ,
                          rho_UA_val: float = None,
                          rho_SCm_val: float = None) -> float:
    Ug1 = G_NEWTON * M_kg / max(r_m * r_m, 1e-300)
    sc_factor = 1.0 - B_T / max(B_crit_T, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_lens, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    L_t = _einstein_lensing_factor_uqff(M_kg, r_m, z_lens, z_source)
    lensing_factor = 1.0 + L_t
    grav_term = Ug1 * (1.0 + H_z_si * t_s) * sc_factor * lensing_factor
    Ug4 = Ug1 * sc_factor
    Ug_sum_trz = (Ug1 + Ug2 + Ug3 + Ug4) * (1.0 + f_TRZ)
    cosm = Lambda_m2 * (C_LIGHT ** 2) / 3.0
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + Ug_sum_trz + cosm + lorentz_term

M_NGC2525_STAR_KG     = 1.0e10 * M_SUN
M_NGC2525_BH_KG       = 2.25e7 * M_SUN
M_NGC2525_TOTAL_KG    = M_NGC2525_STAR_KG + M_NGC2525_BH_KG
R_NGC2525_DISK_M      = 2.836e20
R_NGC2525_BH_M        = 1.496e11
B_NGC2525_T           = 1.0e-5
Z_NGC2525             = 0.016
H0_NGC2525_KMSMPC     = 70.0
V_GAS_NGC2525_MS      = 1.0e5
M_SN_2018GV_INIT_KG   = 1.4 * M_SUN
TAU_SN_2018GV_S       = 1.0 * _YEAR_S_MAGNETAR
T_NGC2525_DEFAULT_S   = 7.0 * _YEAR_S_MAGNETAR

def _ngc2525_g_master_uqff(r_m: float = R_NGC2525_DISK_M,
                              t_s: float = T_NGC2525_DEFAULT_S,
                              M_kg: float = M_NGC2525_TOTAL_KG,
                              M_BH_kg: float = M_NGC2525_BH_KG,
                              r_BH_m: float = R_NGC2525_BH_M,
                              M_SN_init_kg: float = M_SN_2018GV_INIT_KG,
                              tau_SN_s: float = TAU_SN_2018GV_S,
                              B_T: float = B_NGC2525_T,
                              B_crit_T: float = B_CRIT_MAGNETAR_T,
                              z_obs: float = Z_NGC2525,
                              H0_kmsMpc: float = H0_NGC2525_KMSMPC,
                              Ug2: float = 0.0,
                              Ug3: float = 0.0,
                              f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                              Lambda_m2: float = LAMBDA_MAGNETAR_M2,
                              v_gas_ms: float = V_GAS_NGC2525_MS,
                              q_C: float = EV_J,
                              m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                              rho_UA_val: float = None,
                              rho_SCm_val: float = None,
                              macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    Ug1 = G_NEWTON * M_kg / max(r_m * r_m, 1e-300)
    sc_factor = 1.0 - B_T / max(B_crit_T, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_obs, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    grav_disk = Ug1 * (1.0 + H_z_si * t_s) * sc_factor
    bh_term = G_NEWTON * M_BH_kg / max(r_BH_m * r_BH_m, 1e-300)
    Ug4 = Ug1 * sc_factor
    Ug_sum_trz = (Ug1 + Ug2 + Ug3 + Ug4) * (1.0 + f_TRZ)
    cosm = Lambda_m2 * (C_LIGHT ** 2) / 3.0
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    M_SN_t = _magnetar_B_decay(t_s, M_SN_init_kg, tau_SN_s)
    sn_drain = G_NEWTON * M_SN_t / max(r_m * r_m, 1e-300)
    return grav_disk + bh_term + Ug_sum_trz + cosm + lorentz_term - sn_drain

M_NGC3603_INIT_KG     = 4.0e5 * M_SUN
R_NGC3603_M           = 8.998e15
B_NGC3603_T           = 1.0e-5
TAU_SF_NGC3603_S      = 1.0e6 * _YEAR_S_MAGNETAR
TAU_EXP_NGC3603_S     = 1.0e6 * _YEAR_S_MAGNETAR
M_DOT0_NGC3603        = 1.0
V_WIND_NGC3603_MS     = 2.0e6
RHO_GAS_NGC3603       = 1.0e-20
V_GAS_NGC3603_MS      = 1.0e5
H0_NGC3603_KMSMPC     = 70.0
T_NGC3603_DEFAULT_S   = 5.0e5 * _YEAR_S_MAGNETAR

def _ngc3603_g_master_uqff(r_m: float = R_NGC3603_M,
                              t_s: float = T_NGC3603_DEFAULT_S,
                              M_initial_kg: float = M_NGC3603_INIT_KG,
                              M_dot_0: float = M_DOT0_NGC3603,
                              tau_SF_s: float = TAU_SF_NGC3603_S,
                              B_T: float = B_NGC3603_T,
                              B_crit_T: float = B_CRIT_MAGNETAR_T,
                              rho_gas: float = RHO_GAS_NGC3603,
                              v_wind_ms: float = V_WIND_NGC3603_MS,
                              tau_exp_s: float = TAU_EXP_NGC3603_S,
                              H0_kmsMpc: float = H0_NGC3603_KMSMPC,
                              Ug2: float = 0.0,
                              Ug3: float = 0.0,
                              f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                              Lambda_m2: float = LAMBDA_MAGNETAR_M2,
                              v_gas_ms: float = V_GAS_NGC3603_MS,
                              q_C: float = EV_J,
                              m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                              rho_UA_val: float = None,
                              rho_SCm_val: float = None,
                              macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    M_t = _accretion_mass_growth_uqff(M_initial_kg, t_s, M_dot_0, tau_SF_s)
    Ug1 = G_NEWTON * M_t / max(r_m * r_m, 1e-300)
    sc_factor = 1.0 - B_T / max(B_crit_T, 1e-300)
    H0_kmsMpc_val = _hubble_unified(t_s, 0.0, H0_kmsMpc)
    H0_si = H0_kmsMpc_val * 1.0e3 / _MPC_M
    P_0 = rho_gas * v_wind_ms * v_wind_ms
    P_t = _magnetar_B_decay(t_s, P_0, tau_exp_s)
    cavity_factor = 1.0 - P_t
    grav_term = Ug1 * (1.0 + H0_si * t_s) * sc_factor * cavity_factor
    Ug4 = Ug1 * sc_factor
    Ug_sum_trz = (Ug1 + Ug2 + Ug3 + Ug4) * (1.0 + f_TRZ)
    cosm = Lambda_m2 * (C_LIGHT ** 2) / 3.0
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + Ug_sum_trz + cosm + lorentz_term

M_NGC7635_STAR_KG     = 45.0 * M_SUN
R_NGC7635_M           = 3.311e16
B_NGC7635_T           = 1.0e-6
