def _bubble_nebula_g_master_uqff(r_m: float = R_NGC7635_M,
                                     t_s: float = T_NGC7635_DEFAULT_S,
                                     M_star_kg: float = M_NGC7635_STAR_KG,
                                     P_0: float = P_0_NGC7635,
                                     tau_exp_s: float = TAU_EXP_NGC7635_S,
                                     H0_kmsMpc: float = H0_NGC7635_KMSMPC,
                                     f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                                     B_T: float = B_NGC7635_T,
                                     v_wind_ms: float = V_WIND_NGC7635_MS,
                                     q_C: float = EV_J,
                                     m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                                     rho_UA_val: float = None,
                                     rho_SCm_val: float = None,
                                     macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    Ug1 = G_NEWTON * M_star_kg / max(r_m * r_m, 1e-300)
    H0_kmsMpc_val = _hubble_unified(t_s, 0.0, H0_kmsMpc)
    H0_si = H0_kmsMpc_val * 1.0e3 / _MPC_M
    P_t = _magnetar_B_decay(t_s, P_0, tau_exp_s)
    cavity_factor = 1.0 - P_t
    grav_term = Ug1 * (1.0 + H0_si * t_s) * cavity_factor * (1.0 + f_TRZ)
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_wind_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + lorentz_term

M_ANTENNAE_INIT_KG    = 2.0e11 * M_SUN
R_ANTENNAE_M          = 2.838e20
B_ANTENNAE_T          = 1.0e-4
SFR_ANTENNAE_KGS      = 20.0 * M_SUN / _YEAR_S_MAGNETAR
TAU_MERGE_ANTENNAE_S  = 400.0e6 * _YEAR_S_MAGNETAR
M_COLL_0_ANTENNAE     = 0.5
Z_ANTENNAE            = 0.0105
H0_ANTENNAE_KMSMPC    = 70.0
V_GAS_ANTENNAE_MS     = 1.0e6
T_ANTENNAE_DEFAULT_S  = 300.0e6 * _YEAR_S_MAGNETAR

def _sfr_linear_mass_growth_uqff(M_initial_kg: float = M_ANTENNAE_INIT_KG,
                                    t_s: float = T_ANTENNAE_DEFAULT_S,
                                    SFR_kgs: float = SFR_ANTENNAE_KGS) -> float:
    return M_initial_kg + SFR_kgs * t_s

def _merger_progress_saturating_uqff(t_s: float = T_ANTENNAE_DEFAULT_S,
                                        M_0: float = M_COLL_0_ANTENNAE,
                                        tau_merge_s: float = TAU_MERGE_ANTENNAE_S) -> float:
    import math as _math
    return M_0 * (1.0 - _math.exp(-t_s / max(tau_merge_s, 1e-300)))

def _antennae_g_master_uqff(r_m: float = R_ANTENNAE_M,
                              t_s: float = T_ANTENNAE_DEFAULT_S,
                              M_initial_kg: float = M_ANTENNAE_INIT_KG,
                              SFR_kgs: float = SFR_ANTENNAE_KGS,
                              M_coll_0: float = M_COLL_0_ANTENNAE,
                              tau_merge_s: float = TAU_MERGE_ANTENNAE_S,
                              z_obs: float = Z_ANTENNAE,
                              H0_kmsMpc: float = H0_ANTENNAE_KMSMPC,
                              f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                              B_T: float = B_ANTENNAE_T,
                              v_gas_ms: float = V_GAS_ANTENNAE_MS,
                              q_C: float = EV_J,
                              m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                              rho_UA_val: float = None,
                              rho_SCm_val: float = None,
                              macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    M_t = _sfr_linear_mass_growth_uqff(M_initial_kg, t_s, SFR_kgs)
    Ug1 = G_NEWTON * M_t / max(r_m * r_m, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_obs, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    M_coll_t = _merger_progress_saturating_uqff(t_s, M_coll_0, tau_merge_s)
    merger_factor = 1.0 - M_coll_t
    grav_term = Ug1 * (1.0 + H_z_si * t_s) * merger_factor * (1.0 + f_TRZ)
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + lorentz_term

_L_SUN_W_HORSEHEAD     = 3.826e26
M_HORSEHEAD_KG         = 120.0 * M_SUN
R_HORSEHEAD_M          = 1.182e16
L_SIGMA_ORIONIS_W      = 1.0e5 * _L_SUN_W_HORSEHEAD
RHO_HORSEHEAD_KGM3     = 1.0e-21
_M_H_HORSEHEAD_KG      = 1.67e-27
E_0_HORSEHEAD          = 0.2
TAU_ERODE_HORSEHEAD_S  = 5.0e6 * _YEAR_S_MAGNETAR
Z_HORSEHEAD            = 0.0003
H0_HORSEHEAD_KMSMPC    = 70.0
B_HORSEHEAD_T          = 1.0e-5
V_HORSEHEAD_MS         = 1.0e5
T_HORSEHEAD_DEFAULT_S  = 1.0e6 * _YEAR_S_MAGNETAR

def _radiation_pressure_acceleration_uqff(L_star_W: float = L_SIGMA_ORIONIS_W,
                                             r_m: float = R_HORSEHEAD_M,
                                             rho_kgm3: float = RHO_HORSEHEAD_KGM3,
                                             m_particle_kg: float = _M_H_HORSEHEAD_KG,
                                             c_ms: float = C_LIGHT) -> float:
    import math as _math
    rad_energy_density = L_star_W / max(4.0 * _math.pi * r_m * r_m * c_ms, 1e-300)
    number_density = rho_kgm3 / max(m_particle_kg, 1e-300)
    return rad_energy_density * number_density

def _horsehead_g_master_uqff(r_m: float = R_HORSEHEAD_M,
                                t_s: float = T_HORSEHEAD_DEFAULT_S,
                                M_kg: float = M_HORSEHEAD_KG,
                                E_0: float = E_0_HORSEHEAD,
                                tau_erode_s: float = TAU_ERODE_HORSEHEAD_S,
                                z_obs: float = Z_HORSEHEAD,
                                H0_kmsMpc: float = H0_HORSEHEAD_KMSMPC,
                                f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                                L_star_W: float = L_SIGMA_ORIONIS_W,
                                rho_kgm3: float = RHO_HORSEHEAD_KGM3,
                                m_particle_kg: float = _M_H_HORSEHEAD_KG,
                                c_ms: float = C_LIGHT,
                                B_T: float = B_HORSEHEAD_T,
                                v_gas_ms: float = V_HORSEHEAD_MS,
                                q_C: float = EV_J,
                                m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                                rho_UA_val: float = None,
                                rho_SCm_val: float = None,
                                macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    Ug1 = G_NEWTON * M_kg / max(r_m * r_m, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_obs, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    E_t = _merger_progress_saturating_uqff(t_s, E_0, tau_erode_s)
    erosion_factor = 1.0 - E_t
    grav_term = Ug1 * (1.0 + H_z_si * t_s) * erosion_factor * (1.0 + f_TRZ)
    P_rad = _radiation_pressure_acceleration_uqff(L_star_W=L_star_W,
                                                     r_m=r_m,
                                                     rho_kgm3=rho_kgm3,
                                                     m_particle_kg=m_particle_kg,
                                                     c_ms=c_ms)
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + P_rad + lorentz_term

_MU_0_NGC1275            = 4.0 * 3.141592653589793 * 1.0e-7
M_NGC1275_STELLAR_KG     = 1.0e12 * M_SUN
M_NGC1275_SMBH_KG        = 8.0e8 * M_SUN
M_NGC1275_TOTAL_KG       = M_NGC1275_STELLAR_KG + M_NGC1275_SMBH_KG
R_NGC1275_M              = 9.46e20
F_0_NGC1275              = 0.1
TAU_BH_NGC1275_S         = 100.0e6 * _YEAR_S_MAGNETAR
Z_NGC1275                = 0.0176
H0_NGC1275_KMSMPC        = 70.0
B_NGC1275_T              = 1.0e-8
V_NGC1275_FIL_M3         = 1.42e50
M_NGC1275_FIL_KG         = 1.0e6 * M_SUN
V_HVS_NGC1275_MS         = 3.0e6
T_NGC1275_DEFAULT_S      = 50.0e6 * _YEAR_S_MAGNETAR

def _magnetic_tension_acceleration_uqff(B_T: float = B_NGC1275_T,
                                          V_m3: float = V_NGC1275_FIL_M3,
                                          M_kg: float = M_NGC1275_FIL_KG,
                                          mu_0: float = _MU_0_NGC1275,
                                          macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    P_mag = (B_T * B_T) / max(2.0 * mu_0, 1e-300)
    Force_N = P_mag * V_m3
    accel = Force_N / max(M_kg, 1e-300)
    return accel * macro_scale

def _ngc1275_g_master_uqff(r_m: float = R_NGC1275_M,
                              t_s: float = T_NGC1275_DEFAULT_S,
                              M_kg: float = M_NGC1275_TOTAL_KG,
                              F_0: float = F_0_NGC1275,
                              tau_BH_s: float = TAU_BH_NGC1275_S,
                              z_obs: float = Z_NGC1275,
                              H0_kmsMpc: float = H0_NGC1275_KMSMPC,
                              f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                              B_T: float = B_NGC1275_T,
                              V_fil_m3: float = V_NGC1275_FIL_M3,
                              M_fil_kg: float = M_NGC1275_FIL_KG,
                              v_hvs_ms: float = V_HVS_NGC1275_MS,
                              q_C: float = EV_J,
                              m_charge_kg: float = _M_PROTON_KG_MAGNETAR,
                              rho_UA_val: float = None,
                              rho_SCm_val: float = None,
                              macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    Ug1 = G_NEWTON * M_kg / max(r_m * r_m, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_obs, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    F_BH_t = _merger_progress_saturating_uqff(t_s, F_0, tau_BH_s)
    feedback_factor = 1.0 - F_BH_t
    grav_term = Ug1 * (1.0 + H_z_si * t_s) * feedback_factor * (1.0 + f_TRZ)
    a_fil = _magnetic_tension_acceleration_uqff(B_T=B_T, V_m3=V_fil_m3,
                                                  M_kg=M_fil_kg,
                                                  macro_scale=macro_scale)
    lorentz_term = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_hvs_ms, q_C=q_C,
                                                m_kg=m_charge_kg,
                                                rho_UA_val=rho_UA_val,
                                                rho_SCm_val=rho_SCm_val,
                                                macro_scale=macro_scale)
    return grav_term + a_fil + lorentz_term

