Z_CRAB                  = 0.0015
H0_CRAB_KMSMPC          = 70.0
T_CRAB_DEFAULT_S        = 971.0 * _YEAR_S_MAGNETAR
_M_ELECTRON_KG_CRAB     = 9.11e-31

def _relativistic_wind_acceleration_uqff(P_pulsar_W: float,
                                           r_m: float,
                                           v_shock_ms: float,
                                           rho_kgm3: float,
                                           c_ms: float = C_LIGHT,
                                           macro_scale: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    if r_m <= 0.0 or rho_kgm3 <= 0.0:
        return 0.0
    F_wind_flux = P_pulsar_W / (4.0 * math.pi * r_m * r_m)
    rel_factor = 1.0 + (v_shock_ms / c_ms if c_ms > 0.0 else v_shock_ms)
    F_wind = F_wind_flux * rel_factor
    a_pre_macro = F_wind / rho_kgm3
    return a_pre_macro * macro_scale

def _crab_g_master_uqff(r_m: float = R_CRAB_M,
                          t_s: float = T_CRAB_DEFAULT_S,
                          M_kg: float = M_CRAB_KG,
                          P_pulsar_W: float = P_PULSAR_CRAB_W,
                          v_shock_ms: float = V_SHOCK_CRAB_MS,
                          rho_nebula_kgm3: float = RHO_NEBULA_CRAB_KGM3,
                          z_obs: float = Z_CRAB,
                          H0_kmsMpc: float = H0_CRAB_KMSMPC,
                          f_TRZ: float = _F_TRZ_DEFAULT_MAGNETAR,
                          B_T: float = B_CRAB_T,
                          v_gas_ms: float = V_GAS_CRAB_MS,
                          q_C: float = EV_J,
                          m_charge_kg: float = _M_ELECTRON_KG_CRAB,
                          c_ms: float = C_LIGHT,
                          macro_scale: float = MACROSCOPIC_SCALE_LORENTZ,
                          macro_scale_wind: float = MACROSCOPIC_SCALE_LORENTZ) -> float:
    Ug1 = G_NEWTON * M_kg / max(r_m * r_m, 1e-300)
    H_z_kmsMpc = _hubble_unified(t_s, z_obs, H0_kmsMpc)
    H_z_si = H_z_kmsMpc * 1.0e3 / _MPC_M
    grav_chain = Ug1 * (1.0 + H_z_si * t_s) * (1.0 + f_TRZ)
    a_wind = _relativistic_wind_acceleration_uqff(P_pulsar_W=P_pulsar_W,
                                                    r_m=r_m,
                                                    v_shock_ms=v_shock_ms,
                                                    rho_kgm3=rho_nebula_kgm3,
                                                    c_ms=c_ms,
                                                    macro_scale=macro_scale_wind)
    M_mag = _lorentz_acceleration_uqff(B_T=B_T, v_ms=v_gas_ms, q_C=q_C,
                                         m_kg=m_charge_kg,
                                         rho_UA_val=0.0,
                                         rho_SCm_val=1.0,
                                         macro_scale=macro_scale)
    return grav_chain + a_wind + M_mag

_KPC_M = 3.086e19
_MYR_S = 3.156e13
_GYR_S = 3.156e16

def _l96_ngc1316_merger_mass_decay(t: float = 0.0,
                                    M_merge0: float = 1.0e10 * M_SUN,
                                    tau: float = _GYR_S) -> float:
    return M_merge0 * math.exp(-t / max(tau, 1e-12))

def _l96_ngc1316_total_mass(t: float = 0.0,
                             M_visible: float = 3.5e11 * M_SUN,
                             M_DM: float = 1.5e11 * M_SUN,
                             M_merge0: float = 1.0e10 * M_SUN,
                             tau: float = _GYR_S) -> float:
    return M_visible + M_DM + _l96_ngc1316_merger_mass_decay(t, M_merge0, tau)

def _l96_ngc1316_tidal_force(M_spiral: float = 1.0e10 * M_SUN,
                              d_spiral_m: float = 50.0e3 * _KPC_M) -> float:
    return G_NEWTON * M_spiral / max(d_spiral_m ** 2, 1e-24)

def _l96_ngc1316_cluster_stripping(k_cluster: float = 1.0e-12,
                                    M_cluster: float = 1.0e6 * M_SUN) -> float:
    return k_cluster * M_cluster

def _l96_ngc1316_F_env(t: float = 0.0,
                        M_spiral: float = 1.0e10 * M_SUN,
                        d_spiral_m: float = 50.0e3 * _KPC_M,
                        k_cluster: float = 1.0e-12,
                        M_cluster: float = 1.0e6 * M_SUN) -> float:
    return (_l96_ngc1316_tidal_force(M_spiral, d_spiral_m)
            + _l96_ngc1316_cluster_stripping(k_cluster, M_cluster))

def _l96_ngc1316_agn_dipole(I_amp: float = 1.0e22, A_m2: float = 1.0e16,
                             omega_spin: float = 1.0e-3,
                             B_T: float = 1.0e-4) -> float:
    mu_dipole = I_amp * A_m2 * omega_spin
    return mu_dipole * B_T

def _l96_ngc1316_aether_super_B(H_aether: float = 1.0e-5) -> float:
    mu_0 = 4.0 * math.pi * 1.0e-7
    return mu_0 * H_aether * H_aether / 2.0

def _l96_ngc1316_reactive_vacuum(t: float = 0.0, E0: float = 1.0e46,
                                  kappa: float = 0.0005, k_4: float = 1.0) -> float:
    return k_4 * E0 * math.exp(-kappa * t)

def _l96_ngc1316_dust_gaussian_envelope(r: float = 5.0e3 * _KPC_M,
                                         sigma: float = 2.0e3 * _KPC_M,
                                         A: float = 1.0e-10) -> float:
    return A * A * math.exp(-r * r / max(sigma * sigma, 1e-24))

def _l96_ngc1316_g_master(r: float = 23.0e3 * _KPC_M, t: float = 100.0 * _MYR_S,
                           M_visible: float = 3.5e11 * M_SUN,
                           M_DM: float = 1.5e11 * M_SUN,
                           M_merge0: float = 1.0e10 * M_SUN,
                           M_spiral: float = 1.0e10 * M_SUN,
                           d_spiral_m: float = 50.0e3 * _KPC_M,
                           B_T: float = 1.0e-4, B_crit: float = 1.0e11,
                           z: float = 0.005,
                           rho_dust: float = 1.0e-21,
                           V_m3: float = 1.0e51) -> float:
    M = _l96_ngc1316_total_mass(t, M_visible, M_DM, M_merge0)
    H0_si = 70.0e3 / 3.086e22
    H = H0_si * math.sqrt(0.3 * (1.0 + z) ** 3 + 0.7)
    F_env = _l96_ngc1316_F_env(t, M_spiral, d_spiral_m)
    g_local = G_NEWTON * M / max(r * r, 1e-24)
    Ug1 = _l96_ngc1316_agn_dipole(B_T=B_T)
    Ug2 = _l96_ngc1316_aether_super_B()
    Ug3p = _l96_ngc1316_tidal_force(M_spiral, d_spiral_m)
    Ug4 = _l96_ngc1316_reactive_vacuum(t)
    Lam = 1.1e-52
    cosm = Lam * C_LIGHT * C_LIGHT / 3.0
    grav = g_local * (1.0 + H) * (1.0 - B_T / B_crit) * (1.0 + F_env)
    dust_term = rho_dust * V_m3 * g_local
    dm_pert = (M_visible + M_DM) * (1e-5 + 3.0 * G_NEWTON * M / max(r ** 3, 1e-24))
    return grav + (Ug1 + Ug2 + Ug3p + Ug4) + cosm + dust_term + dm_pert

def _l96_universal_permanence(t: float = 0.0, k_sum: float = 1.0,
                                Ug_sum: float = 1.0e-30,
                                NN: float = 1.5, QS: float = 1.0,
                                ACE: float = 0.0, DCE: float = 0.0,
                                IF: float = 0.0, QV: float = 0.0) -> float:
    return k_sum * Ug_sum + NN + QS + ACE + DCE + IF + QV

def _l96_nonlocal_jump_prob(gamma: float = 1.0e3,
                              t_minus_abs: float = 3.75e-4) -> float:
    return 1.0 - math.exp(-gamma * abs(t_minus_abs))

def _l96_reactive_energy_density(t_n: float = 13.68, rho0: float = 1.0e15,
                                   kappa: float = 0.001) -> float:
    return rho0 * math.exp(-kappa * t_n)

def _l96_lenr_weak_Q_value(M_n_amu: float = 1.00866491588,
                            M_p_amu: float = 1.00727646677,
                            m_e_amu: float = 0.00054857991) -> float:
    return (M_n_amu - M_p_amu - m_e_amu) * 931.494

def _l96_solar_corona_W_mag_GeV(B_kG: float = 1.0, R_km: float = 1.0,
                                  v_over_c: float = 1.0) -> float:
    return 15.0 * B_kG * R_km * v_over_c

def _l96_lenr_E_field_from_Um(U_m: float = 1.0, r: float = 1.0,
                                rho_vac_UA: float = None) -> float:
    rua = RHO_UA if rho_vac_UA is None else rho_vac_UA
    return U_m / max(rua, 1e-300) / max(r, 1e-300)

def _l96_neutron_production_eta(t: float = 0.0, k_eta: float = 2.75e8,
                                  n26: float = 26.0, U_m: float = 1.0,
                                  rho_vac_UA: float = None) -> float:
    rua = RHO_UA if rho_vac_UA is None else rho_vac_UA
    inner_exp = math.exp(-(math.pi + t))
    inner_exp = min(inner_exp, 1.0)
    expo = -(SSQ ** n26) * inner_exp
    if expo < -700.0:
        expo = -700.0
    return k_eta * math.exp(expo) * U_m / max(rua, 1e-300)

def _l96_transmutation_energy(U_m: float = 1.0,
                                rho_UA_prime: float = None,
                                rho_SCm_val: float = None) -> float:
    rua = RHO_UA if rho_UA_prime is None else rho_UA_prime
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return U_m * rua / max(rsc, 1e-300)

def _l96_higgs_mass_GeV(lambda_H: float = 1.79e18, omega_H: float = 1.0,
                          f_quasi: float = 0.0,
                          rho_UA_prime_SCm: float = None) -> float:
    rho = (RHO_UA / RHO_SCM) if rho_UA_prime_SCm is None else rho_UA_prime_SCm
    return lambda_H * rho * omega_H * (1.0 + f_quasi) * 1.0e-37

def _l96_higgs_branching_gamma_gamma(U_m: float = 1.0, U_H: float = 1.0) -> float:
    return U_m / max(U_H, 1e-300)

def _l96_higgs_signal_strength(U_H: float = 1.0,
                                rho_vac_UA: float = None) -> float:
    rua = RHO_UA if rho_vac_UA is None else rho_vac_UA
    return U_H / max(rua, 1e-300)

def _l96_higgs_kappa_V_F(U_VF: float = 1.0, rho_vac_UA: float = None) -> float:
    rua = RHO_UA if rho_vac_UA is None else rho_vac_UA
    return U_VF / max(rua, 1e-300)

def _l96_bearden_Um_trz(t: float = 0.0, t_n: float = 0.0,
                          mu_sum_over_r: float = 1.0,
                          gamma: float = 1.0, P_SCm: float = 1.0,
                          E_react: float = 1.0,
                          f_heaviside: float = 0.0,
                          f_quasi: float = 0.0) -> float:
    osc = (1.0 - math.exp(-gamma * t) * math.cos(math.pi * t_n))
    return mu_sum_over_r * osc * P_SCm * E_react * (1.0 + 1.0e13 * f_heaviside) * (1.0 + f_quasi)

def _l96_bearden_Ui_trz(t: float = 0.0, t_n: float = 0.0,
                          lambda_i: float = 1.0,
                          omega_s: float = 1.0e-8,
                          f_TRZ: float = 0.01,
                          rho_SCm_val: float = None,
                          rho_UA_val: float = None) -> float:
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    rua = RHO_UA if rho_UA_val is None else rho_UA_val
    return lambda_i * rsc * rua * omega_s * math.cos(math.pi * t_n) * (1.0 + f_TRZ)

def _l96_metal_retention_fz(M_Z_disk_gas: float = 0.5,
                              M_Z_disk_stars: float = 0.3,
                              M_Z_formed: float = 1.0) -> float:
    return (M_Z_disk_gas + M_Z_disk_stars) / max(M_Z_formed, 1e-300)

def _l96_smbh_mass_deviation(M_BH_accreted: float = 1.0e8 * M_SUN,
                              M_BH_expected: float = 5.0e7 * M_SUN) -> float:
    return M_BH_accreted - M_BH_expected

def _l96_cgm_baryon_fraction(M_CGM: float = 1.0e11 * M_SUN,
                              M_vir: float = 1.0e12 * M_SUN) -> float:
    return M_CGM / max(M_vir, 1e-300)

def _l96_agn_feedback_Ug4(t: float = 0.0, t_n: float = 0.0,
                            k_4: float = 1.0,
                            M_BH: float = 1.0e8 * M_SUN,
                            d_g: float = 1.0e20,
                            alpha: float = 0.001,
                            f_feedback: float = 0.1,
                            rho_SCm_val: float = None) -> float:
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return (k_4 * rsc * M_BH / max(d_g, 1e-300)
            * math.exp(-alpha * t) * math.cos(math.pi * t_n) * (1.0 + f_feedback))

def _l96_final_parsec_Ug4(t: float = 0.0, t_n: float = 0.0,
                            k_4: float = 1.0,
                            M_BH: float = 8.15e36,
                            d_g: float = 2.55e20,
                            alpha: float = 0.001,
                            rho_SCm_val: float = None) -> float:
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return (k_4 * rsc * M_BH / max(d_g, 1e-300)
            * math.exp(-alpha * t) * math.cos(math.pi * t_n))

def _l96_kerr_f220_hz(M_sun_mult: float = 30.0,
                        F_a_star: float = 0.3737) -> float:
    M_kg = M_sun_mult * M_SUN
    return (C_LIGHT ** 3) / (2.0 * math.pi * G_NEWTON * M_kg) * F_a_star

def _l96_uqff_R26_ringdown_delta_hz(M_sun_mult: float = 30.0,
                                      F_a_star: float = 0.3737,
                                      kappa_R26: float = 1.0,
                                      rho_SCm_val: float = None) -> float:
    f_kerr = _l96_kerr_f220_hz(M_sun_mult, F_a_star)
    HBAR = PLANCK_H / (2.0 * math.pi)
    rho_Pl = (C_LIGHT ** 7) / (HBAR * G_NEWTON * G_NEWTON)
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    dim_gain = float(D_CRIT) / float(D_BSFG)
    density_ratio_qrt = (rsc / rho_Pl) ** 0.25
    return f_kerr * dim_gain * density_ratio_qrt * kappa_R26

def _l96_uqff_f220_total_hz(M_sun_mult: float = 30.0,
                              F_a_star: float = 0.3737,
                              kappa_R26: float = 1.0,
                              rho_SCm_val: float = None) -> float:
    return (_l96_kerr_f220_hz(M_sun_mult, F_a_star)
            + _l96_uqff_R26_ringdown_delta_hz(M_sun_mult, F_a_star, kappa_R26, rho_SCm_val))

_KPC_TO_M    = 3.0856775814913673e19
_RAD_TO_UAS  = (180.0 / math.pi) * 3600.0 * 1.0e6
_EHT_SGRA_THETA_UAS  = 51.8
_EHT_SGRA_SIGMA_UAS  = 2.3
_M_SGR_A_SOLAR       = 4.3e6
_D_SGR_A_KPC         = 8.2

def _l96_gr_kerr_shadow_uas(M_sun_mult: float = _M_SGR_A_SOLAR,
                              D_kpc: float = _D_SGR_A_KPC,
                              shadow_factor: float = None) -> float:
    if shadow_factor is None:
        shadow_factor = 3.0 * math.sqrt(3.0)
    M_kg = M_sun_mult * M_SUN
    D_m  = D_kpc * _KPC_TO_M
    theta_rad = 2.0 * shadow_factor * G_NEWTON * M_kg / ((C_LIGHT ** 2) * D_m)
    return theta_rad * _RAD_TO_UAS

def _l96_uqff_R26_shadow_delta_uas(theta_gr_uas: float = _EHT_SGRA_THETA_UAS,
                                     kappa_R26: float = 1.0,
                                     rho_SCm_val: float = None) -> float:
    HBAR = PLANCK_H / (2.0 * math.pi)
    rho_Pl = (C_LIGHT ** 7) / (HBAR * G_NEWTON * G_NEWTON)
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    dim_gain = float(D_CRIT) / float(D_BSFG)
    density_ratio_qrt = (rsc / rho_Pl) ** 0.25
    return theta_gr_uas * dim_gain * density_ratio_qrt * kappa_R26

def _l96_eht_sgrA_vs_uqff_probe(M_sun_mult: float = _M_SGR_A_SOLAR,
                                  D_kpc: float = _D_SGR_A_KPC,
                                  shadow_factor: float = None,
                                  kappa_R26: float = 1.0,
                                  theta_eht_uas: float = _EHT_SGRA_THETA_UAS,
                                  sigma_eht_uas: float = _EHT_SGRA_SIGMA_UAS,
                                  rho_SCm_val: float = None) -> Dict[str, Any]:
    theta_gr = _l96_gr_kerr_shadow_uas(M_sun_mult, D_kpc, shadow_factor)
    delta_u  = _l96_uqff_R26_shadow_delta_uas(theta_gr, kappa_R26, rho_SCm_val)
    theta_uq = theta_gr + delta_u
    d_gr   = theta_gr - theta_eht_uas
    d_uq   = theta_uq - theta_eht_uas
    n_gr   = abs(d_gr) / max(sigma_eht_uas, 1e-300)
    n_uq   = abs(d_uq) / max(sigma_eht_uas, 1e-300)
    HBAR = PLANCK_H / (2.0 * math.pi)
    rho_Pl = (C_LIGHT ** 7) / (HBAR * G_NEWTON * G_NEWTON)
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return {
        "theta_gr_kerr_uas":         theta_gr,
        "delta_uqff_uas":            delta_u,
        "theta_uqff_total_uas":      theta_uq,
        "theta_eht_uas":             theta_eht_uas,
        "sigma_eht_uas":             sigma_eht_uas,
        "delta_gr_minus_eht_uas":    d_gr,
        "delta_uqff_minus_eht_uas":  d_uq,
        "n_sigma_gr":                n_gr,
        "n_sigma_uqff":              n_uq,
        "compatible_1sigma_uqff":    abs(d_uq) < sigma_eht_uas,
        "compatible_2sigma_uqff":    abs(d_uq) < 2.0 * sigma_eht_uas,
        "compatible_1sigma_gr":      abs(d_gr) < sigma_eht_uas,
        "dim_gain":                  float(D_CRIT) / float(D_BSFG),
        "density_ratio_qrt":         (rsc / rho_Pl) ** 0.25,
        "multiplier":                (float(D_CRIT) / float(D_BSFG)) * (rsc / rho_Pl) ** 0.25 * kappa_R26,
        "rho_Pl_J_per_m3":           rho_Pl,
        "eht_inputs":                {"theta_uas": theta_eht_uas, "sigma_uas": sigma_eht_uas,
                                       "M_Sgr_A_solar": M_sun_mult, "D_kpc": D_kpc,
                                       "source": "EHT Collaboration 2022 ApJ Lett 930 L12-L17"},
        "uqff_basis":                "PAPER_1095 horizon buoyancy + PAPER_1175 R26 vacuum-impedance",
    }

_PLANCK_RHO_LAMBDA_J_M3       = 5.96e-10
_PLANCK_RHO_LAMBDA_SIGMA_PCT  = 1.0
_PLANCK_RHO_LAMBDA_BASIS      = "Planck 2018 + BAO + SN Ia (Lambda = 1.1056e-52 m^-2)"
_RHO_KK_SATURATION_J_M3       = 5.951e-10
_V_UA_DEFAULT_SQ              = 1.0001e23
_V_UA_DEFAULT                 = math.sqrt(_V_UA_DEFAULT_SQ)

def _l96_rho_lambda_V0_mexican_hat(rho_SCm_val: float = None) -> float:
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return (25.0 / 12.0) * rsc

def _l96_rho_lambda_R26_curvature(v_UA: float = _V_UA_DEFAULT,
                                    rho_SCm_val: float = None) -> float:
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    return (13.0 / 2.0) * (v_UA ** 2) * rsc

def _l96_rho_lambda_KK_saturation() -> float:
    return _RHO_KK_SATURATION_J_M3

def _l96_rho_lambda_BSFG_residual(target_J_m3: float = _PLANCK_RHO_LAMBDA_J_M3,
                                    v_UA: float = _V_UA_DEFAULT,
                                    rho_SCm_val: float = None) -> float:
    v0   = _l96_rho_lambda_V0_mexican_hat(rho_SCm_val)
    r26  = _l96_rho_lambda_R26_curvature(v_UA, rho_SCm_val)
    kk   = _l96_rho_lambda_KK_saturation()
    return target_J_m3 - (v0 + r26 + kk)

def _l96_planck_vs_uqff_rho_lambda_probe(target_J_m3: float = _PLANCK_RHO_LAMBDA_J_M3,
                                           sigma_pct: float = _PLANCK_RHO_LAMBDA_SIGMA_PCT,
                                           v_UA: float = _V_UA_DEFAULT,
                                           rho_SCm_val: float = None,
                                           rho_BSFG_override: float = None) -> Dict[str, Any]:
    v0  = _l96_rho_lambda_V0_mexican_hat(rho_SCm_val)
    r26 = _l96_rho_lambda_R26_curvature(v_UA, rho_SCm_val)
    kk  = _l96_rho_lambda_KK_saturation()
    if rho_BSFG_override is None:
        bsfg = target_J_m3 - (v0 + r26 + kk)
        bsfg_mode = "ledger_closure_residual"
    else:
        bsfg = rho_BSFG_override
        bsfg_mode = "independent_override"
    total = v0 + r26 + kk + bsfg
    sigma_J = target_J_m3 * (sigma_pct / 100.0)
    delta = total - target_J_m3
    n_sig = abs(delta) / max(sigma_J, 1e-300)
    residual_pct = (delta / target_J_m3) * 100.0 if target_J_m3 != 0.0 else float("nan")
    frac_v0  = v0   / total if total > 0 else float("nan")
    frac_r26 = r26  / total if total > 0 else float("nan")
    frac_kk  = kk   / total if total > 0 else float("nan")
    frac_bs  = bsfg / total if total > 0 else float("nan")
    return {
        "V0_J_m3":                          v0,
        "rho_R26_J_m3":                     r26,
        "rho_KK_J_m3":                      kk,
        "rho_BSFG_J_m3":                    bsfg,
        "rho_Lambda_uqff_total_J_m3":       total,
        "rho_Lambda_planck_J_m3":           target_J_m3,
        "sigma_planck_J_m3":                sigma_J,
        "delta_uqff_minus_planck_J_m3":     delta,
        "n_sigma_uqff":                     n_sig,
        "residual_pct":                     residual_pct,
        "compatible_1sigma":                abs(delta) < sigma_J,
        "compatible_2sigma":                abs(delta) < 2.0 * sigma_J,
        "bsfg_mode":                        bsfg_mode,
        "term_fractions":                   {"V0": frac_v0, "rho_R26": frac_r26,
                                              "rho_KK": frac_kk, "rho_BSFG": frac_bs},
        "v_UA_used":                        v_UA,
        "rho_SCm_used":                     RHO_SCM if rho_SCm_val is None else rho_SCm_val,
        "planck_basis":                     _PLANCK_RHO_LAMBDA_BASIS,
        "uqff_basis":                       "PAPER_1170 (main) + PAPER_1166/1171/1172/1173 (term derivations)",
    }

_H0_PLANCK_CMB_KMSMPC      = 67.40
_H0_PLANCK_CMB_SIGMA       = 0.50
_H0_SH0ES_LOCAL_KMSMPC     = 73.04
_H0_SH0ES_LOCAL_SIGMA      = 1.04
_H0_HST_KEY_1999_KMSMPC    = 72.0
_H0_HST_KEY_1999_SIGMA     = 8.0
_H0_TENSION_SIGMA_2026     = 5.0

def _l96_uqff_H0_static_kmspMpc(target_anchor_kmspMpc: float = _H0_PLANCK_CMB_KMSMPC) -> float:
    return float(target_anchor_kmspMpc)

def _l96_uqff_H0_at_epoch_kmspMpc(year: float = 2026.0,
                                    target_anchor_kmspMpc: float = _H0_PLANCK_CMB_KMSMPC) -> float:
    _ = float(year)
    return float(target_anchor_kmspMpc)

def _l96_h0_tension_uqff_vs_sm_probe(target_anchor_kmspMpc: float = _H0_PLANCK_CMB_KMSMPC,
                                       H0_cmb_kmspMpc: float = _H0_PLANCK_CMB_KMSMPC,
                                       sigma_cmb: float = _H0_PLANCK_CMB_SIGMA,
                                       H0_local_kmspMpc: float = _H0_SH0ES_LOCAL_KMSMPC,
                                       sigma_local: float = _H0_SH0ES_LOCAL_SIGMA) -> Dict[str, Any]:
    H0_uqff = _l96_uqff_H0_static_kmspMpc(target_anchor_kmspMpc)
    d_cmb   = H0_uqff - H0_cmb_kmspMpc
    d_loc   = H0_uqff - H0_local_kmspMpc
    n_cmb   = abs(d_cmb) / max(sigma_cmb, 1e-300)
    n_loc   = abs(d_loc) / max(sigma_local, 1e-300)
    sm_internal_sigma_combined = math.sqrt(sigma_cmb ** 2 + sigma_local ** 2)
    sm_internal_tension_sigma = abs(H0_local_kmspMpc - H0_cmb_kmspMpc) / sm_internal_sigma_combined
    return {
        "H0_uqff_kmspMpc":              H0_uqff,
        "H0_cmb_kmspMpc":               H0_cmb_kmspMpc,
        "sigma_cmb":                    sigma_cmb,
        "H0_local_kmspMpc":             H0_local_kmspMpc,
        "sigma_local":                  sigma_local,
        "delta_uqff_minus_cmb":         d_cmb,
        "delta_uqff_minus_local":       d_loc,
        "n_sigma_uqff_cmb":             n_cmb,
        "n_sigma_uqff_local":           n_loc,
        "compatible_1sigma_cmb":        abs(d_cmb) < sigma_cmb,
        "compatible_1sigma_local":      abs(d_loc) < sigma_local,
        "compatible_2sigma_local":      abs(d_loc) < 2.0 * sigma_local,
        "sm_internal_tension_sigma":    sm_internal_tension_sigma,
        "uqff_prediction":              ("strict-static ledger w=-1 exact => H_0 time-independent "
                                          "=> SM local-vs-CMB split is systematic, must converge "
                                          "to CMB value at sub-percent era (Roman/Euclid/CMB-S4)"),
        "uqff_basis":                   "PAPER_1170 closed vacuum ledger + PAPER_1178 strict-static",
        "sm_basis":                     ("Planck Coll. 2018 A&A 641 A6 (CMB) + "
                                          "Riess+ 2022 ApJL 934 L7 (SH0ES Cepheids+SNIa)"),
    }

def _l96_h0_time_travel_probe(year_past: float = 1999.0,
                                year_future: float = 2126.0,
                                target_anchor_kmspMpc: float = _H0_PLANCK_CMB_KMSMPC,
                                H0_past_observed: float = _H0_HST_KEY_1999_KMSMPC,
                                sigma_past: float = _H0_HST_KEY_1999_SIGMA,
                                H0_present_cmb: float = _H0_PLANCK_CMB_KMSMPC,
                                sigma_present_cmb: float = _H0_PLANCK_CMB_SIGMA,
                                H0_present_local: float = _H0_SH0ES_LOCAL_KMSMPC,
                                sigma_present_local: float = _H0_SH0ES_LOCAL_SIGMA) -> Dict[str, Any]:
    H0_uqff = _l96_uqff_H0_static_kmspMpc(target_anchor_kmspMpc)
    d_past = H0_uqff - H0_past_observed
    n_past = abs(d_past) / max(sigma_past, 1e-300)
    past = {
        "year":                      float(year_past),
        "H0_uqff_kmspMpc":           H0_uqff,
        "H0_sm_observed_kmspMpc":    H0_past_observed,
        "sigma_sm_observed":         sigma_past,
        "delta_uqff_minus_sm":       d_past,
        "n_sigma_uqff_vs_sm":        n_past,
        "compatible_1sigma":         abs(d_past) < sigma_past,
        "sm_source":                 "Freedman+ 2001 ApJ 553 47 (HST Key Project, 1999 data)",
    }
    present = _l96_h0_tension_uqff_vs_sm_probe(target_anchor_kmspMpc,
                                                 H0_present_cmb, sigma_present_cmb,
                                                 H0_present_local, sigma_present_local)
    present["year"] = 2026.0
    future = {
        "year":                       float(year_future),
        "H0_uqff_kmspMpc":            H0_uqff,
        "H0_sm_projected":            None,
        "uqff_falsifiable_at_year":   ("If sub-percent measurement at this epoch gives "
                                        "H_0 outside [67.4 - X, 67.4 + X] km/s/Mpc with X = "
                                        "expected combined sigma_Roman+sigma_Euclid+sigma_CMB-S4 "
                                        "~ 0.1 km/s/Mpc, UQFF strict-static is ruled out."),
        "sm_status_in_2026":          ("SM still resolving Planck-vs-SH0ES 5 sigma tension "
                                        "via proposed early/late-dark-energy, modified gravity, "
                                        "or systematic-error reconciliation"),
    }
    return {
        "year_past":          float(year_past),
        "year_present":       2026.0,
        "year_future":        float(year_future),
        "H0_uqff_static_all_epochs":  H0_uqff,
        "past":               past,
        "present":            present,
        "future":             future,
        "uqff_prediction":    ("Strict-static ledger (PAPER_1170) => H_0 = constant at "
                                f"{H0_uqff:.2f} km/s/Mpc for ALL epochs. 127-year forward "
                                "and backward extrapolation requires zero new parameters."),
        "uqff_basis":         "PAPER_1170 closed vacuum ledger + PAPER_1178 strict-static",
    }

_JWST_JADES_Z14_Z              = 14.32
_JWST_JADES_Z14_MSTAR_OBS_MSUN = 5.0e8
_JWST_JADES_Z14_MSTAR_LO_MSUN  = 5.0e8
_JWST_JADES_Z14_MSTAR_HI_MSUN  = 1.0e9
_JWST_JADES_Z14_AGE_MYR_AFTER_BB = 290.0
_LCDM_HIGH_Z_MSTAR_TYPICAL_MSUN = 10.0 ** 7.5
_LCDM_HIGH_Z_MSTAR_OPTIMISTIC_MSUN = 10.0 ** 8.0

def _l96_uqff_delta_R26_growth_correction(rho_R26_J_m3: float = None,
                                            rho_Lambda_obs_J_m3: float = None,
                                            v_UA: float = _V_UA_DEFAULT,
                                            rho_SCm_val: float = None) -> float:
    r26 = (_l96_rho_lambda_R26_curvature(v_UA, rho_SCm_val)
           if rho_R26_J_m3 is None else rho_R26_J_m3)
    rL  = _PLANCK_RHO_LAMBDA_J_M3 if rho_Lambda_obs_J_m3 is None else rho_Lambda_obs_J_m3
    dim_ratio = (float(D_BSFG) / float(D_CRIT)) ** 4
    density_ratio = r26 / rL
    return dim_ratio * density_ratio

def _l96_uqff_growth_ratio_D_UQFF_over_D_LCDM(rho_R26_J_m3: float = None,
                                                rho_Lambda_obs_J_m3: float = None,
                                                v_UA: float = _V_UA_DEFAULT,
                                                rho_SCm_val: float = None) -> float:
    dR26 = _l96_uqff_delta_R26_growth_correction(rho_R26_J_m3, rho_Lambda_obs_J_m3,
                                                   v_UA, rho_SCm_val)
    return 1.0 - 0.5 * dR26

def _l96_uqff_mstar_high_z_literal(M_star_LCDM_baseline_msun: float = _LCDM_HIGH_Z_MSTAR_TYPICAL_MSUN,
                                     power: float = 1.0,
                                     rho_R26_J_m3: float = None,
                                     rho_Lambda_obs_J_m3: float = None,
                                     v_UA: float = _V_UA_DEFAULT,
                                     rho_SCm_val: float = None) -> float:
    ratio = _l96_uqff_growth_ratio_D_UQFF_over_D_LCDM(rho_R26_J_m3, rho_Lambda_obs_J_m3,
                                                       v_UA, rho_SCm_val)
    return M_star_LCDM_baseline_msun * (ratio ** power)

def _l96_jwst_jades_z14_vs_uqff_probe(z: float = _JWST_JADES_Z14_Z,
                                        M_star_obs_msun: float = _JWST_JADES_Z14_MSTAR_OBS_MSUN,
                                        M_star_obs_lo_msun: float = _JWST_JADES_Z14_MSTAR_LO_MSUN,
                                        M_star_obs_hi_msun: float = _JWST_JADES_Z14_MSTAR_HI_MSUN,
                                        M_star_LCDM_baseline_msun: float = _LCDM_HIGH_Z_MSTAR_TYPICAL_MSUN,
                                        power: float = 1.0,
                                        rho_R26_J_m3: float = None,
                                        rho_Lambda_obs_J_m3: float = None,
                                        v_UA: float = _V_UA_DEFAULT,
                                        rho_SCm_val: float = None) -> Dict[str, Any]:
    dR26  = _l96_uqff_delta_R26_growth_correction(rho_R26_J_m3, rho_Lambda_obs_J_m3,
                                                   v_UA, rho_SCm_val)
    ratio = 1.0 - 0.5 * dR26
    M_uq  = M_star_LCDM_baseline_msun * (ratio ** power)
    log_obs  = math.log10(M_star_obs_msun)
    log_lcdm = math.log10(M_star_LCDM_baseline_msun)
    log_uq   = math.log10(M_uq)
    decades_lcdm = log_lcdm - log_obs
    decades_uq   = log_uq   - log_obs
    uqff_in_jwst_envelope = (M_star_obs_lo_msun <= M_uq <= M_star_obs_hi_msun)
    summary = (
        f"PAPER_1176 literal closed form: delta_R26 = {dR26:.4e}, "
        f"D_UQFF/D_LCDM = {ratio:.9f}. M_star^UQFF (literal) = {M_uq:.3e} M_sun. "
        f"JWST observation = {M_star_obs_msun:.3e} M_sun. LCDM reference baseline = "
        f"{M_star_LCDM_baseline_msun:.3e} M_sun (contextual datapoints supplied by user spec)."
    )
    return {
        "z":                          z,
        "age_Myr_after_BB":           _JWST_JADES_Z14_AGE_MYR_AFTER_BB,
        "M_star_obs_msun":            M_star_obs_msun,
        "M_star_obs_lo_msun":         M_star_obs_lo_msun,
        "M_star_obs_hi_msun":         M_star_obs_hi_msun,
        "M_star_LCDM_baseline_msun":  M_star_LCDM_baseline_msun,
        "M_star_UQFF_literal_msun":   M_uq,
        "delta_R26":                  dR26,
        "D_UQFF_over_D_LCDM":         ratio,
        "growth_power":               power,
        "log10_M_star_obs":           log_obs,
        "log10_M_star_LCDM":          log_lcdm,
        "log10_M_star_UQFF":          log_uq,
        "decades_LCDM_minus_obs":     decades_lcdm,
        "decades_UQFF_minus_obs":     decades_uq,
        "uqff_in_jwst_envelope":      uqff_in_jwst_envelope,
        "summary":                    summary,
        "jwst_basis":                 "Helton+ 2025 JADES-GS-z14-0 spec-z=14.32, NASA/JWST 2024-2025",
        "lcdm_reference_basis":       ("LCDM galaxy formation references (FIRE, IllustrisTNG, EAGLE "
                                        "high-z extensions); supplied as contextual datapoint only"),
        "uqff_basis":                 "PAPER_1176 R26 vacuum-impedance growth-factor correction "
                                       "(literal closed form)",
    }

def _l96_bh_hawking_temperature_K(M_msun: float = 10.0) -> float:
    M_kg = float(M_msun) * M_SUN
    hbar = PLANCK_H / (2.0 * math.pi)
    return hbar * (C_LIGHT ** 3) / (8.0 * math.pi * G_NEWTON * M_kg * K_B)

def _l96_bh_schwarzschild_area_m2(M_msun: float = 10.0) -> float:
    M_kg = float(M_msun) * M_SUN
    R_s  = 2.0 * G_NEWTON * M_kg / (C_LIGHT ** 2)
    return 4.0 * math.pi * R_s * R_s

def _l96_sm_S_BH_over_kB(M_msun: float = 10.0) -> float:
    M_kg = float(M_msun) * M_SUN
    hbar = PLANCK_H / (2.0 * math.pi)
    return 4.0 * math.pi * G_NEWTON * M_kg * M_kg / (hbar * C_LIGHT)

def _l96_uqff_paper1095_scm_multiplier(M_msun: float = 10.0,
                                         delta_SCm_J: float = None,
                                         phi_norm: float = 1.0) -> float:
    if delta_SCm_J is None:
        delta_SCm_J = DELTA_SCM_J
    T_H = _l96_bh_hawking_temperature_K(M_msun)
    correction = delta_SCm_J / (K_B * T_H)
    return (1.0 + correction) * S26_DPM * phi_norm

def _l96_uqff_S_Page_literal_over_kB(M_msun: float = 10.0,
                                       delta_SCm_J: float = None,
                                       phi_norm: float = 1.0) -> float:
    hbar = PLANCK_H / (2.0 * math.pi)
    ell_P2 = hbar * G_NEWTON / (C_LIGHT ** 3)
    A = _l96_bh_schwarzschild_area_m2(M_msun)
    A_over_4lp2 = A / (4.0 * ell_P2)
    return A_over_4lp2 * _l96_uqff_paper1095_scm_multiplier(M_msun, delta_SCm_J, phi_norm)

def _l96_uqff_S_Page_capped_over_kB(M_msun: float = 10.0) -> float:
    return _l96_sm_S_BH_over_kB(M_msun)

def _l96_uqff_S_Page_stationary_derived_over_kB(M_msun: float = 10.0) -> float:
    hbar = PLANCK_H / (2.0 * math.pi)
    ell_P2 = hbar * G_NEWTON / (C_LIGHT ** 3)
    A = _l96_bh_schwarzschild_area_m2(M_msun)
    S_BH_geom_over_kB = A / (4.0 * ell_P2)
    N_ch_int = 9
    Phi_RES_rational = 5.0 / 6.0
    D_phys_over_D_BSFG = 4.0 / 6.0
    page_time_fraction = 0.5 * ((N_ch_int - 1) / N_ch_int) * Phi_RES_rational
    remaining_fraction = 1.0 - page_time_fraction
    cap_factor = remaining_fraction ** D_phys_over_D_BSFG
    return S_BH_geom_over_kB * cap_factor

def _l96_uqff_S_Page_cap_factor_PAPER1213() -> float:
    N_ch_int = 9
    Phi_RES_rational = 5.0 / 6.0
    D_phys_over_D_BSFG = 4.0 / 6.0
    page_time_fraction = 0.5 * ((N_ch_int - 1) / N_ch_int) * Phi_RES_rational
    remaining_fraction = 1.0 - page_time_fraction
    return remaining_fraction ** D_phys_over_D_BSFG

def _l96_page_curve_paradox_probe(M_msun: float = 10.0,
                                    delta_SCm_J: float = None,
                                    phi_norm: float = 1.0) -> Dict[str, Any]:
    if delta_SCm_J is None:
        delta_SCm_J = DELTA_SCM_J
    M_kg = float(M_msun) * M_SUN
    R_s  = 2.0 * G_NEWTON * M_kg / (C_LIGHT ** 2)
    A    = _l96_bh_schwarzschild_area_m2(M_msun)
    T_H  = _l96_bh_hawking_temperature_K(M_msun)
    scm_ratio = delta_SCm_J / (K_B * T_H)
    scm_mult  = (1.0 + scm_ratio) * S26_DPM * phi_norm
    S_ref     = _l96_sm_S_BH_over_kB(M_msun)
    S_uq_lit  = _l96_uqff_S_Page_literal_over_kB(M_msun, delta_SCm_J, phi_norm)
    S_uq_cap  = _l96_uqff_S_Page_capped_over_kB(M_msun)
    S_uq_der  = _l96_uqff_S_Page_stationary_derived_over_kB(M_msun)
    cap_factor = _l96_uqff_S_Page_cap_factor_PAPER1213()
    log10_ratio_lit  = math.log10(S_uq_lit / S_ref)
    log10_ratio_der  = math.log10(S_uq_lit / S_uq_der)
    derived_vs_ref   = (S_uq_der - S_ref) / S_ref
    kk_bound = _l96_uqff_paper1168_p3_kk_suppression_bound()
    summary = (
        f"PAPER_1095 literal product: S_Page^UQFF = {S_uq_lit:.4e} k_B. "
        f"PAPER_1183 first-principles variational derived (NO GR passthrough): "
        f"{S_uq_der:.4e} k_B = (17/27)^(2/3) * (A/4 ell_P^2). "
        f"Asserted F_U=1 saturation form (GR identity): {S_uq_cap:.4e} k_B. "
        f"Bekenstein-Hawking reference (SM): {S_ref:.4e} k_B. "
        f"SCm correction ratio delta_SCm/(k_B T_H) = {scm_ratio:.3e}. "
        f"Literal-to-derived collapse: 10^{log10_ratio_der:.2f} "
        f"(matches PAPER_1168 P3 KK bound 1/26^26 = {kk_bound:.3e}). "
        f"UQFF-vs-SM signature: derived = {derived_vs_ref*100:+.2f}% relative to S_BH."
    )
    return {
        "M_msun":                              float(M_msun),
        "R_s_m":                               R_s,
        "area_m2":                             A,
        "T_H_K":                               T_H,
        "delta_SCm_J":                         delta_SCm_J,
        "delta_SCm_eV":                        delta_SCm_J / EV_J,
        "scm_correction_ratio":                scm_ratio,
        "scm_multiplier_uncapped":             scm_mult,
        "S_BH_reference_over_kB":              S_ref,
        "S_Page_UQFF_literal_over_kB":         S_uq_lit,
        "S_Page_UQFF_capped_over_kB":          S_uq_cap,
        "S_Page_UQFF_derived_over_kB":         S_uq_der,
        "cap_factor_17over27_to_2over3":       cap_factor,
        "derived_vs_reference_fractional":     derived_vs_ref,
        "log10_ratio_literal_over_reference":  log10_ratio_lit,
        "log10_ratio_literal_over_derived":    log10_ratio_der,
        "kk_suppression_bound_PAPER1168_P3":   kk_bound,
        "capped_equals_reference":             bool(abs(S_uq_cap - S_ref) / S_ref < 1e-12),
        "summary":                             summary,
        "paper_basis":                         "PAPER_1095 horizon-buoyancy Lagrangian + SCm shell gap + "
                                                "S_26=1.4531e26 + Phi_1.25THz + F_U=1 ledger closure; "
                                                "PAPER_1183 first-principles variational derivation "
                                                "(delta S/delta r = 0 SymPy residual 0); PAPER_1166 "
                                                "Mexican-hat V(U_A) minimum K_Mex=25/12; PAPER_1213 "
                                                "Page-time channel partition t_P/t_evap = 10/27; "
                                                "PAPER_1168 P3 / PAPER_1170 §4 KK suppression 1/26^26.",
    }

_KK_SUPPRESSION_BOUND = 1.0 / (26.0 ** 26)

def _l96_uqff_paper1168_p3_kk_suppression_bound() -> float:
    return _KK_SUPPRESSION_BOUND

_LENR_KAPPA_PER_DAY = 5.0e-4
_LENR_EPSILON_CLUSTER_EV = 630.0
_LENR_EPSILON_CLUSTER_J  = _LENR_EPSILON_CLUSTER_EV * EV_J
_LENR_PD_ATOMIC_DENSITY  = 6.8e28
_LENR_F_ACTIVE_DEFAULT   = 0.01

def _l96_uqff_lenr_holmlid_KER_eV(omega_THz: float = 1.25e12,
                                     S26_amp: float = None,
                                     phi_norm: float = None) -> float:
    if S26_amp is None:
        S26_amp = S26_3
    if phi_norm is None:
        phi_norm = PHI_RESONANCE
    return (PLANCK_H * omega_THz / EV_J) * S26_amp * phi_norm

def _l96_uqff_lenr_unified_power_W(N_eff: float,
                                      t_hours: float = 1.0,
                                      f_b: float = 1.0,
                                      kappa_per_day: float = None,
                                      epsilon_cluster_J: float = None) -> float:
    if kappa_per_day is None:
        kappa_per_day = _LENR_KAPPA_PER_DAY
    if epsilon_cluster_J is None:
        epsilon_cluster_J = _LENR_EPSILON_CLUSTER_J
    decay = math.exp(-kappa_per_day * t_hours * 24.0)
    return N_eff * epsilon_cluster_J * decay * f_b

def _l96_uqff_lenr_parkhomov_power_W(N_clusters: float = 2.0e18,
                                        t_hours: float = 1.0,
                                        f_b: float = 1.0) -> float:
    return _l96_uqff_lenr_unified_power_W(N_clusters, t_hours, f_b)

def _l96_uqff_lenr_pons_fleischmann_power_W(PdD_loading: float = 0.9,
                                                V_m3: float = 1.0e-6,
                                                f_active: float = None,
                                                f_b: float = None,
                                                t_hours: float = 1.0) -> float:
    if f_active is None:
        f_active = _LENR_F_ACTIVE_DEFAULT
    if f_b is None:
        f_b = PHI_RESONANCE
    N_per_sec = PdD_loading * V_m3 * _LENR_PD_ATOMIC_DENSITY * f_active / 3600.0
    return _l96_uqff_lenr_unified_power_W(N_per_sec, t_hours, f_b)

def _l96_uqff_lenr_mizuno_power_W(N_M: float = 1.0e20,
                                     t_hours: float = 1.0,
                                     f_b: float = 1.2e-3) -> float:
    return _l96_uqff_lenr_unified_power_W(N_M, t_hours, f_b)

def _l96_uqff_lenr_rossi_ecat_COP(N_clusters: float = 5.0e18,
                                     P_input_W: float = 100.0,
                                     t_hours: float = 1.0,
                                     f_b: float = 1.0) -> float:
    P_excess = _l96_uqff_lenr_unified_power_W(N_clusters, t_hours, f_b)
    return P_excess / P_input_W

