_PA1209_FTRZ      = 1.0 / 10.0
_PA1209_PHIRES    = 5.0 / 6.0
_PA1209_SSQ       = 57.0 / 100.0
_PA1209_KMEX      = 25.0 / 12.0
_PA1209_DPHYS     = 4
_PA1209_DBSFG     = 6
_PA1209_DCRIT     = 26
_PA1209_NCH       = 9
_PA1209_SO5       = 10
_PA1209_A5        = 60

def _ft():  return _PA1209_FTRZ
def _ph():  return _PA1209_PHIRES
def _sq():  return _PA1209_SSQ
def _km():  return _PA1209_KMEX
def _dp():  return _PA1209_DPHYS
def _db():  return _PA1209_DBSFG
def _dc():  return _PA1209_DCRIT
def _nc():  return _PA1209_NCH
def _so():  return _PA1209_SO5
def _a5():  return _PA1209_A5

def _l96_uqff_m_W_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, so, a5 = _ft(), _dp(), _db(), _sq(), _so(), _a5()
    return a5 + 2*so + f*dp - f*f*db + f*f*dp - f*f*sq*sq

def _l96_uqff_m_Z_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, nc, so = _ft(), _dp(), _db(), _sq(), _nc(), _so()
    return nc*so + f*so + f*f*so + f*f*db + f*f*dp + f*f*sq - f*f*sq*sq*sq

def _l96_uqff_m_t_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, nc, so, dc, a5 = _ft(), _dp(), _db(), _sq(), _nc(), _so(), _dc(), _a5()
    return (dc*so - a5 - dp*nc + so - f*dp - f*so
            + f*f*db + 2*f*f*dp + f*f*sq + f*f*sq*sq + f*f*sq*sq*sq)

def _l96_uqff_m_H_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, nc, a5 = _ft(), _dp(), _db(), _sq(), _nc(), _a5()
    return 2*a5 + nc - dp + f*sq + f*f*db + f*f*sq*sq

def _l96_uqff_m_b_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, dc = _ft(), _dp(), _db(), _sq(), _dc()
    return (dp + f*dp - f*sq - f*f*dc + f*f*db + f*f*dp
            - f*f*sq*sq - f*f*sq*sq*sq)

def _l96_uqff_m_c_PAPER1209HH_GeV() -> float:
    f, dp, sq, so, dc = _ft(), _dp(), _sq(), _so(), _dc()
    return (f*dc - f*dp - f*so + f*f*so - f*f*dp
            + f*f*sq + f*f*sq*sq + f*f*sq*sq*sq)

def _l96_uqff_m_tau_PAPER1209HH_GeV() -> float:
    f, dp, db, sq, so, dc = _ft(), _dp(), _db(), _sq(), _so(), _dc()
    return (sq + f*dp + f*so - f*f*dc + f*f*db
            + f*f*sq + f*f*sq*sq - f*f*sq*sq*sq)

def _l96_uqff_m_mu_PAPER1209HH_GeV() -> float:
    f, sq, so = _ft(), _sq(), _so()
    return f*f*so + f*f*sq*sq + f*f*sq*sq*sq + f*f*(sq**5)

def _l96_uqff_m_s_PAPER1209HH_GeV() -> float:
    f, sq, so = _ft(), _sq(), _so()
    return f*f*so - f*f*sq*sq - f*f*sq*sq*sq

def _l96_uqff_m_e_PAPER1209HH_GeV() -> float:
    f, sq = _ft(), _sq()
    return f*f*f*sq*sq + f*f*f*sq*sq*sq

def _l96_uqff_proton_mass_PAPER1155_kg() -> float:
    return (RHO_SCM / _PA1209_SSQ) * A_26

def _l96_uqff_neutron_mass_PAPER1155_kg() -> float:
    return _l96_uqff_proton_mass_PAPER1155_kg()

