def _l96_uqff_neutron_star_eos_closure(M_msun: float = None,
                                         R_km: float = None) -> Dict[str, Any]:
    if M_msun is None:
        M_msun = NS_NICER_J0030_M_MSUN
    if R_km is None:
        R_km = NS_NICER_J0030_R_KM
    M_kg = M_msun * M_SUN
    R_m = R_km * 1000.0
    compactness = G_NEWTON * M_kg / (R_m * (C_LIGHT ** 2))
    schwarzschild_factor = 2.0 * G_NEWTON * M_kg / (R_m * (C_LIGHT ** 2))
    rho_central_kg_per_m3 = M_kg / ((4.0 / 3.0) * math.pi * (R_m ** 3))
    R_uqff_correction_factor = 1.0 + BETA_I * TRZ * PHI_RESONANCE * SSQ
    R_uqff_km = R_km * R_uqff_correction_factor
    return {
        "M_msun":                                  M_msun,
        "R_km_observed":                           R_km,
        "R_km_uqff_corrected":                     R_uqff_km,
        "compactness_GM_over_R_c_squared":         compactness,
        "schwarzschild_factor_2GM_over_R_c_sq":    schwarzschild_factor,
        "rho_central_kg_per_m3":                   rho_central_kg_per_m3,
        "nicer_j0030_M_msun":                      NS_NICER_J0030_M_MSUN,
        "nicer_j0030_R_km":                        NS_NICER_J0030_R_KM,
        "gw170817_M_max_msun":                     NS_GW170817_M_MAX_MSUN,
        "tov_limit_msun":                          NS_TOV_LIMIT_MSUN,
        "M_above_tov_limit":                       M_msun > NS_TOV_LIMIT_MSUN,
        "uqff_R_correction_form":                  "one_plus_BETA_I_TRZ_PHI_SSQ_locked_primitive_modulation",
        "TOV_equation_form":                       "dP_dr_eq_minus_G_rho_M_over_r_sq_plus_relativistic_corrections",
        "primary_result":                          R_uqff_km,
        "primary_source":                          "NICER_PSR_J0030_PAPER_1126_plus_LIGO_GW170817_PAPER_914_with_UQFF_SCm_correction",
    }

def _l96_uqff_smarr_formula_closure(M_msun: float = 10.0,
                                      a_star: float = 0.0,
                                      Q_coulombs: float = 0.0) -> Dict[str, Any]:
    M_kg     = M_msun * M_SUN
    A        = _l96_bh_schwarzschild_area_m2(M_msun)
    kappa    = (C_LIGHT ** 4) / (4.0 * G_NEWTON * M_kg)
    kappa_A_over_4pi = kappa * A / (4.0 * math.pi)
    omega_horizon = a_star * (C_LIGHT ** 3) / (2.0 * G_NEWTON * M_kg)
    J_kg_m2_per_s = a_star * G_NEWTON * (M_kg ** 2) / C_LIGHT
    M_smarr_J = kappa_A_over_4pi / (C_LIGHT ** 2) + 2.0 * omega_horizon * J_kg_m2_per_s
    M_smarr_kg = M_smarr_J / (C_LIGHT ** 2)
    return {
        "M_msun":                                  M_msun,
        "M_kg":                                    M_kg,
        "spin_a_star":                             a_star,
        "Q_coulombs":                              Q_coulombs,
        "surface_gravity_kappa_m_per_s2":          kappa,
        "horizon_area_m2":                         A,
        "kappa_A_over_4pi":                        kappa_A_over_4pi,
        "omega_horizon_rad_per_s":                 omega_horizon,
        "angular_momentum_J_kg_m2_per_s":          J_kg_m2_per_s,
        "M_smarr_total_J":                         M_smarr_J,
        "M_smarr_total_kg":                        M_smarr_kg,
        "smarr_formula_form":                      "M_eq_kappa_A_over_4pi_plus_2_Omega_J_plus_Phi_Q",
        "primary_result":                          M_smarr_kg,
        "primary_source":                          "Smarr_1973_BH_mass_formula_PAPER_087_via_horizon_buoyancy_in_UQFF",
    }

def _l96_uqff_bekenstein_bound_closure(E_joules: float = 1.0e-19,
                                        R_m: float = 1.0e-10) -> Dict[str, Any]:
    HBAR = PLANCK_H / (2.0 * math.pi)
    S_max_over_kB = BEKENSTEIN_BOUND_PREFACTOR * E_joules * R_m / (HBAR * C_LIGHT)
    S_max_J_per_K = S_max_over_kB * K_B
    S_per_volume = S_max_over_kB / ((4.0 / 3.0) * math.pi * (R_m ** 3))
    return {
        "E_joules":                                E_joules,
        "R_m":                                     R_m,
        "bekenstein_S_max_over_kB":                S_max_over_kB,
        "bekenstein_S_max_J_per_K":                S_max_J_per_K,
        "bekenstein_S_per_volume":                 S_per_volume,
        "prefactor_2pi":                           BEKENSTEIN_BOUND_PREFACTOR,
        "bekenstein_bound_form":                   "S_leq_2pi_E_R_over_hbar_c",
        "violates_bound_if_S_exceeds":             False,
        "saturated_by_black_hole_horizon":         True,
        "primary_result":                          S_max_over_kB,
        "primary_source":                          "Bekenstein_1981_universal_entropy_bound_PAPER_087_in_UQFF_with_kBhc_normalization",
    }

