def _l96_uqff_goldstone_theorem_closure(n_broken_global_generators: int = 3,
                                          n_broken_gauge_generators: int = 3) -> Dict[str, Any]:
    n_NG_bosons = n_broken_global_generators
    n_eaten_by_gauge = n_broken_gauge_generators
    n_physical_NG = max(0, n_NG_bosons - n_eaten_by_gauge)
    return {
        "n_broken_global_generators":            n_broken_global_generators,
        "n_broken_gauge_generators":             n_broken_gauge_generators,
        "n_Nambu_Goldstone_bosons":              n_NG_bosons,
        "n_eaten_by_gauge_bosons":               n_eaten_by_gauge,
        "n_physical_NG_remaining":               n_physical_NG,
        "goldstone_form":                        "n_NG_eq_n_broken_generators_global_or_eaten_by_gauge",
        "massless_NG_for_global":                n_broken_gauge_generators == 0,
        "Higgs_mechanism_eats_NG":               n_broken_gauge_generators > 0,
        "primary_result":                        n_physical_NG,
        "primary_source":                        "Goldstone_Salam_Weinberg_1962_theorem_PAPER_034_with_Higgs_mechanism_NG_eating",
    }

