def _l96_uqff_casimir_effect_closure(a_separation_m: float = 1.0e-6) -> Dict[str, Any]:
    HBAR = PLANCK_H / (2.0 * math.pi)
    F_over_A_N_per_m2 = HBAR * C_LIGHT * (math.pi ** 2) / (240.0 * (a_separation_m ** 4))
    energy_density_J_per_m3 = -HBAR * C_LIGHT * (math.pi ** 2) / (720.0 * (a_separation_m ** 4))
    return {
        "separation_a_m":                        a_separation_m,
        "casimir_pressure_N_per_m2":             F_over_A_N_per_m2,
        "casimir_energy_density_J_per_m3":       energy_density_J_per_m3,
        "expected_at_1um":                       CASIMIR_PARALLEL_PLATES_N_PER_M2_AT_1UM,
        "casimir_form":                          "F_over_A_eq_hbar_c_pi_sq_over_240_a_to_4",
        "attractive_force":                      True,
        "vacuum_boundary_effect":                True,
        "verified_Lamoreaux_1997_Mohideen_1998": True,
        "primary_result":                        F_over_A_N_per_m2,
        "primary_source":                        "Casimir_1948_vacuum_energy_PAPER_1051_between_conducting_plates_in_UQFF_zero_point",
    }

def _l96_uqff_schwinger_effect_closure(E_field_V_per_m: float = 1.0e16) -> Dict[str, Any]:
    M_e_KG = 9.1093837015e-31
    E_KG = 1.602176634e-19
    HBAR = PLANCK_H / (2.0 * math.pi)
    E_critical = (M_e_KG ** 2) * (C_LIGHT ** 3) / (E_KG * HBAR)
    ratio = E_field_V_per_m / E_critical
    exponent_arg = -math.pi / ratio if ratio > 0 else float("inf")
    if exponent_arg < -700.0:
        rate_factor = 0.0
    elif exponent_arg > 700.0:
        rate_factor = float("inf")
    else:
        rate_factor = math.exp(exponent_arg)
    pair_production_active = E_field_V_per_m > E_critical
    return {
        "E_field_V_per_m":                       E_field_V_per_m,
        "E_critical_Schwinger_V_per_m":          E_critical,
        "ratio_E_over_E_critical":               ratio,
        "exponent_minus_pi_E_critical_over_E":   exponent_arg,
        "rate_factor_exp":                       rate_factor,
        "pair_production_active":                pair_production_active,
        "schwinger_form":                        "Gamma_per_volume_eq_e_E_sq_over_4pi_cubed_hbar_sq_times_sum_exp_minus_n_pi_E_c_over_E",
        "vacuum_decay_into_pairs":               pair_production_active,
        "verified_in_high_intensity_lasers":     False,
        "primary_result":                        rate_factor,
        "primary_source":                        "Schwinger_1951_QED_vacuum_polarization_PAPER_1373_pair_production_in_strong_field",
    }

