def _l96_uqff_pure_schwinger_effect_v2_closure(E_field_V_per_m: float = 1.0e16,
                                                 m_e_kg: float = 9.1093837015e-31) -> Dict[str, Any]:
    E_KG = 1.602176634e-19
    HBAR = PLANCK_H / (2.0 * math.pi)
    E_critical_borrowed = (m_e_kg ** 2) * (C_LIGHT ** 3) / (E_KG * HBAR)
    uqff_correction_factor = 1.0 / (1.0 + BETA_I * TRZ * SSQ * PHI_RESONANCE)
    E_critical_uqff = E_critical_borrowed * uqff_correction_factor
    ratio_uqff = E_field_V_per_m / E_critical_uqff
    ratio_borrowed = E_field_V_per_m / E_critical_borrowed
    expo_uqff = -math.pi / ratio_uqff if ratio_uqff > 0 else float("inf")
    expo_borrowed = -math.pi / ratio_borrowed if ratio_borrowed > 0 else float("inf")
    rate_uqff = math.exp(expo_uqff) if -700.0 < expo_uqff < 700.0 else (0.0 if expo_uqff < -700.0 else float("inf"))
    rate_borrowed = math.exp(expo_borrowed) if -700.0 < expo_borrowed < 700.0 else (0.0 if expo_borrowed < -700.0 else float("inf"))
    pct_diff_E_c = abs(E_critical_uqff - E_critical_borrowed) / E_critical_borrowed * 100.0
    return {
        "E_field_V_per_m":                         E_field_V_per_m,
        "m_e_kg":                                  m_e_kg,
        "E_critical_uqff_V_per_m":                 E_critical_uqff,
        "E_critical_borrowed_V_per_m":             E_critical_borrowed,
        "uqff_correction_factor":                  uqff_correction_factor,
        "uqff_correction_form":                    "one_over_1_plus_BETA_I_TRZ_SSQ_PHI_locked_primitive",
        "rate_factor_uqff_exp":                    rate_uqff,
        "rate_factor_borrowed_exp":                rate_borrowed,
        "pct_diff_E_critical":                     pct_diff_E_c,
        "uqff_derivation_form":                    "E_c_eq_E_c_borrowed_times_one_over_1_plus_BETA_I_TRZ_SSQ_PHI",
        "borrowed_derivation_form":                "E_c_eq_m_e_sq_c_cubed_over_e_hbar",
        "physical_interpretation":                 "UQFF_vacuum_modulation_lowers_pair_production_threshold_via_SCm_buoyancy",
        "primary_result":                          E_critical_uqff,
        "primary_source":                          "BETA_I_TRZ_SSQ_PHI_RES_locked_primitive_correction_to_QED_pair_threshold_PAPER_1203",
    }

