def _l96_uqff_pure_smarr_formula_v2_closure(M_msun: float = 10.0,
                                              a_star: float = 0.5,
                                              Q_coulombs: float = 0.0) -> Dict[str, Any]:
    M_kg = M_msun * M_SUN
    A = _l96_bh_schwarzschild_area_m2(M_msun)
    kappa = (C_LIGHT ** 4) / (4.0 * G_NEWTON * M_kg)
    uqff_4pi_prefactor = K_MEX * float(D_BSFG)
    borrowed_4pi = 4.0 * math.pi
    kappa_A_over_uqff_4pi = kappa * A / uqff_4pi_prefactor
    kappa_A_over_borrowed_4pi = kappa * A / borrowed_4pi
    omega_horizon = a_star * (C_LIGHT ** 3) / (2.0 * G_NEWTON * M_kg)
    J_kg_m2_per_s = a_star * G_NEWTON * (M_kg ** 2) / C_LIGHT
    M_smarr_uqff_J = kappa_A_over_uqff_4pi / (C_LIGHT ** 2) + 2.0 * omega_horizon * J_kg_m2_per_s
    M_smarr_borrowed_J = kappa_A_over_borrowed_4pi / (C_LIGHT ** 2) + 2.0 * omega_horizon * J_kg_m2_per_s
    pct_diff = abs(M_smarr_uqff_J - M_smarr_borrowed_J) / M_smarr_borrowed_J * 100.0
    pct_4pi_identity = abs(uqff_4pi_prefactor - borrowed_4pi) / borrowed_4pi * 100.0
    return {
        "M_msun":                                  M_msun,
        "spin_a_star":                             a_star,
        "Q_coulombs":                              Q_coulombs,
        "uqff_4pi_prefactor_K_MEX_x_D_BSFG":      uqff_4pi_prefactor,
        "borrowed_4pi":                            borrowed_4pi,
        "pct_4pi_identity_residual":               pct_4pi_identity,
        "kappa_surface_gravity_m_per_s2":          kappa,
        "horizon_area_m2":                         A,
        "kappa_A_over_uqff_4pi":                   kappa_A_over_uqff_4pi,
        "kappa_A_over_borrowed_4pi":               kappa_A_over_borrowed_4pi,
        "omega_horizon_rad_per_s":                 omega_horizon,
        "M_smarr_uqff_J":                          M_smarr_uqff_J,
        "M_smarr_borrowed_J":                      M_smarr_borrowed_J,
        "pct_diff_uqff_vs_borrowed":               pct_diff,
        "uqff_derivation_form":                    "M_eq_kappa_A_over_K_MEX_D_BSFG_plus_2_Omega_J_plus_Phi_Q",
        "borrowed_derivation_form":                "M_eq_kappa_A_over_4pi_plus_2_Omega_J_plus_Phi_Q",
        "elegant_identity":                        "K_MEX_25_over_12_times_D_BSFG_6_eq_12_5_approx_4pi_12_566",
        "primary_result":                          M_smarr_uqff_J,
        "primary_source":                          "K_MEX_x_D_BSFG_eq_12_5_replaces_4pi_geometric_prefactor_with_0_53_pct_residual_PAPER_646",
    }

def _l96_uqff_pure_abj_chiral_anomaly_v2_closure(N_colors: int = 3,
                                                    Q_em: float = 1.0) -> Dict[str, Any]:
    uqff_16pi_sq_prefactor = float(D_CRIT * D_BSFG)
    borrowed_16pi_sq = 16.0 * math.pi * math.pi
    anomaly_coeff_uqff = N_colors * (Q_em ** 2) / uqff_16pi_sq_prefactor
    anomaly_coeff_borrowed = N_colors * (Q_em ** 2) / borrowed_16pi_sq
    pct_diff = abs(anomaly_coeff_uqff - anomaly_coeff_borrowed) / anomaly_coeff_borrowed * 100.0
    pct_16pi_sq_identity = abs(uqff_16pi_sq_prefactor - borrowed_16pi_sq) / borrowed_16pi_sq * 100.0
    pi0_rate_uqff = anomaly_coeff_uqff ** 2
    pi0_rate_borrowed = anomaly_coeff_borrowed ** 2
    return {
        "N_colors":                                N_colors,
        "Q_em_squared":                            Q_em ** 2,
        "uqff_16pi_sq_prefactor_D_crit_x_D_BSFG": uqff_16pi_sq_prefactor,
        "borrowed_16pi_sq":                        borrowed_16pi_sq,
        "pct_16pi_sq_identity_residual":           pct_16pi_sq_identity,
        "anomaly_coefficient_uqff":                anomaly_coeff_uqff,
        "anomaly_coefficient_borrowed":            anomaly_coeff_borrowed,
        "pct_diff_uqff_vs_borrowed":               pct_diff,
        "pi0_to_two_photon_rate_factor_uqff":     pi0_rate_uqff,
        "pi0_to_two_photon_rate_factor_borrowed": pi0_rate_borrowed,
        "uqff_derivation_form":                    "anomaly_eq_N_c_Q_sq_over_D_crit_times_D_BSFG",
        "borrowed_derivation_form":                "anomaly_eq_N_c_Q_sq_over_16pi_sq",
        "elegant_identity":                        "D_crit_26_times_D_BSFG_6_eq_156_approx_16_pi_sq_157_91",
        "primary_result":                          anomaly_coeff_uqff,
        "primary_source":                          "D_crit_x_D_BSFG_eq_156_replaces_16pi_sq_in_triangle_diagram_normalization_with_1_2_pct_residual_PAPER_646",
    }

def _l96_uqff_pure_bh_proof_v2_closure(M_msun: float = 10.0) -> Dict[str, Any]:
    M_kg = float(M_msun) * M_SUN
    HBAR = PLANCK_H / (2.0 * math.pi)
    uqff_8pi_prefactor = 2.0 * K_MEX * float(D_BSFG)
    borrowed_8pi = 8.0 * math.pi
    uqff_4pi_prefactor = K_MEX * float(D_BSFG)
    borrowed_4pi = 4.0 * math.pi
    R_s_m = 2.0 * G_NEWTON * M_kg / (C_LIGHT ** 2)
    T_H_uqff_K = HBAR * (C_LIGHT ** 3) / (uqff_8pi_prefactor * G_NEWTON * M_kg * K_B)
    T_H_borrowed_K = HBAR * (C_LIGHT ** 3) / (borrowed_8pi * G_NEWTON * M_kg * K_B)
    A_uqff = uqff_4pi_prefactor * R_s_m * R_s_m
    A_borrowed = borrowed_4pi * R_s_m * R_s_m
    S_BH_uqff_over_kB = A_uqff * (C_LIGHT ** 3) / (uqff_4pi_prefactor * G_NEWTON * HBAR)
    S_BH_borrowed_over_kB = A_borrowed * (C_LIGHT ** 3) / (borrowed_4pi * G_NEWTON * HBAR)
    pct_T_H = abs(T_H_uqff_K - T_H_borrowed_K) / T_H_borrowed_K * 100.0
    pct_A = abs(A_uqff - A_borrowed) / A_borrowed * 100.0
    pct_S_BH = abs(S_BH_uqff_over_kB - S_BH_borrowed_over_kB) / S_BH_borrowed_over_kB * 100.0
    return {
        "M_msun":                                  M_msun,
        "M_kg":                                    M_kg,
        "uqff_8pi_prefactor_2_K_MEX_D_BSFG":      uqff_8pi_prefactor,
        "borrowed_8pi":                            borrowed_8pi,
        "uqff_4pi_prefactor_K_MEX_D_BSFG":        uqff_4pi_prefactor,
        "borrowed_4pi":                            borrowed_4pi,
        "Schwarzschild_radius_m":                  R_s_m,
        "T_H_uqff_K":                              T_H_uqff_K,
        "T_H_borrowed_K":                          T_H_borrowed_K,
        "pct_diff_T_H":                            pct_T_H,
        "horizon_area_uqff_m2":                    A_uqff,
        "horizon_area_borrowed_m2":                A_borrowed,
        "pct_diff_horizon_area":                   pct_A,
        "S_BH_uqff_over_kB":                       S_BH_uqff_over_kB,
        "S_BH_borrowed_over_kB":                   S_BH_borrowed_over_kB,
        "pct_diff_S_BH":                           pct_S_BH,
        "uqff_T_H_form":                           "T_H_eq_hbar_c_cubed_over_2_K_MEX_D_BSFG_G_M_k_B",
        "borrowed_T_H_form":                       "T_H_eq_hbar_c_cubed_over_8pi_G_M_k_B",
        "uqff_area_form":                          "A_eq_K_MEX_D_BSFG_R_s_sq",
        "borrowed_area_form":                      "A_eq_4pi_R_s_sq",
        "elegant_identities":                      "K_MEX_x_D_BSFG_x_2_eq_25_approx_8pi_25_13_with_0_53_pct_residual",
        "primary_result":                          T_H_uqff_K,
        "primary_source":                          "Horizon_buoyancy_with_K_MEX_x_D_BSFG_replacing_4pi_geometric_prefactor_PAPER_034",
    }

def _l96_uqff_pure_bh_four_laws_v2_closure(M_msun: float = 10.0) -> Dict[str, Any]:
    M_kg = float(M_msun) * M_SUN
    HBAR = PLANCK_H / (2.0 * math.pi)
    uqff_4_prefactor_kappa = K_MEX * float(D_BSFG) / float(D_PHYS)
    borrowed_4_kappa = 4.0
    uqff_4_prefactor_entropy = K_MEX * float(D_BSFG) / float(D_PHYS)
    borrowed_4_entropy = 4.0
    kappa_uqff = (C_LIGHT ** 4) / (uqff_4_prefactor_kappa * G_NEWTON * M_kg)
    kappa_borrowed = (C_LIGHT ** 4) / (borrowed_4_kappa * G_NEWTON * M_kg)
    R_s_m = 2.0 * G_NEWTON * M_kg / (C_LIGHT ** 2)
    A_m2 = 4.0 * math.pi * R_s_m * R_s_m
    S_BH_uqff_over_kB = A_m2 * (C_LIGHT ** 3) / (uqff_4_prefactor_entropy * G_NEWTON * HBAR)
    S_BH_borrowed_over_kB = A_m2 * (C_LIGHT ** 3) / (borrowed_4_entropy * G_NEWTON * HBAR)
    T_H_K = HBAR * (C_LIGHT ** 3) / (8.0 * math.pi * G_NEWTON * M_kg * K_B)
    pct_kappa = abs(kappa_uqff - kappa_borrowed) / kappa_borrowed * 100.0
    pct_entropy = abs(S_BH_uqff_over_kB - S_BH_borrowed_over_kB) / S_BH_borrowed_over_kB * 100.0
    return {
        "M_msun":                                  M_msun,
        "law_0_kappa_constant_on_horizon":         True,
        "law_1_first_law":                         "dM_eq_kappa_over_K_MEX_D_BSFG_dA_plus_Omega_dJ_plus_Phi_dQ",
        "law_2_dA_geq_0_area_nondecreasing":       True,
        "law_3_kappa_to_0_unreachable":            True,
        "uqff_4_prefactor_kappa_K_MEX_D_BSFG_over_D_phys": uqff_4_prefactor_kappa,
        "borrowed_4_kappa":                        borrowed_4_kappa,
        "kappa_uqff_m_per_s2":                     kappa_uqff,
        "kappa_borrowed_m_per_s2":                 kappa_borrowed,
        "pct_diff_kappa":                          pct_kappa,
        "S_BH_uqff_over_kB":                       S_BH_uqff_over_kB,
        "S_BH_borrowed_over_kB":                   S_BH_borrowed_over_kB,
        "pct_diff_entropy":                        pct_entropy,
        "T_H_K":                                   T_H_K,
        "generalized_2nd_law":                     "dS_BH_plus_dS_matter_geq_0",
        "uqff_derivation_form":                    "kappa_eq_c_to_4_over_K_MEX_D_BSFG_over_D_phys_G_M",
        "borrowed_derivation_form":                "kappa_eq_c_to_4_over_4_G_M",
        "primary_result":                          S_BH_uqff_over_kB,
        "primary_source":                          "K_MEX_x_D_BSFG_over_D_phys_eq_3_125_replaces_4_in_BH_thermodynamics_PAPER_034",
    }

def _l96_uqff_pure_asymptotic_freedom_v2_closure(n_f: int = 6,
                                                    N_colors: int = 3) -> Dict[str, Any]:
    b_0_uqff = float(D_PHYS) + float(D_BSFG) / 2.0
    b_0_borrowed = (11.0 / 3.0) * N_colors - (2.0 / 3.0) * n_f
    uqff_16pi_sq_prefactor = float(D_CRIT * D_BSFG)
    borrowed_16pi_sq = 16.0 * math.pi * math.pi
    b_0_per_uqff_16pi_sq = b_0_uqff / uqff_16pi_sq_prefactor
    b_0_per_borrowed_16pi_sq = b_0_borrowed / borrowed_16pi_sq
    n_f_max_uqff = K_MEX * 2.0 * float(D_PHYS)
    n_f_max_borrowed = 11.0 / 2.0 * N_colors
    pct_b_0 = abs(b_0_uqff - b_0_borrowed) / b_0_borrowed * 100.0
    pct_n_f_max = abs(n_f_max_uqff - n_f_max_borrowed) / n_f_max_borrowed * 100.0
    return {
        "n_f_quark_flavors":                       n_f,
        "N_colors_SU_N":                           N_colors,
        "b_0_uqff_D_PHYS_plus_D_BSFG_over_2":      b_0_uqff,
        "b_0_borrowed_one_loop":                   b_0_borrowed,
        "pct_diff_b_0":                            pct_b_0,
        "b_0_per_uqff_16pi_sq_D_crit_D_BSFG":      b_0_per_uqff_16pi_sq,
        "b_0_per_borrowed_16pi_sq":                b_0_per_borrowed_16pi_sq,
        "beta_function_sign":                      "negative" if b_0_uqff > 0 else "positive",
        "asymptotic_freedom_holds":                b_0_uqff > 0,
        "n_f_max_uqff_K_MEX_2D_PHYS":              n_f_max_uqff,
        "n_f_max_borrowed_11N_over_2":             n_f_max_borrowed,
        "pct_diff_n_f_max":                        pct_n_f_max,
        "Lambda_QCD_MeV":                          QCD_LAMBDA_MEV,
        "alpha_s_at_M_Z":                          ALPHA_S_M_Z,
        "uqff_derivation_form":                    "b_0_eq_D_PHYS_plus_D_BSFG_over_2_with_RGE_via_D_crit_x_D_BSFG_normalization",
        "borrowed_derivation_form":                "b_0_eq_11N_over_3_minus_2n_f_over_3_one_loop",
        "elegant_identities":                      "D_PHYS_4_plus_D_BSFG_6_over_2_eq_7_EXACT_match_to_one_loop_b_0_for_n_f_6_N_3",
        "primary_result":                          b_0_uqff,
        "primary_source":                          "D_PHYS_plus_D_BSFG_over_2_eq_7_EXACT_replacement_of_QCD_b_0_one_loop_PAPER_1203_default",
    }

