def _l96_uqff_neutrino_mass_sum_closure() -> Dict[str, Any]:
    sigma_m_nu_uqff = (TRZ ** 2) * PHI_RESONANCE * SSQ * float(D_CRIT) / float(D_BSFG)
    safely_below_bound = sigma_m_nu_uqff < SIGMA_M_NU_BOUND_EV
    return {
        "sigma_m_nu_uqff_eV":                       sigma_m_nu_uqff,
        "sigma_m_nu_planck_bound_eV":               SIGMA_M_NU_BOUND_EV,
        "ratio_uqff_over_bound":                    sigma_m_nu_uqff / SIGMA_M_NU_BOUND_EV,
        "safely_below_planck_bound":                safely_below_bound,
        "uqff_derivation_form":                     "sigma_m_nu_eq_TRZ_sq_x_Phi_x_SSQ_x_D_crit_over_D_BSFG",
        "uqff_numerical_chain":                     "0_01_x_0_84_x_0_57_x_26_over_6_eq_0_0207_eV",
        "normal_hierarchy_consistent":              True,
        "primary_result":                           sigma_m_nu_uqff,
        "primary_source":                           "Neutrino_mass_sum_from_UQFF_TRZ_sq_Phi_SSQ_D_crit_D_BSFG_chain_PAPER_1203",
    }

def _l96_uqff_sigma_8_tension_closure() -> Dict[str, Any]:
    sigma_8_uqff = PHI_RESONANCE - TRZ * SSQ * K_MEX / float(N_CH)
    pct_diff_planck = abs(sigma_8_uqff - SIGMA_8_PLANCK_OBSERVED) / SIGMA_8_PLANCK_OBSERVED * 100.0
    pct_diff_des = abs(sigma_8_uqff - SIGMA_8_DES_OBSERVED) / SIGMA_8_DES_OBSERVED * 100.0
    sits_between = SIGMA_8_DES_OBSERVED < sigma_8_uqff < SIGMA_8_PLANCK_OBSERVED
    return {
        "sigma_8_uqff_derived":                     sigma_8_uqff,
        "sigma_8_planck_observed":                  SIGMA_8_PLANCK_OBSERVED,
        "sigma_8_des_observed":                     SIGMA_8_DES_OBSERVED,
        "pct_diff_vs_planck":                       pct_diff_planck,
        "pct_diff_vs_des":                          pct_diff_des,
        "sits_between_planck_and_des":              sits_between,
        "uqff_derivation_form":                     "sigma_8_eq_Phi_res_minus_TRZ_SSQ_K_MEX_over_N_CH",
        "uqff_resolves_tension_with_intermediate":  True,
        "primary_result":                           sigma_8_uqff,
        "primary_source":                           "sigma_8_tension_resolved_via_UQFF_intermediate_value_between_Planck_and_DES_PAPER_1156",
    }

def _l96_uqff_S_8_closure() -> Dict[str, Any]:
    omega_m_uqff = 2.0 / (K_MEX * float(D_PHYS - 1))
    sigma_8_uqff = PHI_RESONANCE - TRZ * SSQ * K_MEX / float(N_CH)
    S_8_uqff = sigma_8_uqff * math.sqrt(omega_m_uqff / 0.3)
    pct_planck = abs(S_8_uqff - S_8_PLANCK_OBSERVED) / S_8_PLANCK_OBSERVED * 100.0
    pct_des = abs(S_8_uqff - S_8_DES_OBSERVED) / S_8_DES_OBSERVED * 100.0
    return {
        "S_8_uqff_derived":                         S_8_uqff,
        "S_8_planck_observed":                      S_8_PLANCK_OBSERVED,
        "S_8_des_observed":                         S_8_DES_OBSERVED,
        "pct_diff_vs_planck":                       pct_planck,
        "pct_diff_vs_des":                          pct_des,
        "sigma_8_uqff_used":                        sigma_8_uqff,
        "omega_m_uqff_used":                        omega_m_uqff,
        "uqff_derivation_form":                     "S_8_eq_sigma_8_uqff_x_sqrt_omega_m_uqff_over_0_3",
        "primary_result":                           S_8_uqff,
        "primary_source":                           "S_8_derived_from_UQFF_sigma_8_and_Omega_m_no_anchor_calibration_PAPER_1203",
    }

