_OMEGA_M = 0.3
_OMEGA_L = 0.7

def _hubble_unified(t: float = 0.0, z: float = 0.0, H_0: float = 67.4) -> float:
    return H_0 * math.sqrt(_OMEGA_M * (1.0 + z) ** 3 + _OMEGA_L)

def _f_env(name: str, **kwargs) -> float:
    n = name.lower().strip()
    if n == "magnetar":
        return kwargs.get("M_mag", 0.0) + math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_decay", 1.0))
    if n in ("stellar_wind", "wind"):
        return kwargs.get("rho", 0.0) * kwargs.get("v_wind", 0.0) ** 2
    if n == "erosion":
        return 1.0 - math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_erode", 1.0))
    if n in ("lensing", "lens"):
        return kwargs.get("L_amp", 1.0) * (1.0 + 0.1 * kwargs.get("t", 0.0))
    if n in ("merger", "collision"):
        return kwargs.get("M_coll", 0.0) * math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_merge", 1.0))
    if n in ("starburst", "sf"):
        return kwargs.get("M_sf", 0.0) * (1.0 - math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_sf", 1.0)))
    if n in ("supernova", "sn"):
        return kwargs.get("F_sn", 0.0)
    if n in ("bh_feedback", "agn"):
        return kwargs.get("F_BH", 0.0)
    if n in ("rad_pressure", "radiation"):
        return kwargs.get("P_rad", 0.0)
    if n in ("cavity", "pressure"):
        return kwargs.get("P_0", 0.0) * math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_P", 1.0))
    if n in ("evolution", "evo"):
        return kwargs.get("M_evo", 0.0) * (1.0 - math.exp(-kwargs.get("t", 0.0) / kwargs.get("tau_evo", 1.0)))
    if n in ("filament", "fil"):
        return kwargs.get("M_fil", 0.0)
    if n in ("dust", "dust_drag"):
        return kwargs.get("D_dust", 0.0)
    if n in ("ring", "ring_tidal"):
        return kwargs.get("T_ring", 0.0)
    if n in ("tech", "tech_field"):
        return kwargs.get("F_tech", 0.0) + kwargs.get("P_term", 0.0)
    if n in ("shell", "shell_support"):
        return 0.1 * (kwargs.get("Z_magic", 0.0) + kwargs.get("N_magic", 0.0))
    if n in ("cosmo", "cosmological"):
        return kwargs.get("k_curv", 0.0) * kwargs.get("r_c", 0.0) ** 2
    if n in ("torque", "spiral_torque"):
        return kwargs.get("T_spiral", 0.0)
    if n in ("shock", "wind_shock"):
        return kwargs.get("W_shock", 0.0)
    if n in ("outflow", "protostellar_outflow"):
        return kwargs.get("P_outflow", 0.0)
    if n in ("qg", "quantum_gravity"):
        return kwargs.get("QG_term", 0.0)
    if n in ("dm", "dark_matter_term"):
        return kwargs.get("DM_term", 0.0)
    if n in ("gw", "gravitational_wave"):
        return kwargs.get("GW_term", 0.0)
    return 0.0

def _g_compressed_cycle2(M: float = DEFAULT_M, r: float = DEFAULT_R,
                         t: float = 0.0, z: float = 0.0,
                         F_env_total: float = 0.0,
                         B_ratio: float = 0.0,
                         t_n: float = 0.0) -> float:
    H_factor   = 1.0 + _hubble_unified(0.0, z) * 1.0e-20 * t
    B_factor   = 1.0 - B_ratio
    env_factor = 1.0 + F_env_total
    g_base     = (G_NEWTON * M / (r * r)) * H_factor * B_factor * env_factor
    g_ug       = _g_compressed(M, r, t_n)
    g_ui       = _u_mi(t=max(t, 1.0), r=r, n=1, t_n=t_n, M=M)
    Lambda_eff = _vacuum_ledger_4term() / (RHO_SCM * G8_26_BARRIER)
    g_lambda   = Lambda_eff * C_LIGHT * C_LIGHT / 3.0
    g_quantum  = PLANCK_H * OMEGA_SCM * PHI_RESONANCE / (r ** 3)
    g_buoy     = _rho_scm_mass_equiv() * (4.0 / 3.0) * math.pi * r ** 3
    return g_base + g_ug + g_ui + g_lambda + g_quantum + g_buoy

def _f_u_bi_i_mode(mode: str, M: float = DEFAULT_M, r: float = DEFAULT_R,
                   t_n: float = 0.0) -> float:
    m = mode.lower().strip()
    if m in ("compressed", "compress", "c"):
        return _g_compressed(M, r, t_n)
    if m in ("resonant", "resonance", "r"):
        return _g_resonance(M, r, t_n)
    if m in ("buoyant", "buoy", "archimedes", "b"):
        V = (4.0 / 3.0) * math.pi * r * r * r
        return RHO_SCM * V * (G_NEWTON * M / (r * r))
    if m in ("superconductive", "sc", "noble_gas", "s"):
        base = _g_compressed(M, r, t_n)
        return base * (1.0 + SSQ) * PHI_RESONANCE * (RHO_UA / RHO_SCM)
    return 0.0

def _f_u_bi_i_all_modes(M: float = DEFAULT_M, r: float = DEFAULT_R,
                        t_n: float = 0.0) -> Dict[str, float]:
    return {
        "compressed":     _f_u_bi_i_mode("compressed",     M, r, t_n),
        "resonant":       _f_u_bi_i_mode("resonant",       M, r, t_n),
        "buoyant":        _f_u_bi_i_mode("buoyant",        M, r, t_n),
        "superconductive": _f_u_bi_i_mode("superconductive", M, r, t_n),
    }

def _muge_dual_validate(M: float = DEFAULT_M, r: float = DEFAULT_R,
                        t_n: float = 0.0) -> Dict[str, float]:
    uqff = _g_compressed(M, r, t_n)
    muge = _g_resonance(M, r, t_n)
    denom = abs(uqff) + abs(muge)
    agreement = (1.0 - abs(uqff - muge) / denom) if denom > 0.0 else 1.0
    if agreement < 0.0: agreement = 0.0
    return {"uqff_compressed": uqff, "muge_resonance": muge,
            "residual": uqff - muge, "agreement_pct": 100.0 * agreement}

M_SUN_KG = M_SUN

def _generate_99system_catalog() -> Dict[str, Dict[str, Any]]:
    cat: Dict[str, Dict[str, Any]] = {}
    for i in range(20):
        cat[f"star_{i+1}"] = {"M": M_SUN_KG * 10 ** ((i - 5) / 5.0),
                              "r": DEFAULT_R * 10 ** (i / 4.0),
                              "type": "stellar"}
    for i in range(20):
        cat[f"galaxy_{i+1}"] = {"M": M_SUN_KG * 10 ** (9 + i / 5.0),
                                "r": DEFAULT_R * 10 ** (11 + i / 10.0),
                                "type": "galaxy"}
    for i in range(15):
        cat[f"nebula_{i+1}"] = {"M": M_SUN_KG * 10 ** (i / 5.0),
                                "r": DEFAULT_R * 10 ** (7 + i / 10.0),
                                "type": "nebula"}
    for i in range(15):
        if i < 8:
            M = M_SUN_KG * (10 ** ((i + 1) / 10.0))
            r_compact = 12.0e3
        else:
            M = M_SUN_KG * 10 ** ((i - 7) / 2.0)
            r_compact = 3.0 * 2.0 * G_NEWTON * M / (C_LIGHT * C_LIGHT)
        cat[f"compact_{i+1}"] = {"M": M, "r": r_compact, "type": "compact"}
    for i in range(15):
        cat[f"cluster_{i+1}"] = {"M": M_SUN_KG * 10 ** (13 + i / 10.0),
                                 "r": DEFAULT_R * 10 ** (13 + i / 15.0),
                                 "type": "cluster"}
    for i in range(14):
        cat[f"cosmo_{i+1}"] = {"M": M_SUN_KG * 10 ** (15 + i / 5.0),
                               "r": DEFAULT_R * 10 ** (14 + i / 10.0),
                               "type": "cosmological"}
    return cat

def _astro_system_99(name: str):
    n = name.lower().strip().replace(" ", "_").replace("-", "_")
    cat = _generate_99system_catalog()
    params = cat.get(n)
    if params is None:
        return None
    val = _f_u_bi_i(params["M"], params["r"], 4, 0.0)
    prov = (f"99system [{n}] type={params['type']} M={params['M']:.3g} kg r={params['r']:.3g} m: "
            f"procedural catalog (Map §3.1 gold standard (residuals reported via _ledger_residual_all)) {PROV_99}")
    return val, prov

_REGIME_MODES = ("compressed", "resonant", "buoyant", "superconductive")
N_REGIME_LEVELS = 26
N_REGIME_PHASES = 10
TOTAL_REGIME_VARIANTS = 1018

def _regime_decompose(index: int):
    if index < 1 or index > TOTAL_REGIME_VARIANTS:
        return None
    i = index - 1
    mode_idx  = i // (N_REGIME_LEVELS * N_REGIME_PHASES)
    rem       = i %  (N_REGIME_LEVELS * N_REGIME_PHASES)
    level_idx = rem // N_REGIME_PHASES
    phase_idx = rem %  N_REGIME_PHASES
    level     = level_idx + 1
    ssq_sign  = +1 if (level % 2 == 1) else -1
    return _REGIME_MODES[mode_idx], level, phase_idx, ssq_sign

def _regime_beta_level(level: int) -> float:
    rem = level % 5
    return BETA_I * (5 - rem) / 5.0 if rem != 0 else BETA_I

def _regime_f_u_bi_i(index: int, M: float = DEFAULT_M,
                     r: float = DEFAULT_R) -> float:
    dec = _regime_decompose(index)
    if dec is None:
        return 0.0
    mode, level, phase_idx, ssq_sign = dec
    t_n_phase = phase_idx / float(N_REGIME_PHASES)
    base      = _f_u_bi_i_mode(mode, M, r, t_n_phase)
    beta_l    = _regime_beta_level(level)
    ssq_term  = 1.0 + ssq_sign * SSQ
    return base * beta_l * math.cos(math.pi * t_n_phase) * ssq_term

def _regime_inventory() -> Dict[str, int]:
    return {
        "total_variants":    TOTAL_REGIME_VARIANTS,
        "modes":             len(_REGIME_MODES),
        "ladder_levels":     N_REGIME_LEVELS,
        "phase_windows":     N_REGIME_PHASES,
        "candidates_full":   len(_REGIME_MODES) * N_REGIME_LEVELS * N_REGIME_PHASES,
        "candidates_capped": TOTAL_REGIME_VARIANTS,
    }

def _regime_sample(indices, M: float = DEFAULT_M,
                   r: float = DEFAULT_R) -> Dict[int, Dict[str, Any]]:
    out: Dict[int, Dict[str, Any]] = {}
    for idx in indices:
        dec = _regime_decompose(idx)
        if dec is None:
            continue
        mode, level, phase_idx, ssq_sign = dec
        out[idx] = {
            "mode":      mode,
            "level":     level,
            "phase_idx": phase_idx,
            "ssq_sign":  ssq_sign,
            "value":     _regime_f_u_bi_i(idx, M, r),
        }
    return out

def _regime_aggregate(M: float = DEFAULT_M, r: float = DEFAULT_R) -> Dict[str, float]:
    vmin = float("inf"); vmax = float("-inf")
    s = 0.0; sa = 0.0; zc = 0
    for idx in range(1, TOTAL_REGIME_VARIANTS + 1):
        v = _regime_f_u_bi_i(idx, M, r)
        if v < vmin: vmin = v
        if v > vmax: vmax = v
        s  += v
        sa += abs(v)
        if v == 0.0: zc += 1
    n = float(TOTAL_REGIME_VARIANTS)
    return {"min": vmin, "max": vmax, "mean": s / n,
            "abs_mean": sa / n, "zero_count": zc,
            "count": TOTAL_REGIME_VARIANTS}

_UA_OVER_SCM  = RHO_UA / RHO_SCM
_SCM_OVER_UA  = RHO_SCM / RHO_UA
_UA_OVER_SUM  = RHO_UA / (RHO_UA + RHO_SCM)
_SCM_OVER_SUM = RHO_SCM / (RHO_UA + RHO_SCM)

_M_PROTON_KG  = 1.67262192369e-27
_M_PROTON_C2  = _M_PROTON_KG * C_LIGHT * C_LIGHT
_HBAR_J_S     = PLANCK_H / (2.0 * math.pi)

def _f_ubii_virx(sigma_X: float = 1.2e6, T_X: float = 7.1e7,
                 M_vir: float = 1.2e15 * M_SUN, r_vir: float = 1.9e22) -> float:
    return (M_vir / r_vir) * (sigma_X * sigma_X / (C_LIGHT * C_LIGHT)) \
           * _UA_OVER_SUM * BETA_I * math.sqrt(T_X / 1.0e7)

def _f_ubii_termv(tau: float = 1.0, L: float = 3.828e26 * 1.0e6,
                  E_LEP: float = 1.0e35, gamma: float = 1.0e-3, t: float = 0.0) -> float:
    return (tau * L) / (C_LIGHT * E_LEP) * math.exp(-gamma * t) * BETA_I

def _f_ubii_upar(U: float = 1.0e-2, L_ion: float = 1.0e49, n_H: float = 1.0e10,
                 r: float = 1.5e16, SCm_factor: float = 1.0) -> float:
    return U * (L_ion / (n_H * r * r)) * SCm_factor * BETA_I

def _f_ubii_coup(E_kin: float = 1.0e44, E_mag: float = 1.0e43,
                 v: float = 5.0e6) -> float:
    return (E_kin / E_mag) * (v * v / (C_LIGHT * C_LIGHT)) * _UA_OVER_SUM * BETA_I

def _f_ubii_orbdec(M1: float = 36.0 * M_SUN, M2: float = 29.0 * M_SUN,
                   a: float = 3.5e5) -> float:
    mu      = (M1 * M2) / (M1 + M2)
    dadt    = (64.0 / 5.0) * (G_NEWTON ** 3) * M1 * M2 * (M1 + M2) \
              / ((C_LIGHT ** 5) * (a ** 3))
    return dadt * mu * (G_NEWTON / (C_LIGHT ** 5)) * _UA_OVER_SCM * BETA_I

def _f_ubii_kn(L_peak: float = 1.5e35, t_peak: float = 1.123e5,
               r: float = 1.234e24) -> float:
    return (L_peak * t_peak) / (4.0 * math.pi * r * r * C_LIGHT) \
           * _SCM_OVER_UA * BETA_I

def _f_ubii_fermi(v_shock: float = 5.0e6, beta_shock: float = 4.0) -> float:
    return beta_shock * (v_shock * v_shock / (C_LIGHT * C_LIGHT)) \
           * _UA_OVER_SCM * BETA_I

def _f_ubii_kne(rho_CR_J_m3: float = 1.602e-13, Z: float = 1.0,
                E_knee_eV: float = 3.0e15) -> float:
    E_knee_J = E_knee_eV * EV_J
    return rho_CR_J_m3 * Z * (E_knee_J / _M_PROTON_C2) \
           * _UA_OVER_SCM * BETA_I

def _f_ubii_whim(T_WHIM: float = 1.0e6, n_e: float = 1.0) -> float:
    return (T_WHIM * n_e * K_B) / _M_PROTON_C2 * _UA_OVER_SUM * BETA_I

def _f_ubii_ps(M_halo: float = 1.0e12 * M_SUN, sigma_8: float = 0.811,
               Omega_m: float = 0.315, Omega_L: float = 0.685) -> float:
    return M_halo * sigma_8 * (Omega_m / Omega_L) * _SCM_OVER_UA * BETA_I

def _f_ubii_sfe(epsilon_SFE: float = 0.01, Sigma_gas: float = 100.0 * M_SUN / (3.086e16 ** 2),
                Sigma_crit: float = 50.0 * M_SUN / (3.086e16 ** 2)) -> float:
    return epsilon_SFE * (Sigma_gas / Sigma_crit) * _SCM_OVER_UA * BETA_I

def _f_ubii_hawk(M_BH: float = 10.0 * M_SUN) -> float:
    T_H = (_HBAR_J_S * C_LIGHT ** 3) / (8.0 * math.pi * G_NEWTON * M_BH * K_B)
    return T_H * _SCM_OVER_UA * BETA_I

def _f_ubii_bd(rho_bounce: float = 0.41 * 5.155e96,
               a_bounce: float = 1.0e-35) -> float:
    return rho_bounce * (a_bounce ** 3) * _UA_OVER_SCM * BETA_I

def _f_ubii_roche(dm_dt: float = 1.0e-9 * M_SUN / 3.156e7,
                  v_esc: float = 6.0e5) -> float:
    return dm_dt * (v_esc * v_esc / (C_LIGHT * C_LIGHT)) * _SCM_OVER_UA * BETA_I

def _f_ubii_ent(S_ent: float = 1.0e77, Area: float = 1.05e16) -> float:
    return (S_ent * Area) / (4.0 * G_NEWTON * _HBAR_J_S) * _UA_OVER_SCM * BETA_I

def _f_ubii_dec(tau_dec: float = 1.0e-13, T: float = 300.0) -> float:
    return (_HBAR_J_S / tau_dec) * T * _UA_OVER_SCM * BETA_I

def _f_ubii_lobe(P_jet: float = 1.0e37, t_lobe: float = 3.156e14,
                 rho_ICM: float = 1.0e-26) -> float:
    return (P_jet * t_lobe) / rho_ICM * _UA_OVER_SUM * BETA_I

