               counts["verdict_counts"]["harmful"],
               counts["verdict_counts"]["silent"],
               uqff["verdict"], uqff["n_helped"], uqff["n_harmed"],
               uqff["post_wmean"], base_wmean, uqff["absorption_pct"],
