def _compose_step4_provenance(
    calc_label: str,
    base_prov: str,
    val: Any = None,
    anchor: Any = None,
    anchor_unit: str = "",
    anchor_kind: str = "",
    anchor_source: str = "",
) -> str:
    head = f"{calc_label} via {base_prov}"
    suffix = ""
    if anchor is not None:
        try:
            v_num = float(val) if val is not None else None
            a_num = float(anchor)
            if v_num is not None:
                _, diff_str = _compute_diff_pct(v_num, a_num)
                anchor_block = (
                    f" | REF={anchor} ({anchor_unit}, kind={anchor_kind}, "
                    f"source: {anchor_source}) | UQFF={v_num:.6g} "
                    f"| {diff_str}"
                )
            else:
                anchor_block = (
                    f" | REF={anchor} ({anchor_unit}, kind={anchor_kind}, "
                    f"source: {anchor_source}) | UQFF={val}"
                )
        except (TypeError, ValueError):
            anchor_block = (
                f" | REF={anchor} ({anchor_unit}, kind={anchor_kind}, "
                f"source: {anchor_source}) | UQFF={val}"
            )
        return head + anchor_block
    if "" in base_prov:
        return head
    return head + suffix


def _universal_inertial_operator(omega_s=OMEGA_S_SUN, t_n=0.0, lambda_i=LAMBDA_I):
    return lambda_i * (RHO_SCM / RHO_UA) * omega_s * _cos_pi_tn(t_n) * (1.0 + TRZ)

def _universal_inertial_operator_product(omega_s=OMEGA_S_SUN, t_n=0.0, lambda_i=LAMBDA_I):
    return lambda_i * RHO_SCM * RHO_UA * omega_s * _cos_pi_tn(t_n) * (1.0 + TRZ)

def _beta_dynamic(E=1.0, Z=1, t=0.0):
    return BETA_I * abs(E) * float(Z) * _cos_pi_tn(t)

def _k_spring():
    return DPM_DENSITY_RATIO * OMEGA_SCM * PHI_RESONANCE

def _f_u_bi_canonical(M, r, t_n=0.0, beta_eff=None):
    if beta_eff is None:
        beta_eff = BETA_I
    if r <= 0.0:
        return 0.0
    return (-beta_eff * G_NEWTON * M * RHO_SCM / (r * r)
            * (1.0 + TRZ) * abs(_cos_pi_tn(t_n)))

def _f_u_bii_canonical(M, r, t_n=0.0, beta_eff=None, E_n=0.0, r0=DEFAULT_R):
    if beta_eff is None:
        beta_eff = BETA_I
    if r0 == 0.0:
        return 0.0
    return (beta_eff * (r / r0) * _k_spring() * (1.0 + E_n)
            * abs(_cos_pi_tn(t_n)))

def _f_u_total(M, r, t_n=0.0, Um=0.0, dissipation=0.0, Ug_sum=None, beta_eff=None):
    if Ug_sum is None:
        Ug_sum = G_NEWTON * M / (r * r) if r > 0 else 0.0
    fubi = _f_u_bi_canonical(M, r, t_n, beta_eff)
    fubii = _f_u_bii_canonical(M, r, t_n, beta_eff)
    return Ug_sum - fubi + fubii + Um + dissipation

def _solve_habitable_zone(M, t_n=0.0, r_lo=1.0e6, r_hi=1.0e22, max_iter=200, tol=1.0e-8):
    def total(r):
        return _f_u_bi_canonical(M, r, t_n) + _f_u_bii_canonical(M, r, t_n)
    f_lo = total(r_lo)
    f_hi = total(r_hi)
    if f_lo == 0.0:
        return r_lo
    if f_hi == 0.0:
        return r_hi
    if f_lo * f_hi > 0.0:
        return float('nan')
    for _ in range(max_iter):
        r_mid = math.sqrt(r_lo * r_hi)
        f_mid = total(r_mid)
        if abs(f_mid) < tol:
            return r_mid
        if f_lo * f_mid < 0.0:
            r_hi = r_mid; f_hi = f_mid
        else:
            r_lo = r_mid; f_lo = f_mid
    return math.sqrt(r_lo * r_hi)

def _magic_number(shell):
    if shell == 1: return SO_FIVE - 2 * D_PHYS
    if shell == 2: return 2 * D_PHYS
    if shell == 3: return 2 * SO_FIVE
    if shell == 4: return D_CRIT + SO_FIVE - 2 * D_PHYS
    if shell == 5: return A_FIVE - SO_FIVE
    if shell == 6: return A_FIVE + D_CRIT - D_PHYS
    if shell == 7: return D_CRIT + SO_FIVE * SO_FIVE
    raise ValueError(f'shell {shell} out of range 1-7')

def _magic_numbers_all():
    return {
        'shell_1_He':  _magic_number(1),
        'shell_2_O':   _magic_number(2),
        'shell_3_Ca':  _magic_number(3),
        'shell_4_Ni':  _magic_number(4),
        'shell_5_Sn':  _magic_number(5),
        'shell_6_Pb':  _magic_number(6),
        'shell_7_ndrip': _magic_number(7),
    }

def _be_per_a_peak():
    return float(N_CH) - TRZ * K_MEX

def _deuteron_binding():
    f = TRZ
    return (K_MEX + PHI_RESONANCE - SSQ - f
            - (f**2) * K_MEX - (f**2) * PHI_RESONANCE
            + (f**2) + (f**3))

def _alpha_particle_binding():
    f = TRZ
    return (float(D_CRIT) + K_MEX + f + f * PHI_RESONANCE
            + (f**2) * K_MEX + (f**2) * PHI_RESONANCE)

