def _ker_scm():
    return EPSILON_CLUSTER_EV

def _ker_scm_chain():
    e_phon_J = E_PHONON_J
    e_phon_eV = e_phon_J / EV_J
    chain_eV = e_phon_eV * S26_3 * PHI_RESONANCE
    return {
        'E_phonon_J':         e_phon_J,
        'E_phonon_eV':        e_phon_eV,
        'S26_amplification':  S26_DPM,
        'phi_resonance':      PHI_RESONANCE,
        'KER_chain_eV':       chain_eV,
        'KER_canonical_eV':   EPSILON_CLUSTER_EV,
        'residual_pct':       (chain_eV - EPSILON_CLUSTER_EV) / EPSILON_CLUSTER_EV * 100.0,
    }

def _parkhomov_excess_heat(N_clusters=2.0e18, t_hours=1.0, kappa=KAPPA_LENR):
    return N_clusters * EPSILON_CLUSTER_J * math.exp(-kappa * t_hours * 24.0)

def _pons_fleischmann_excess_heat(PdD_loading=0.85, volume_m3=1.0e-6, f_buoyancy=1.0e-3):
    N_active = PdD_loading * f_buoyancy * 6.022e28 * volume_m3
    return N_active * EPSILON_CLUSTER_J

def _mizuno_lenr(N_clusters=5.0e17, transmutation_efficiency=0.1):
    return {
        'excess_heat_W':    N_clusters * EPSILON_CLUSTER_J,
        'transmuted_count': N_clusters * transmutation_efficiency,
    }

