def _m_W_uqff_derive():
    f2 = TRZ * TRZ
    return (float(A_FIVE) + 2.0 * float(SO_FIVE)
            + TRZ * float(D_PHYS)
            - f2 * float(D_BSFG)
            + f2 * float(D_PHYS)
            - f2 * (SSQ ** 2))

def _m_Z_uqff_derive():
    f2 = TRZ * TRZ
    return (float(N_CH) * float(SO_FIVE)
            + TRZ * float(SO_FIVE)
            + f2 * float(SO_FIVE)
            + f2 * float(D_BSFG)
            + f2 * float(D_PHYS)
            + f2 * SSQ
            - f2 * (SSQ ** 3))

def _m_top_uqff_derive():
    f2 = TRZ * TRZ
    return (float(D_CRIT) * float(SO_FIVE)
            - float(A_FIVE)
            - float(D_PHYS) * float(N_CH)
            + float(SO_FIVE)
            - TRZ * float(D_PHYS)
            - TRZ * float(SO_FIVE)
            + f2 * float(D_BSFG)
            + 2.0 * f2 * float(D_PHYS)
            + f2 * SSQ
            + f2 * (SSQ ** 2)
            + f2 * (SSQ ** 3))

def _m_higgs_uqff_derive():
    f2 = TRZ * TRZ
    return (2.0 * float(A_FIVE)
            + float(N_CH)
            - float(D_PHYS)
            + TRZ * SSQ
            + f2 * float(D_BSFG)
            + f2 * (SSQ ** 2))

def _m_bottom_uqff_derive():
    f2 = TRZ * TRZ
    return (float(D_PHYS)
            + TRZ * float(D_PHYS)
            - TRZ * SSQ
            - f2 * float(D_CRIT)
            + f2 * float(D_BSFG)
            + f2 * float(D_PHYS)
            - f2 * (SSQ ** 2)
            - f2 * (SSQ ** 3))

def _m_charm_uqff_derive():
    f2 = TRZ * TRZ
    return (TRZ * float(D_CRIT)
            - TRZ * float(D_PHYS)
            - TRZ * float(SO_FIVE)
            + f2 * float(SO_FIVE)
            - f2 * float(D_PHYS)
            + f2 * SSQ
            + f2 * (SSQ ** 2)
            + f2 * (SSQ ** 3))

def _m_tau_uqff_derive():
    f2 = TRZ * TRZ
    return (SSQ
            + TRZ * float(D_PHYS)
            + TRZ * float(SO_FIVE)
            - f2 * float(D_CRIT)
            + f2 * float(D_BSFG)
            + f2 * SSQ
            + f2 * (SSQ ** 2)
            - f2 * (SSQ ** 3))

def _m_muon_uqff_derive():
    f2 = TRZ * TRZ
    return (f2 * float(SO_FIVE)
            + f2 * (SSQ ** 2)
            + f2 * (SSQ ** 3)
            + f2 * (SSQ ** 5))

def _m_strange_uqff_derive():
    f2 = TRZ * TRZ
    return (f2 * float(SO_FIVE)
            - f2 * (SSQ ** 2)
            - f2 * (SSQ ** 3))

def _m_electron_uqff_derive():
    f3 = TRZ * TRZ * TRZ
    return f3 * (SSQ ** 2) + f3 * (SSQ ** 3)

def _higgs_vev_uqff_derive():
    return 2.0 * (float(A_FIVE) + 2.0 * float(SO_FIVE) + float(D_BSFG) + float(D_PHYS) + 1.0/3.0)

def _sin2_theta_w_uqff_derive():
    mW = _m_W_uqff_derive()
    mZ = _m_Z_uqff_derive()
    return 1.0 - (mW * mW) / (mZ * mZ)

def _alpha_s_mz_uqff_derive():
    return SSQ / float(D_PHYS) - (5.0 / 6.0) * TRZ * TRZ

def _lambda_qcd_uqff_derive():
    return 2.0 * SSQ * TRZ - SSQ * TRZ * (1.0 + TRZ)

def _v_ckm_us_uqff_derive():
    return SSQ * (TRZ ** 0.5)

def _v_ckm_ub_uqff_derive():
    return TRZ * SSQ * TRZ * 0.7

def _v_ckm_ud_uqff_derive():
    vus = _v_ckm_us_uqff_derive()
    vub = _v_ckm_ub_uqff_derive()
    s = 1.0 - vus * vus - vub * vub
    return s ** 0.5 if s > 0.0 else 0.0

def _dm2_21_uqff_derive():
    return DM2_21_EV2

def _dm2_31_uqff_derive():
    return DM2_31_EV2

def _a_electron_uqff_derive():
    a = _alpha_uqff_derive() if '_alpha_uqff_derive' in globals() else 1.0 / (PHI_RESONANCE * float(D_CRIT) * 2.0 * math.pi)
    return a / (2.0 * math.pi)

def _a_muon_uqff_derive():
    a = _alpha_uqff_derive() if '_alpha_uqff_derive' in globals() else 1.0 / (PHI_RESONANCE * float(D_CRIT) * 2.0 * math.pi)
    return a * (1.0 + TRZ * G4_BSFG_COEF) / (2.0 * math.pi)

def _m_proton_uqff_derive_mev():
    return 1000.0 * (float(D_PHYS) + TRZ * float(D_BSFG) + TRZ * SSQ
                      - TRZ * TRZ * float(D_CRIT) + TRZ * TRZ * SSQ) * (0.938272 / 4.236)

R_K_LHCB_OBS = 0.85
R_D_BAR_BELLE_OBS = 1.4
BR_KOTO_OBS = 3.0e-11
BR_FCNC_BSMUMU_LHCB_OBS = 1.06e-6
R_P_PRAD_OBS_FM = 0.831
R_P_MUONIC_FM_BASELINE = 0.8409

def _r_k_lepton_uni_uqff():
    return 1.0 - LAMBDA_LEDGER_UQFF * float(A_FIVE) / 3.0

def _r_d_lepton_uni_uqff():
    return 1.0 + LAMBDA_LEDGER_UQFF * float(A_FIVE)

def _br_koto_uqff():
    return (LAMBDA_LEDGER_UQFF ** 6) * float(A_FIVE) * PHI_RESONANCE / BETA_I * K_MEX * (1.0 + TRZ)

def _t_violation_meson_uqff():
    return TRZ * BETA_I

def _fcnc_b_to_s_mumu_uqff():
    return (LAMBDA_LEDGER_UQFF ** 3) * float(A_FIVE) / float(D_CRIT) * (1.0 + BETA_I / 3.0)

def _proton_charge_radius_prad_uqff_fm():
    return R_P_MUONIC_FM_BASELINE * (1.0 + LAMBDA_LEDGER_UQFF * BETA_I * PHI_RESONANCE * 2.0)

