def _l_edd_classical_erg_s(M_msun):
    return 1.26e38 * M_msun

def _m_jet_modulation(gamma_thz=AGN_3C273_GAMMA_PEAK_THZ, a_jet=AGN_3C273_A_JET, gamma_crit_thz=AGN_3C273_GAMMA_CRIT_THZ):
    return 1.0 + a_jet * (2.718281828459045 ** (-gamma_thz / gamma_crit_thz))

def _agn_eddington_uqff_correction():
    return 1.0 + BETA_I * S_26 * PHI_RESONANCE * TRZ

def _eddington_luminosity_uqff_erg_s(M_msun, gamma_thz=AGN_3C273_GAMMA_PEAK_THZ, include_jet=False):
    L_edd_classical = _l_edd_classical_erg_s(M_msun)
    correction = 1.0 + BETA_I * S_26 * PHI_RESONANCE * TRZ
    if include_jet:
        correction = correction * _m_jet_modulation(gamma_thz)
    return L_edd_classical * correction

def _eddington_3c273_uqff_observed_match_erg_s():
    return _eddington_luminosity_uqff_erg_s(M_3C273_MSUN, AGN_3C273_GAMMA_PEAK_THZ, include_jet=True)

def _msigma_phonon_index_uqff():
    delta = BETA_I * S_26 * TRZ * K_MEX
    return M_SIGMA_INDEX_PDG + delta

def _msigma_correction_factor_uqff(sigma_kms=200.0):
    sigma_ratio = sigma_kms / 200.0
    delta = BETA_I * S_26 * TRZ * K_MEX
    return sigma_ratio ** delta

def _blandford_znajek_phonon_factor(B_over_Bcrit=0.6):
    return 1.0 + BETA_I * PHI_RESONANCE * (B_over_Bcrit ** 2)

def _blandford_znajek_uqff_enhancement(B_over_Bcrit=0.6):
    return BETA_I * PHI_RESONANCE * (B_over_Bcrit ** 2)

def _perseus_ixpe_polarization_uqff():
    return (float(D_BSFG) - float(D_PHYS)) * (TRZ ** 2) * K_MEX

def _perseus_q_phonon_over_lcool_uqff():
    return BETA_I * S_26 * PHI_RESONANCE * TRZ * K_MEX

def _cooling_flow_suppression_uqff(gamma_thz=AGN_3C273_GAMMA_PEAK_THZ):
    Q_ratio = _perseus_q_phonon_over_lcool_uqff() * _m_jet_modulation(gamma_thz)
    return min(Q_ratio, 1.0)

def _cool_core_buoyancy_suppression_uqff():
    return 1.0 - _perseus_q_phonon_over_lcool_uqff()

T_COAL_OBS_PTA_YR = 1.0e8
L_MAGNETAR_GIANT_FLARE_OBS_ERG_S = 1.0e47

def _final_parsec_t_coal_uqff_yr():
    return 1.0e10 / (float(D_CRIT) * K_MEX * PHI_RESONANCE * (1.0 + BETA_I * PHI_RESONANCE))

def _magnetar_giant_flare_structural_uqff():
    return RHO_SCM * (C_LIGHT ** 2) * float(A_FIVE) * (float(D_CRIT) ** 2)

