RINGS_R_EINSTEIN_M = 3.086e20
RINGS_Z_LENS = 0.5
RINGS_D_LS_OVER_D_S = 0.67

def _crab_pulses_per_60s_window():
    return CRAB_SPIN_HZ * CRAB_TIMING_WINDOW_S

def _crab_dpm_lock_ratio():
    return CRAB_F_OSC_HZ * 1.0e-12

def _crab_angular_frequency_rad_s():
    return 2.0 * 3.141592653589793 * CRAB_F_OSC_HZ

def _psr_j0030_kozima_cross_section_m2(rho_interior=PSR_J0030_RHO_INTERIOR, sigma_0=1.0e-4, rho_0=1.0e-22):
    return sigma_0 * (rho_interior / rho_0)

def _psr_j0030_surface_gravity_m_s2():
    return G_NEWTON * PSR_J0030_M_KG / (PSR_J0030_R_M ** 2)

def _eta_carinae_g_base_m_s2():
    M_total_kg = (ETA_CARINAE_M1_MSUN + ETA_CARINAE_M2_MSUN) * M_SUN
    r_peri_m = ETA_CARINAE_R_PERI_AU * AU_M
    return G_NEWTON * M_total_kg / (r_peri_m ** 2)

def _eta_carinae_pcr_factor():
    return 1.0 + BETA_I * PHI_RESONANCE * (TRZ ** 2) * K_MEX

def _eta_carinae_g_eff_uqff_m_s2():
    return _eta_carinae_g_base_m_s2() * _eta_carinae_pcr_factor()

def _westerlund2_mass_growth_function_kg(t_yr=0.0):
    tau_s = WESTERLUND2_AGE_MYR * 1.0e6 * 3.1557e7
    t_s = t_yr * 3.1557e7
    return WESTERLUND2_M0_MSUN * M_SUN * (1.0 + WESTERLUND2_MF_GROWTH * (2.718281828459045 ** (-t_s / tau_s)))

def _westerlund2_peak_mass_msun():
    return WESTERLUND2_M0_MSUN * (1.0 + WESTERLUND2_MF_GROWTH)

def _orion_g_uqff_m_s2(t_yr=ORION_T_AGE_YR):
    g_base = G_NEWTON * ORION_M_TOTAL_KG / (ORION_R_M ** 2)
    return g_base * (1.0 + BETA_I * PHI_RESONANCE * (TRZ ** 2) * K_MEX)

def _rings_of_relativity_lensing_L():
    L = (G_NEWTON * RINGS_M_LENS_KG) / ((C_LIGHT ** 2) * RINGS_R_EINSTEIN_M) * RINGS_D_LS_OVER_D_S
    return L

def _rings_of_relativity_amplification_uqff():
    return 1.0 + _rings_of_relativity_lensing_L()

def _lagoon_nebula_sfr_amplifier_uqff(t_yr=50000.0):
    delta_M = TRZ * K_MEX * (t_yr / 100000.0)
    return delta_M

def _ngc3603_tau_sf_uqff_myr():
    return NGC3603_TAU_SF_MYR * (1.0 + (float(D_BSFG) - float(D_PHYS)) * (TRZ ** 2))

FABER_JACKSON_EXPONENT_OBS = 4.0
