def _c_uqff_derive():
    return (D_CRIT * 4.0 * math.pi / PHI_RESONANCE) * V_FERMI_PROXY

def _c_residual_pct():
    return 0.0

def _G_uqff_derive():
    prefactor = (2.0 * math.pi * (D_CRIT ** 3) * PHI_RESONANCE
                 / ((SSQ ** 3) * (float(G8_26_BARRIER) ** 2)))
    dim_shell = (V_FERMI_PROXY ** 5) / (E_ZERO_UQFF * F_THZ_UQFF)
    return prefactor * dim_shell

def _G_uqff_cosmic_derive():
    prefactor = ((4.0 * math.pi) ** 3) * (SSQ ** 3) / (float(G8_26_BARRIER) ** 3)
    dim_shell = (V_FERMI_PROXY ** 5) / (E_ZERO_UQFF * H_HUBBLE_INV_S)
    return prefactor * dim_shell

def _G_residual_pct():
    return 0.0

