def _lagrangian_sector_residual(dataset: Dict[str, Any]) -> Dict[str, Any]:
    d = dataset or {}
    key = d.get("lagrangian_sector")
    if not isinstance(key, str) or key not in _LAGRANGIAN_SECTOR_REGISTRY:
        return {"paper": key, "sector": {}, "residual": None,
                "diff_str": "diff=undefined% (unknown sector)"}
    entry = _LAGRANGIAN_SECTOR_REGISTRY[key]
    lt = d.get("lagrangian_terms") or {}
    phi_index = d.get("phi_index", entry.get("phi_index", "phi"))
    residual = _stationarity_residual(lt, phi_index)
    _, diff_str = _compute_diff_pct(residual, 0.0)
    return {"paper": key, "sector": entry, "residual": residual,
            "diff_str": diff_str}

def _ug1(r: float, layer_i: int = 1,
         dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    M = float(d.get("M", d.get("m", DEFAULT_M)))
    return G_NEWTON * M / (r * r)

def _ug2(r: float, layer_i: int = 1,
         dataset: Optional[Dict[str, Any]] = None) -> float:
    return _ug1(r, layer_i, dataset) * SSQ

def _ug3(r: float, t: float = 0.0, layer_i: int = 1,
         dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    t_n = float(d.get("t_n", t))
    return _ug1(r, layer_i, dataset) * BETA_I * _cos_pi_tn(t_n)

def _ug4(r: float, layer_i: int = 1,
         dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    M = float(d.get("M", d.get("m", DEFAULT_M)))
    return RHO_SCM * M / r

def _u_i(r: float, layer_i: int = 1,
         dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    M = float(d.get("M", d.get("m", DEFAULT_M)))
    n = int(d.get("n", layer_i))
    return RHO_SCM * M / (r * r) * n

def _u_m(t: float, r: float = DEFAULT_R, n: int = 1,
        dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    M = float(d.get("M", d.get("m", DEFAULT_M)))
    gamma = float(d.get("gamma", GAMMA))
    t_n = float(d.get("t_n", 0.0))
    return _u_mi(t=t, r=r, n=n, gamma=gamma, t_n=t_n, M=M)

def _u_b(r: float, dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    M = float(d.get("M", d.get("m", DEFAULT_M)))
    t_n = float(d.get("t_n", 0.0))
    return (RHO_SCM * M / r) * (1.0 + K_Ub * _cos_pi_tn(t_n))

def _f_env_layer27(r: float, dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    return RHO_SCM * (4.0 / 3.0) * math.pi * r * r * r

def _h_res(n: int = 1, dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    nn = max(1, min(int(n), int(D_CRIT)))
    return (1.0 / (nn * nn)) * PLANCK_H * OMEGA_SCM

def _a_res(dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    return (RHO_UA / RHO_SCM) * PHI_RESONANCE

def _f_res(n: int = 1, dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    return float(n) * OMEGA_SCM / (2.0 * math.pi)

def _u_dp(dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    return BETA_I * RHO_SCM

def _k_nuc(dataset: Optional[Dict[str, Any]] = None) -> float:
    _ = dataset
    return RHO_SCM * A_26

def _s_shell(r: float, dataset: Optional[Dict[str, Any]] = None) -> float:
    d = dataset or {}
    R_b = float(d.get("R_b", DEFAULT_R))
    return 1.0 if r >= R_b else 0.0

def _h_res_composite(t: float = 0.0, r: float = DEFAULT_R, n: int = 1,
                     SC_m: float = 1.0,
                     dataset: Optional[Dict[str, Any]] = None) -> float:
    A_res = _a_res(dataset)
    f_res = _f_res(n, dataset)
    U_dp  = _u_dp(dataset)
    k_nuc = _k_nuc(dataset)
    S_sh  = _s_shell(r, dataset)
    return A_res * math.sin(2.0 * math.pi * f_res * t) + U_dp * SC_m * k_nuc + S_sh

LENR_WEAK_Q_J = 0.78e6 * EV_J

def _lenr_weak_Q() -> float:
    return LENR_WEAK_Q_J

def _delta_n_monopole(n: int = 1) -> float:
    return 2.0 * math.pi * float(n) / float(D_BSFG)

def _b_pseudo_monopole(q_m: float = 1.0, r: float = DEFAULT_R) -> float:
    mu_0 = _vacuum_permeability_canonical_sat()
    return (mu_0 / (4.0 * math.pi)) * q_m / max(r * r, 1e-300)

def _phi_twist_caduceus(t: float = 0.0, beta: float = 1.0,
                        omega: float = None) -> float:
    w = OMEGA_SCM if omega is None else omega
    return beta * math.sin(w * t)

def _psi_quantum_radial(r: float = DEFAULT_R, t: float = 0.0,
                        k: float = None, omega: float = None,
                        alpha: float = 1.0, r_0: float = 0.0,
                        A: float = 1.0) -> float:
    kk = (2.0 * math.pi / max(r, 1e-300)) if k is None else k
    ww = OMEGA_SCM if omega is None else omega
    return A * math.sin(kk * r - ww * t) / max(r, 1e-300) * math.exp(-alpha * abs(r - r_0))

def _psi_rotating(r: float = DEFAULT_R, theta: float = 0.0, t: float = 0.0,
                  sigma: float = None, m: int = 1, omega: float = None,
                  A: float = 1.0) -> float:
    s = (r / 2.0) if sigma is None else sigma
    w = OMEGA_SCM if omega is None else omega
    return A * math.exp(-r * r / (2.0 * s * s)) * math.cos(m * theta - w * t)

def _e_boson_harmonic(m: float = None, omega: float = None,
                      x: float = 0.0, n: int = 0) -> float:
    mm = RHO_SCM / (C_LIGHT * C_LIGHT) if m is None else m
    ww = OMEGA_SCM if omega is None else omega
    H_BAR = PLANCK_H / (2.0 * math.pi)
    return 0.5 * mm * ww * ww * x * x + H_BAR * ww * (n + 0.5)

def _spacetime_phase(t: float = 0.0, E_g: float = 0.0, G_i: float = 0.0,
                     C_j: float = 0.0, m_0: float = 0.0) -> float:
    H_BAR = PLANCK_H / (2.0 * math.pi)
    return (E_g + G_i + C_j + m_0) * t / H_BAR

def _p_de_inertia(eta_inertia: float = 0.1, V: float = 1.0,
                  omega_vac: float = None) -> float:
    w = OMEGA_SCM if omega_vac is None else omega_vac
    return eta_inertia * RHO_SCM * V * w

def _p_ac_emp(E_EMP: float = 1.0, V: float = 1.0,
              omega_EMP: float = None) -> float:
    eps_0 = _vacuum_permittivity_canonical_sat()
    w = OMEGA_SCM if omega_EMP is None else omega_EMP
    return 0.5 * eps_0 * E_EMP * E_EMP * V * w

def _jeans_mass(T: float = 100.0, mu: float = 1.3, rho: float = 1.0e-20) -> float:
    M_H = 1.6735e-27
    inner = (5.0 * K_B * T) / (G_NEWTON * mu * M_H)
    return inner ** 1.5 * math.sqrt(3.0 / (4.0 * math.pi * rho))

def _f_phi_ladder(n: int = 1, f_0: float = None) -> float:
    f0 = 281.5 if f_0 is None else f_0
    phi = (1.0 + math.sqrt(5.0)) / 2.0
    return f0 * (phi ** n)

E_AETHER_DENSITY = 1.683e-10

def _i_ac_damped(t: float, I_0: float = 1.0, omega: float = 2.0 * math.pi * 60.0,
                  gamma: float = 0.1) -> float:
    return I_0 * math.sin(omega * t) * math.exp(-gamma * t)

def _omega_spark_lc(L: float = 1.0e-6, C: float = 1.0e-12) -> float:
    return 1.0 / math.sqrt(max(L * C, 1e-60))

def _omega_plasma_damped(omega_0: float = 1.0e16, gamma: float = 1.0e15) -> float:
    return math.sqrt(omega_0 * omega_0 + gamma * gamma)

def _exp_density_profile(r: float, rho_0: float = 1.0e-20, r_0: float = 1.0) -> float:
    return rho_0 * math.exp(-r / max(r_0, 1e-30))

def _h_mag_zeeman(mu_mag: float = 9.274e-24, B: float = 1.0e-8) -> float:
    return -mu_mag * B

