def _qscope_event_times_s(t_array, label_array, marker: str):
    if len(t_array) != len(label_array):
        raise ValueError("t_array and label_array must be same length")
    return [float(t_array[i]) for i in range(len(t_array))
            if label_array[i] == marker]

def _qscope_mean_period_s(event_times) -> float:
    if len(event_times) < 2:
        return 0.0
    diffs = [event_times[i+1] - event_times[i] for i in range(len(event_times)-1)]
    return math.fsum(diffs) / len(diffs)

def _qscope_batch_envelope(v_array, batch_array) -> Dict[int, Dict[str, float]]:
    if len(v_array) != len(batch_array):
        raise ValueError("v_array and batch_array must be same length")
    grouped: Dict[int, List[float]] = {}
    for v, b in zip(v_array, batch_array):
        grouped.setdefault(int(b), []).append(float(v))
    out: Dict[int, Dict[str, float]] = {}
    for b, vs in grouped.items():
        vmax = max(vs); vmin = min(vs); n = len(vs)
        vmean = math.fsum(vs) / n
        out[b] = {"max": vmax, "min": vmin, "mean": vmean,
                  "pp_range": vmax - vmin, "n": float(n)}
    return out

def _qscope_stability_index(v_array, batch_array,
                              reference_batch: int = 1) -> Dict[int, float]:
    if len(v_array) != len(batch_array):
        raise ValueError("v_array and batch_array must be same length")
    grouped: Dict[int, List[float]] = {}
    for v, b in zip(v_array, batch_array):
        grouped.setdefault(int(b), []).append(float(v))
    def _pop_std(xs: List[float]) -> float:
        n = len(xs)
        if n == 0:
            return 0.0
        mu = math.fsum(xs) / n
        var = math.fsum((x - mu) * (x - mu) for x in xs) / n
        return math.sqrt(var)
    ref_std = _pop_std(grouped.get(reference_batch, []))
    if ref_std == 0.0:
        return {b: 0.0 for b in grouped}
    return {b: _pop_std(vs) / ref_std for b, vs in grouped.items()}

def _qscope_cycle_summary(t_array, flow_state_array) -> Dict[str, Any]:
    frc = _qscope_event_times_s(t_array, flow_state_array, "full_reversal_cycle")
    rcc = _qscope_event_times_s(t_array, flow_state_array, "reversal_cycle_complete")
    return {
        "full_reversal_cycle_count":          len(frc),
        "full_reversal_cycle_times_s":        frc,
        "full_reversal_cycle_mean_period_s":  _qscope_mean_period_s(frc),
        "reversal_cycle_complete_count":          len(rcc),
        "reversal_cycle_complete_times_s":        rcc,
        "reversal_cycle_complete_mean_period_s":  _qscope_mean_period_s(rcc),
    }

L_SUN_W              = 3.826e26
L_OUTBURST_V838_W    = 6.0e5 * L_SUN_W
L_OUTBURST_V838_SPEC_QUOTE_W = 2.3e38

def _light_echo_radius_m(t_s: float,
                           c_m_s: float = C_LIGHT) -> float:
    return c_m_s * t_s

def _dust_density_uqff(rho_0: float,
                         beta: float,
                         U_g1_value: float) -> float:
    return rho_0 * math.exp(-beta * U_g1_value)

def _v838_light_echo_intensity_uqff(t_s: float,
                                       rho_0_dust: float = 1.0e-21,
                                       sigma_scatter: float = 1.0e-22,
                                       beta_U_g1: float = 0.0,
                                       L_outburst_W: float = L_OUTBURST_V838_W,
                                       f_TRZ: float = F_TRZ_DEFAULT,
                                       rho_UA_val: float = None,
                                       rho_SCm_val: float = None) -> float:
    rua = RHO_UA  if rho_UA_val  is None else rho_UA_val
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    r = _light_echo_radius_m(t_s)
    if r <= 0.0:
        return float('inf')
    classical = (L_outburst_W / (4.0 * math.pi * r * r)) * sigma_scatter
    rho_dust  = rho_0_dust * math.exp(-beta_U_g1)
    uqff_enh  = (1.0 + f_TRZ) * (1.0 + (rua / rsc if rsc != 0.0 else 0.0))
    return classical * rho_dust * uqff_enh

def _u_g2_heliosphere_uqff(k_2: float = 1.2,
                             rho_UA_val: float = None,
                             rho_SCm_val: float = None,
                             M_s: float = M_SUN,
                             r: float = R_J_MAGNETIC,
                             R_b: float = R_J_MAGNETIC,
                             delta_sw: float = 0.01,
                             v_sw: float = 5.0e5,
                             H_SCm: float = H_SCM_DEFAULT,
                             E_react: float = 1.0e46) -> float:
    rua = RHO_UA  if rho_UA_val  is None else rho_UA_val
    rsc = RHO_SCM if rho_SCm_val is None else rho_SCm_val
    S = 1.0 if r >= R_b else 0.0
    return (k_2 * (rua + rsc) * M_s / max(r * r, 1e-300)
            * S * (1.0 + delta_sw * v_sw) * H_SCm * E_react)

def _u_g3_string_magnetism_uqff(k_3: float = 1.8,
                                  B_j_sum: float = 1.0e3,
                                  omega_s: float = 2.5e-6,
                                  t: float = 0.0,
                                  P_core: float = 1.0,
                                  E_react: float = 1.0e46) -> float:
    return k_3 * B_j_sum * math.cos(omega_s * t * math.pi) * P_core * E_react

def _galactic_rotation_period(Omega_g: float = OMEGA_GALACTIC) -> float:
    return 2.0 * math.pi / max(abs(Omega_g), 1e-300)

def _f_u_unified(t: float = 0.0, t_n: float = 0.0,
                  U_g_list: list = None, k_list: tuple = K_GRAV_LADDER,
                  beta_i: float = BETA_I, Omega_g: float = OMEGA_GALACTIC,
                  M_bh: float = 8.15e36, d_g: float = D_GALACTIC_CENTER,
                  E_react: float = 1.0e46,
                  mu_over_r_sum: float = 0.0, gamma: float = 0.00005,
                  T_smunu: float = 1.123e7, eta: float = ETA_AETHER_COUPLING,
                  lambda_U_i_sum: float = 0.0) -> float:
    if U_g_list is None:
        U_g_list = [1.39e26, 1.18e53, 1.8e49, 2.50e-20]
    Mbh_over_dg = M_bh / max(d_g, 1e-300)
    grav_sum = 0.0
    for ki, Ugi in zip(k_list, U_g_list):
        grav_sum += ki * Ugi - beta_i * Ugi * Omega_g * Mbh_over_dg * E_react
    osc = (1.0 - math.exp(-gamma * t * math.cos(math.pi * t_n)))
    magnetic_sum = mu_over_r_sum * osc
    aether_trace = sum(_aether_metric_a_munu(T_smunu=T_smunu, eta=eta))
    inertia_term = lambda_U_i_sum * E_react
    return grav_sum + magnetic_sum + aether_trace - inertia_term

