def calculate_lenr(dataset):
    d = dataset or {}
    variant = str(d.get('variant', d.get('reactor', 'all'))).lower()
    if variant in ('all', 'full', 'report'):
        return {'value': _lenr_full_report()}
    if variant == 'holmlid':
        return {'value': _ker_scm_chain()}
    if variant == 'parkhomov':
        N = float(d.get('N_clusters', 2.0e18))
        t_h = float(d.get('t_hours', 1.0))
        return {'value': {'P_excess_W': _parkhomov_excess_heat(N, t_h)}}
    if variant in ('pons', 'pons_fleischmann', 'pf'):
        return {'value': {'P_excess_W': _pons_fleischmann_excess_heat()}}
    if variant == 'mizuno':
        return {'value': _mizuno_lenr()}
    if variant in ('rossi', 'ecat', 'rossi_early', 'early', 'x', 'sk', 'starmagic'):
        key = variant.replace('rossi_', '').replace('ecat_', '')
        if key in ('rossi', 'ecat'):
            key = 'early'
        return {'value': _rossi_ecat_cop(key)}
    return {'value': None}

