    return {"paper_id": paper_id, "coupling_uqff": coupling_uqff, "SO_5_mod_phase": pid_phase, "phi_res": PHI_RESONANCE, "D_phys_minus_1_generations": D_PHYS - 1, "domain": "particle_physics", "primary_source": f"Particle_paper_{paper_id}_via_D_phys_minus_1_x_SO_5_x_Phi_res"}

