def _whitepaper_proof(paper_id: int):
    d = WHITEPAPER_TO_DOMAIN.get(paper_id)
    if d is None:
        return None
    fn = WHITEPAPER_DOMAIN_DISPATCH.get(d)
    if fn is None:
        return None
    try:
        return fn(paper_id)
    except Exception:
        return None

def _whitepaper_inventory() -> Dict[str, Any]:
    domains = {}
    for pid, d in WHITEPAPER_TO_DOMAIN.items():
        domains.setdefault(d, []).append(pid)
    return {
        "total_whitepapers_wired_this_pass": len(WHITEPAPER_TO_DOMAIN),
        "total_domains": len(domains),
        "domain_counts": {d: len(lst) for d, lst in domains.items()},
        "paper_id_range": [min(WHITEPAPER_TO_DOMAIN), max(WHITEPAPER_TO_DOMAIN)],
    }

def calculate_paradox(dataset):
    d = dataset or {}
    name = d.get('paradox') or d.get('name')
    if name is None or str(name).lower() in ('all', 'full', 'report', 'inventory'):
        return {'value': _paradox_full_report()}
    r = _paradox_proof(str(name))
    if r is None:
        return {'value': None}
    val, prov = r
    return {'value': val}

def calculate_whitepaper(dataset):
    d = dataset or {}
    if d.get('list_inventory') or d.get('inventory') or d.get('list_supported'):
        return {'value': _whitepaper_inventory()}
    pid = d.get('paper_id') or d.get('paper') or d.get('id')
    if pid is None:
        return {'value': _whitepaper_inventory()}
    try:
        pid_int = int(pid)
    except (ValueError, TypeError):
        return {'value': None}
    result = _whitepaper_proof(pid_int)
    if result is None:
        return {'value': None}
    return {'value': result}

def calculate_analytic_closures(dataset: Dict[str, Any]) -> Dict[str, Any]:
    d = dataset or {}

    vr = d.get("vr_outfall")
    if isinstance(vr, dict):
        r_grid = vr.get("r_grid") or [DEFAULT_R]
        t_grid = vr.get("t_grid") or [0.0]
        layer_i = int(vr.get("layer_i", 1))
        sys_label = vr.get("system", "default")
        grid = [
            [_f_lenr_enhanced(float(r), float(t), layer_i, d) for r in r_grid]
            for t in t_grid
        ]
        prov = ""
        return {'value': {'grid': grid, 'axes': {'r': list(r_grid), 't': list(t_grid)}}}

    if d.get("dse") is True or "dse_channels" in d:
        ds = _dse_dispatch(d)
        return {'value': {k: v for (k, v) in ds.items() if k != 'provenance'}}

    if "f_lenr_enhanced" in d:
        cfg = d.get("f_lenr_enhanced") or {}
        r = float(cfg.get("r", d.get("r", DEFAULT_R)))
        t = float(cfg.get("t", d.get("t", 0.0)))
        li = int(cfg.get("layer_i", 1))
        val = _f_lenr_enhanced(r, t, li, d)
        return {'value': val}
    if "vds_factor" in d:
        val = _vds_factor(d)
        return {'value': val}
    if "dvp_potential" in d:
        cfg = d.get("dvp_potential") or {}
        r = float(cfg.get("r", d.get("r", DEFAULT_R)))
        t = float(cfg.get("t", d.get("t", 0.0)))
        val = _dvp_potential(r, t, d)
        return {'value': val}
    if "bh26_geometry" in d:
        cfg = d.get("bh26_geometry") or {}
        r = float(cfg.get("r", d.get("r", DEFAULT_R)))
        li = int(cfg.get("layer_i", 1))
        val = _bh26_geometry(r, li, d)
        return {'value': val}
    if "qcalcgeom_fold" in d:
        val = _qcalcgeom_fold(d)
        return {'value': val}
    if "belly_button_umbilicus" in d:
        val = _belly_button_umbilicus(d)
        return {'value': val}
    if "stationarity_residual" in d:
        lt = d.get("stationarity_residual") or {}
        val = _stationarity_residual(lt, d.get("phi_index", "phi"))
        diff_pct, diff_str = _compute_diff_pct(val, 0.0)
        return {'value': val}

    if "lagrangian_sector" in d:
        info = _lagrangian_sector_residual(d)
        paper = info.get("paper") or "UNKNOWN"
        sector = info.get("sector") or {}
        residual = info.get("residual")
        diff_str = info.get("diff_str", "diff=undefined%")
        domain = sector.get("domain", "unknown sector")
        b9 = sector.get("b9_anchor", "n/a")
        phi_index = sector.get("phi_index", d.get("phi_index", "phi"))
        prov = ""
        return {'value': info}

    def _leaf_prov(name: str, val: float, extra: str = "") -> str:
        return (
            f"universal-field leaf {name} [Plan sec 3.8 / Map sec 20.4; "
            f"Slice 3] extracted view of canonical master algebra "
            f"(_g_compressed L3036-L3047 / _g_resonance L3052 / _u_mi L3081). "
            f"UQFF={val:.6g}. {extra}."
        )
    for key, fn in (
        ("ug1",            lambda c: _ug1(float(c.get("r", d.get("r", DEFAULT_R))),
                                          int(c.get("layer_i", 1)), d)),
        ("ug2",            lambda c: _ug2(float(c.get("r", d.get("r", DEFAULT_R))),
                                          int(c.get("layer_i", 1)), d)),
        ("ug3",            lambda c: _ug3(float(c.get("r", d.get("r", DEFAULT_R))),
                                          float(c.get("t", d.get("t", 0.0))),
                                          int(c.get("layer_i", 1)), d)),
        ("ug4",            lambda c: _ug4(float(c.get("r", d.get("r", DEFAULT_R))),
                                          int(c.get("layer_i", 1)), d)),
        ("u_i",            lambda c: _u_i(float(c.get("r", d.get("r", DEFAULT_R))),
                                          int(c.get("layer_i", 1)), d)),
        ("u_m",            lambda c: _u_m(float(c.get("t", d.get("t", 1.0))),
                                          float(c.get("r", d.get("r", DEFAULT_R))),
                                          int(c.get("n", 1)), d)),
        ("u_b",            lambda c: _u_b(float(c.get("r", d.get("r", DEFAULT_R))), d)),
        ("f_env_layer27",  lambda c: _f_env_layer27(float(c.get("r", d.get("r", DEFAULT_R))), d)),
        ("h_res",          lambda c: _h_res(int(c.get("n", 1)), d)),
        ("a_res",          lambda c: _a_res(d)),
        ("f_res",          lambda c: _f_res(int(c.get("n", 1)), d)),
        ("u_dp",           lambda c: _u_dp(d)),
        ("k_nuc",          lambda c: _k_nuc(d)),
        ("s_shell",        lambda c: _s_shell(float(c.get("r", d.get("r", DEFAULT_R))), d)),
    ):
        if key in d:
            cfg = d.get(key)
            cfg = cfg if isinstance(cfg, dict) else {}
            val = fn(cfg)
            return {'value': val}

    if "spinor" in d or d.get("closure") == "spinor":
        info = _spinor_closure()
        prov = ""
        return {'value': info}

    pid = d.get("prediction") or d.get("p")
    if isinstance(pid, str) and pid.strip():
        out = _prediction(pid)
        if out is not None:
            pval, pprov = out
            return {'value': pval}

    return _resolve_uqff_ledger(d)

